            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Genetically higher sebaceous activity in T-zone", "Climate/hormonal fluctuations affecting regional oil balance"], "score_explanation": "White light shows higher specular shine on the T-zone versus matte cheeks (estimated shine_T-zone − shine_cheeks ≈ 0.3+). UV imaging reveals porphyrin fluorescence localized predominantly to the nose and central forehead while cheeks remain relatively low, matching a T-zone-only fluorescence pattern. PPL mode demonstrates moderate/enlarged pores confined to the T-zone with smaller pores over the cheeks and reasonable texture uniformity laterally. Applying the weighted confidence (white 0.45, UV 0.35, PPL 0.20), the criteria align best with Combination Skin per decision logic (T-zone shine contrast ≥0.3, UV fluorescence ≥40 in T-zone and <25 on cheeks, and pore size moderate/enlarged centrally but small laterally).", "affected_area_image": "6"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "1 - Mildly Compromised Barrier", "possible_causes": ["Insufficient lipid/ceramide support in routine", "Frequent cleansing or irritant exposure"], "score_explanation": "PPL shows slight texture unevenness (surface_texture_uniformity ~0.75–0.80). White-mode hydration_signal_index is modest (~0.50–0.60). Redness_intensity_index ~0.30–0.35 with minimal flaking_visibility_index <0.3. Weighted global barrier index corresponds to mild compromise (Score 1).", "affected_area_image": "3"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "1 - Mild Dehydration", "possible_causes": ["Insufficient use of humectants/occlusives or low ambient humidity", "Cleansing or actives that temporarily impair water retention"], "score_explanation": "White-mode surface_reflectance_index is modest (~0.55–0.60), PPL microline_density_index ~0.18–0.22 (mild), and red-mode subsurface_diffusion_index ~0.60–0.65 (moderate). Color/luminance uniformity slightly patchy (~0.7–0.8). Weighted hydration index maps to mild dehydration (Score 1).", "affected_area_image": "6"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Early collagen/elastin decline with age", "Weight or fluid shifts affecting lower-face contour"], "score_explanation": "White/XPL contour analysis indicates slightly blunted mandibular edges with a small jowl prominence near the mandibular angle. Estimated mandibular_angle_change ~7° (5–10° mild) and contour_smoothness_index ~0.75–0.80. Skin_laxity_index appears in the mild range (~0.3–0.4). Overall metrics align with mild sagging (Grade 2).", "affected_area_image": "6"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure without lip SPF", "Habits such as smoking or chronic lip dryness"], "score_explanation": "Brown/XPL views show lips slightly darker than adjacent perioral skin with a uniform-to-slightly patchy pattern, consistent with mild lip pigmentation.", "affected_area_image": "2"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "1 - Mild Comedonal Activity", "possible_causes": ["Occlusive cosmetics or incomplete makeup removal", "Increased keratinization and sebum in T-zone follicles"], "score_explanation": "PPL/white detection shows scattered comedones mainly in T-zone with comedone_count_density ~0.08–0.12 (mild) and comedone_cluster_index ~0.3 (scattered). UV porphyrin_overlap_index ~0.25–0.30 supports active but mild follicular congestion. Global index maps to Score 1.", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Mild", "possible_causes": ["Genetic thin peri-orbital skin with visible vasculature", "Sleep insufficiency or transient fluid shifts"], "score_explanation": "XPL/white inspection shows faint under-eye pigmentation with subtle vascular hue and mild tear-trough definition. Puffiness is minimal. Overall composite across puffiness, hollowness, pigmentation, and vascularity is mild.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "2 - Moderate / Normal-Oily", "possible_causes": ["Overactive sebaceous glands in T-zone", "Diet, stress, or heat increasing sebum output"], "score_explanation": "White light shows a noticeable T-zone sheen with normalized shine_reflectance ~0.58, and UV reveals moderate porphyrins (porphyrin_fluorescence_index ~45–55). Sebum_quantity_index ≈ 0.55–0.60. Distribution is T-zone dominant with sebum_distribution_index ~0.25–0.30. Global_sebum_index ≈ (0.8×~0.58) + (0.2×~0.28) ≈ ~0.52–0.56, mapping to Score 2.", "affected_area_image": "6"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["Comedogenic or occlusive skincare/makeup", "Mild hormonal fluctuations increasing T-zone keratinization"], "score_explanation": "White/UV modes show few comedones clustered in the T-zone with sparse scattered lesions elsewhere (estimated total lesion count ~5–8, meeting 3–10 for Grade 1). Inflammatory elements are minimal with inflammatory_ratio <0.25 (few papules/pustules, no nodules). Region contribution is T-zone weighted, but overall region-weighted severity remains low, aligning with Grade 1.", "affected_area_image": "6"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Cumulative UV exposure reducing collagen/elastin", "Transient dehydration accentuating fine lines"], "score_explanation": "XPL/PPL reveal fine dynamic lines on the forehead and peri-orbital crow’s feet visible at rest. Estimated wrinkle_depth_index ~0.30–0.40 (mild) and wrinkle_density_index ~0.25–0.35 (mild). White-mode contrast remains moderate, supporting a mild classification rather than moderate.", "affected_area_image": "3"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "1 - Mild Sensitivity", "possible_causes": ["Over-exfoliation or frequent actives (AHAs/retinoids)", "Environmental triggers such as heat or wind"], "score_explanation": "Red-mode reveals faint cheek erythema (erythema_intensity_index ~0.30–0.35). PPL shows subtle vascular visibility (vascular_pattern_index ~0.25–0.30) without prominent telangiectasia. Barrier_uniformity_index remains slightly reduced (~0.75–0.8). Weighted global sensitivity falls into the mild range (Score 1).", "affected_area_image": "4"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "1 - T-zone Predominant", "possible_causes": ["Higher density/size of sebaceous glands in T-zone", "Hormonal pattern influencing central facial oiliness"], "score_explanation": "White-mode regional reflectance shows higher values in forehead, nose, and chin versus cheeks with regional_variance_index ~0.30. UV porphyrin_distribution_index ~0.35 localized centrally and good bilateral symmetry (shine_symmetry_index <0.4). Pattern fits T-zone predominant distribution (Score 1).", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "2 - Healthy Glow / Moderate Luminosity", "possible_causes": ["Slight dehydration and mild pigmentation limiting peak radiance", "Subtle texture irregularities dispersing reflection"], "score_explanation": "White-mode surface_reflectance_uniformity ~0.72–0.78 (high-moderate), color_luminance_index ~0.65–0.70 (bright), subsurface_diffusion_index ~0.60–0.65 (moderate), and shadow_contrast_index ~0.35 (soft-moderate). Weighted indices yield a global luminosity consistent with a healthy, moderate glow (Score 2).", "affected_area_image": "6"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Higher T-zone sebum output enlarging follicular openings", "Genetic predisposition to visible pores in central face"], "score_explanation": "PPL mode shows pores that are visible beyond the nose onto the medial cheeks with an estimated pore_diameter_ratio ~1.4–1.5× (mild: 1.3–1.6). Texture uniformity index is mildly reduced (~0.65–0.75), consistent with mild roughness. White-mode reflection shows minor mottling without coarse breakup. The global texture index maps to Grade 2.", "affected_area_image": "3"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "1 - Mild", "possible_causes": ["Sun/heat exposure causing reactive vasodilation", "Mild irritant sensitivity or early rosacea tendency"], "score_explanation": "Red-mode erythema_intensity_index ~0.35–0.40 and PPL vascular_pattern_density ~0.25–0.35 with even distribution symmetry and decent color uniformity (~0.75–0.8). The global vascularity index indicates mild redness, mainly over cheeks and nose, without dense telangiectasia.", "affected_area_image": "4"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "2 - Mild", "possible_causes": ["Sun exposure and UV-induced melanogenesis", "Post-inflammatory hyperpigmentation after minor breakouts"], "score_explanation": "Brown light reveals scattered faint macules on the forehead and malar areas with coverage estimated around 10–15% (within the 5–20% mild range). Mean intensity index appears ~0.40–0.48 (mild: 0.35–0.50) and contrast uniformity ~0.78–0.82 (near the 0.75–0.85 mild band). UV enhancement is present but limited, suggesting a mainly epidermal-to-mixed depth (depth indicator ratio ~0.40). Weighted aggregation of coverage, intensity, homogeneity, and border definition maps to a global score in the mild bin (2).", "affected_area_image": "2"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "1 - Mild", "possible_causes": ["Subclinical micro-scarring from past breakouts", "Episodic dehydration affecting surface uniformity"], "score_explanation": "PPL variance indicates microtexture_variance_index ~0.35–0.45 (mild) with surface_gradient_irregularity ~0.30–0.40 and shallow shadow_depth_index ~0.25–0.35. Diffuse_reflection_loss_index is low to moderate. Combined weights produce a mild texture irregularity score (1).", "affected_area_image": "3"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "1 - Mild", "possible_causes": ["Thin peri-orbital skin with superficial vessels", "Early anatomical hollowness accentuating shadows"], "score_explanation": "XPL reveals faint bluish vascular hue with mild shadowing along the tear trough; UV does not show pronounced deep dermal involvement. Pattern fits Score 1 (mild vascular pigmentation with minimal structural shadow).", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "2 - Mild"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1 - Very Mild"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0–1", "current_score": "Grade 2 - Mild"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 2 - Mild"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 2 - Mild"}, {"parameter": "Skin Hydration", "target_score": "0 - Excellent Hydration", "current_score": "1 - Mild Dehydration"}, {"parameter": "Skin Sebum Content", "target_score": "1 - Low-Normal Sebum", "current_score": "2 - Moderate / Normal-Oily"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 - No Sensitivity", "current_score": "1 - Mild Sensitivity"}, {"parameter": "Barrier Health", "target_score": "0 - Strong / Healthy Barrier", "current_score": "1 - Mildly Compromised Barrier"}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Mild"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0 - No Vascularity / Redness", "current_score": "1 - Mild"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "0 - None", "current_score": "1 - Mild"}, {"parameter": "Comedonal Density", "target_score": "0 - No Comedones", "current_score": "1 - Mild Comedonal Activity"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0 - Smooth / Even Texture", "current_score": "1 - Mild"}, {"parameter": "Regional Oil Distribution", "target_score": "0 - Even / Balanced Oil Distribution", "current_score": "1 - T-zone Predominant"}]}}',
