            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Regional sebaceous activity concentrated in T‑zone", "Environmental humidity and routine leading to mixed oiliness/dryness"], "score_explanation": "White light (image 1) shows noticeable specular shine on nose and central forehead with comparatively matte cheeks, indicating localized T‑zone shine (shine_reflectance_ratio high in T‑zone, low on cheeks). UV/Woods (images 4–5) reveal clustered porphyrin fluorescence mainly over nose and central forehead with low cheek fluorescence (porphyrin_fluorescence_pattern T‑zone only). PPL (image 2) shows enlarged pores confined to T‑zone while cheeks display small pores and smoother texture. These satisfy the combination-skin logic where shine and porphyrins are elevated in the T‑zone but low on cheeks.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "1 - Mildly Compromised Barrier", "possible_causes": ["Suboptimal moisturization and cleanser overuse", "Infrequent sunscreen leading to barrier stress"], "score_explanation": "PPL (image 2) shows mild surface roughness with texture_uniformity ~0.75. White mode hydration signal is slightly low (~0.55) and redness index mild (~0.3) with minimal micro‑flaking. Weighted indices map to a mildly compromised barrier (score 1).", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "2 - Moderate Dehydration", "possible_causes": ["Inadequate moisturization or transepidermal water loss", "Air‑conditioned environments and low water intake"], "score_explanation": "White light (image 1) shows patchy, matte areas with reduced glow (surface_reflectance_index ~0.40–0.50). PPL (image 2) reveals increased micro‑line texture around lips/cheeks (microline_density_index ~0.25–0.32). Red mode (image 6) shows only moderate subsurface diffusion (~0.6). Together these meet score 2 thresholds.", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["Normal age-related tissue support", "Healthy weight and skin elasticity"], "score_explanation": "White/XPL (images 1 and 8) show a relatively sharp mandibular contour with minimal jowl formation; mandibular_angle_change is visually <5° and contour_smoothness_index high (>0.85). No significant submandibular shadowing.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure without lip SPF", "Post‑inflammatory or frictional darkening; possible dehydration"], "score_explanation": "Brown/UV images (7 and 6) show lips slightly darker than adjacent skin with patchy tone along vermilion border, consistent with mild lip hyperpigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "2 - Moderate", "possible_causes": ["Follicular keratinization with sebum retention", "Makeup residue or occlusive skincare"], "score_explanation": "PPL (image 2) detects multiple comedonal openings over forehead and nose; UV (image 4) shows moderate porphyrin overlap at these sites. Estimated comedone_count_density ~0.18–0.25 (6–9/cm²) with cluster_index ~0.45 and porphyrin_overlap ~0.3–0.4, matching score 2.", "affected_area_image": "4"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Mild", "possible_causes": ["Genetic predisposition to under‑eye pigmentation", "Sleep deficit or screen fatigue"], "score_explanation": "XPL (image 8) reveals subtle infra‑orbital darkening with mild medial hollowness and minimal puffiness; pigmentation/vascular component is present but not dense. Overall peri‑orbital concerns are mild.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "2 - Moderate / Normal-Oily", "possible_causes": ["Genetic sebaceous activity", "Hormonal fluctuations and occlusive products"], "score_explanation": "White (image 1) shows noticeable shine on nose/central forehead (shine_reflectance_index ~0.6). UV/Woods (images 4–5) show multiple porphyrin dots clustered on the nose and central face (porphyrin_fluorescence_index ~0.55). Calculated sebum_quantity_index ≈ 0.55–0.60 and distribution index indicates T‑zone focus (~0.30). Global index maps to score 2.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Sebaceous activity in T‑zone with follicular plugging", "Irregular cleansing or comedogenic products"], "score_explanation": "White/PPL images (1–2) show ~12–18 lesions predominantly as open/closed comedones on forehead with a few small papules; no nodules or cysts. UV (4) shows moderate porphyrin clustering in the T‑zone supporting active comedonal activity. Inflammatory ratio estimated ~0.25–0.35. This maps to Grade 2 (11–25 total lesions with modest inflammation), borderline from Grade 1 due to count and scattered papules.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["Early expression lines from facial movement", "Transient dehydration"], "score_explanation": "PPL/XPL views (images 2 and 8) display mostly smooth skin with only faint fine lines around peri‑orbital/forehead on close inspection; wrinkle_depth_index appears <0.25 and density low (<0.2). A forehead linear mark appears to be a scar rather than etched wrinkle. Hence very mild.", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "1 - Mild Sensitivity", "possible_causes": ["Occasional irritant exposure or over‑cleansing", "Environmental heat or friction"], "score_explanation": "Red light (image 6) shows faint, persistent erythema on cheeks and around nostrils with low vessel prominence on PPL (image 2). Estimated erythema_intensity_index ~0.3 and vascular_pattern_index <0.3 with near‑intact barrier uniformity. This aligns with mild sensitivity.", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "1 - T-zone Predominant", "possible_causes": ["Higher sebaceous gland density in T‑zone", "Habitual touching of nose/forehead increasing oiliness"], "score_explanation": "UV (image 4) demonstrates porphyrin clustering centered on nose and central forehead with relatively sparse fluorescence on cheeks; white light (image 1) shows corresponding localized shine. Indices indicate regional_variance_index ~0.3 and porphyrin_distribution_index ~0.35, consistent with T‑zone pattern (score 1).", "affected_area_image": "4"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "1 - Mild Glow", "possible_causes": ["Dehydration reducing light scatter", "Superficial pigmentation and mild texture reducing radiance"], "score_explanation": "White mode (image 1) shows moderate reflectance uniformity (~0.6) with patchy brightness; PPL (image 2) indicates slight surface dullness and uneven highlight distribution. Subsurface diffusion appears moderate (~0.6). Weighted glow indices map to score 1.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Higher local sebum output stretching follicular openings", "Past acne and inadequate exfoliation"], "score_explanation": "PPL (image 2) highlights visible pores on nose and medial cheeks; cheeks laterally remain fine. Estimated pore_diameter_ratio ~1.4–1.6 on nose with texture_uniformity_index ~0.65–0.75 and minor reflectance mottling on white light (image 1). This matches Grade 2 criteria (moderate pore enlargement with mild roughness).", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "1 - Mild", "possible_causes": ["Heat, rubbing, or cleanser-induced transient flushing", "Barrier mild compromise increasing reactivity"], "score_explanation": "Red mode (image 6) indicates mild diffuse erythema across cheeks and nose; PPL (image 2) shows minimal linear vessel enhancement. Indices: erythema_intensity_index ~0.30–0.35, vascular_pattern_density ~0.25–0.30, color_uniformity moderate. Global vascularity index maps to score 1.", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "3 - Moderate", "possible_causes": ["Cumulative sun exposure and tanning", "Post‑inflammatory hyperpigmentation from past acne"], "score_explanation": "Brown mode (image 7) shows mottled macules across forehead, peri‑oral and cheek areas with estimated coverage ~25–35% of face (moderate). Mean intensity of darker patches is mid‑contrast (~0.50–0.60) and uniformity is uneven to moderate (contrast_uniformity_index ~0.70). UV enhancement is limited, suggesting predominantly epidermal/mixed depth. Pattern aligns with score 3 definitions: visible macules and mottling on multiple regions without confluent severe darkening.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "1 - Mild", "possible_causes": ["Post‑inflammatory changes from past acne", "Dehydration leading to transient roughness"], "score_explanation": "PPL (image 2) shows fine surface roughness and subtle micro‑shadowing along previous acne areas; microtexture_variance_index ~0.4 and surface_gradient_irregularity ~0.3 with shallow shadows. These meet mild irregularity criteria.", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2 - Moderate", "possible_causes": ["Thin under‑eye skin revealing vasculature", "Early tear‑trough hollowing and lifestyle fatigue"], "score_explanation": "XPL (image 8) reveals a bluish‑brown hue along the tear trough with discernible inner corner shadows, suggesting combined vascular pigmentation and mild hollowness. The darkness is noticeable beyond faint (score 1) but without severe confluent dark circles, consistent with score 2.", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1–2 (Minimal to Mild)", "current_score": "3 - Moderate"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0–1", "current_score": "Grade 2 - Mild"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0–1", "current_score": "Grade 2 - Mild"}, {"parameter": "Skin Hydration", "target_score": "0–1 (Excellent to Mild)", "current_score": "2 - Moderate Dehydration"}, {"parameter": "Skin Sebum Content", "target_score": "1 (Low-Normal)", "current_score": "2 - Moderate / Normal-Oily"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 (No 