            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Dry Skin", "possible_causes": ["Age-related decline in sebaceous output", "Environmental dehydration or inadequate barrier lipids"], "score_explanation": "White-light view (image 3) shows a predominantly matte surface with minimal specular highlights (shine_reflectance_ratio <0.3). UV/Woods (images 5/4) display sparse porphyrin fluorescence (<20) and PPL (image 2) shows fine micro-lines with small pores. The weighted criteria (white>UV>PPL) meet the Dry Skin definition.", "affected_area_image": "3"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "Score 1", "possible_causes": ["Low lipid content but improving hydration", "Cumulative sun exposure"], "score_explanation": "PPL (image 2) shows relatively uniform surface with mild roughness; white (3) indicates acceptable hydration signal (~0.5) and only mild erythema. Weighted indices place barrier in mildly compromised range (Score 1).", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "Score 1", "possible_causes": ["Suboptimal stratum corneum water content", "Low ambient humidity or inadequate emollients"], "score_explanation": "White (image 3) shows slightly improved reflectance (0.50–0.60) and PPL (2) shows lower microline density (~0.18–0.22). Red mode (6) shows moderate subsurface diffusion. Aggregated hydration index corresponds to Mild Dehydration (Score 1).", "affected_area_image": "3"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 3", "possible_causes": ["Age-related soft tissue descent and ligament laxity", "Loss of dermal elasticity"], "score_explanation": "White-light (image 3) shows jowl prominence and blunted mandibular outline with submandibular shadowing. Estimated mandibular angle change ~10–15° and contour_smoothness_index ~0.6 → Moderate sagging (Grade 3).", "affected_area_image": "3"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure without lip SPF", "Post‑inflammatory changes or habitual factors"], "score_explanation": "Brown (image 7) and white (3) show lips darker than surrounding skin with uneven tone, consistent with detectable lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "Score 0", "possible_causes": ["Effective cleansing and low sebum output", "Regular exfoliation minimizing keratin plugs"], "score_explanation": "UV (image 5) shows very few isolated fluorescence dots and PPL (2) lacks clustered follicular plugs. Overall comedone_count_density <0.05 with isolated pattern → No Comedones (Score 0).", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Vascular visibility in thin infraorbital skin", "Tear‑trough hollowing with chronic pigmentation"], "score_explanation": "Under‑eye region shows persistent dark circles with brown‑bluish hue and structural shadowing; visible in white (3) and accentuated under UV/Woods (5/4). Puffiness minimal, hollowness mild‑moderate → overall Moderate.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "Score 1", "possible_causes": ["Age‑related reduction in sebaceous activity", "Use of gentle cleansers controlling oil"], "score_explanation": "White mode (3) displays minimal shine and UV (5) shows few scattered porphyrin dots mostly in T‑zone. Estimated sebum_quantity_index ~0.35–0.45 with distribution_index <0.3 → Low‑Normal (Score 1).", "affected_area_image": "3"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 0", "possible_causes": ["Well-controlled comedones", "Low sebum with regular cleansing"], "score_explanation": "White/PPL (images 3/2) reveal no active papules or pustules and fewer than three comedonal lesions overall; UV (5) shows minimal isolated porphyrin dots. Total lesion count <3 and inflammatory_ratio <0.1 → Grade 0 (Clear).", "affected_area_image": "3"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 2", "possible_causes": ["Collagen/elastin reduction from photoaging", "Surface dehydration accentuating fine lines"], "score_explanation": "PPL (image 2) and white (3) show multiple fine lines on forehead and peri‑orbital area visible at rest but not deep; estimated wrinkle_depth_index 0.25–0.45 and density_index 0.2–0.4 → Mild (Grade 2).", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "Score 1", "possible_causes": ["Transient flushing and mild dryness", "Environmental triggers/cleansers"], "score_explanation": "Red mode (image 6) shows faint malar erythema without dense capillary patterns; barrier uniformity is acceptable. Erythema_intensity_index ~0.3–0.4 and vascular_pattern_index <0.3 indicate Mild sensitivity.", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "Score 1", "possible_causes": ["Physiologic sebaceous predominance in T‑zone", "Localized product application patterns"], "score_explanation": "White (3) and UV (5) demonstrate slightly higher reflectance/porphyrins on forehead and nose relative to cheeks; cheeks remain matte. Regional_variance_index ~0.25–0.35 with T‑zone focused porphyrins ~0.3–0.4 → T‑zone Predominant (Score 1).", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "Score 1", "possible_causes": ["Residual dehydration and pigmentation scattering light", "Gradual barrier recovery"], "score_explanation": "White (image 3) shows modest, slightly uneven reflectance (surface_reflectance_uniformity ~0.55–0.6) and improved luminance (~0.45–0.5) versus dull baseline; subsurface diffusion moderate. This aligns with Mild Glow (Score 1).", "affected_area_image": "3"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 1", "possible_causes": ["Physiologic follicular size in T‑zone", "Mild photoaging-related texture change"], "score_explanation": "PPL (image 2) shows fine pores mainly limited to nose/medial cheeks with minor unevenness; pore_diameter_ratio ~1.1–1.3× and texture_uniformity_index ~0.75–0.85. This corresponds to Very Mild (Grade 1).", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "Score 1", "possible_causes": ["Background flushing/reactivity", "Mild photo‑induced vascular prominence"], "score_explanation": "Red mode (image 6) demonstrates low‑grade diffuse cheek redness with minimal linear vessel enhancement and near‑even color uniformity (0.6–0.8). Global vascularity index → Mild (Score 1).", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "3 - Moderate", "possible_causes": ["Chronic photoexposure and lentigines", "Post‑inflammatory hyperpigmentation"], "score_explanation": "Brown mode (image 7) shows multiple macules and patches across forehead, malar and perioral zones covering ~20–40% area. Mean darkness appears in the 0.50–0.65 band with mottled distribution (contrast_uniformity_index ~0.7). UV (5) modestly enhances some spots → mixed superficial depth. These fall in the \'Moderate\' bin.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "Score 1", "possible_causes": ["Photoaging with light undulation", "Resolved acne/PIH with subtle texture residues"], "score_explanation": "PPL (image 2) reveals minor micro‑roughness with mostly even reflection; brown (7) shows shallow micro‑shadows. Indices suggest microtexture_variance ~0.35–0.45 and surface_gradient_irregularity ~0.3–0.4 → Mild irregularities (Score 1).", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2", "possible_causes": ["Vascular congestion with thin skin", "Tear‑trough hollowing causing fixed shadow"], "score_explanation": "Infraorbital area shows bluish‑brown tint persistent across modes with noticeable shadow curve at the tear trough; UV (5) slightly enhances pigment. Mixed vascular and structural etiology corresponds to Moderate (Score 2).", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Skin Type", "target_score": "Normal/Balanced Skin", "current_score": "Dry Skin"}, {"parameter": "Superficial Pigmentation Score", "target_score": "1–2 (Minimal to Mild)", "current_score": "3 - Moderate"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0–1 (Smooth to Very Mild)", "current_score": "Grade 1"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 (Very Mild)", "current_score": "Grade 2"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 (Very Mild)", "current_score": "Grade 3"}, {"parameter": "Skin Hydration", "target_score": "Score 0 (Excellent Hydration)", "current_score": "Score 1"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0 (No Sensitivity)", "current_score": "Score 1"}, {"parameter": "Barrier Health", "target_score": "Score 0 (Strong / Healthy Barrier)", "current_score": "Score 1"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0–1", "current_score": "Score 2"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3 (Healthy to Radiant)", "current_score": "Score 1"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0–1 (Smooth)", "current_score": "Score 1"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 (Even / Balanced)", "current_score": "Score 1"}]}}',
