            'parameters_with_abnormal_scores' => '{"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Skin Type", "target_score": "Normal/Balanced Skin", "current_score": "Dry Skin"}, {"parameter": "Superficial Pigmentation Score", "target_score": "1–2 (Minimal to Mild)", "current_score": "3 - Moderate"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0–1 (Smooth to Very Mild)", "current_score": "Grade 1"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 (Very Mild)", "current_score": "Grade 2"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 (Very Mild)", "current_score": "Grade 3"}, {"parameter": "Skin Hydration", "target_score": "Score 0 (Excellent Hydration)", "current_score": "Score 1"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0 (No Sensitivity)", "current_score": "Score 1"}, {"parameter": "Barrier Health", "target_score": "Score 0 (Strong / Healthy Barrier)", "current_score": "Score 1"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0–1", "current_score": "Score 2"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3 (Healthy to Radiant)", "current_score": "Score 1"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0–1 (Smooth)", "current_score": "Score 1"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 (Even / Balanced)", "current_score": "Score 1"}]}',
