            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Regional sebaceous activity differences (T‑zone > cheeks)", "Environmental factors and cleansing patterns leading to uneven oil balance"], "score_explanation": "White mode shows localized T‑zone shine with reflectance notably higher on forehead/nose than cheeks (approx R_T-zone ~0.55 vs R_cheeks ~0.30). UV mode (image 4) reveals clustered porphyrin fluorescence mainly on the nose indicating oilier T‑zone while cheeks remain low. PPL view (image 3) shows pore diameter ratio moderate on the nose (~1.4×) but small on cheeks (~1.1×). This pattern meets the Combination criteria (shine localized to T‑zone, UV fluorescence T‑zone only, pores enlarged/moderate centrally and small laterally).", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "Score 1 - Mildly Compromised Barrier", "possible_causes": ["Under‑moisturization and over‑cleansing", "Intermittent exposure to dry indoor air"], "score_explanation": "PPL indicates mild roughness with mostly smooth texture (surface_texture_uniformity ≈0.75–0.8). Hydration signal from white light is slightly low (≈0.55–0.60). Redness intensity low‑mild (~0.3) and fine flaking visible on upper forehead. Weighted indices map to Score 1.", "affected_area_image": "3"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "Score 1 - Mild Dehydration", "possible_causes": ["Inadequate moisturization or transepidermal water loss", "Air‑conditioned environment or low water intake"], "score_explanation": "White mode indicates moderate surface reflectance (surface_reflectance_index ≈0.55–0.60) without strong glow; PPL shows slight micro‑line presence (microline_density ~0.18–0.22). Red/blue channels suggest moderate subsurface diffusion (≈0.60). Weighted indices map to global hydration consistent with Score 1 (mild dehydration).", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["Normal age‑related soft tissue changes", "Mild skin laxity due to dehydration or sleep posture"], "score_explanation": "White/XPL views show a largely straight mandibular contour with only slight softness near the mandibular angle; estimated mandibular_angle_change <5° and contour_smoothness_index >0.85 with minimal submandibular shadowing. This corresponds to Grade 1 - Very Mild.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure and post‑inflammatory pigmentation around the mouth", "Habitual lip licking or irritation"], "score_explanation": "Brown mode (image 7) and UV/white views show darker tone along the upper lip and vermilion border relative to surrounding skin, consistent with lip/perioral pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "Score 1 - Mild Comedonal Activity", "possible_causes": ["Sebum accumulation and incomplete cleansing of T‑zone", "Comedogenic residues or occlusion around the nose"], "score_explanation": "UV (image 4) demonstrates porphyrin speckles concentrated at the nose with sparse distribution elsewhere. Estimated comedone_count_density in the nose region within 0.05–0.15 and cluster index ~0.3–0.4, with limited overlap beyond T‑zone. Global index yields Score 1.", "affected_area_image": "4"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Periorbital hyperpigmentation and vascular visibility", "Lifestyle factors like sleep insufficiency or rubbing"], "score_explanation": "Across XPL/white (images 2 and 1), there is visible under‑eye darkening with a brown‑gray hue and mild trough definition; vascular tint is present but not severe. Composite assessment: pigmentation = moderate, vascularity = mild‑moderate, puffiness = mild, hollowness = mild. Overall severity classified as Moderate.", "affected_area_image": "2"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "Score 2 - Moderate / Normal-Oily", "possible_causes": ["Genetic sebaceous activity higher in T‑zone", "Climate/heat prompting increased oiliness"], "score_explanation": "White mode shows moderate T‑zone sheen (shine_reflectance_index ≈0.55). UV (image 4) reveals multiple porphyrin dots concentrated on the nose (porphyrin_fluorescence_index ≈50–60). Computed sebum_quantity_index ≈0.55–0.60 and distribution index indicates T‑zone predominance (0.25–0.35). Global index maps to visible Score 2.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["T‑zone oiliness leading to comedone formation", "Occasional occlusion or comedogenic products"], "score_explanation": "White/PPL views show very few active lesions with scattered comedones primarily on the nose; inflammatory papules/pustules are minimal. Total lesion count estimated <10 with inflammatory ratio <0.25. UV (image 4) shows porphyrin speckles confined mainly to the nose without widespread clustering. This meets Grade 1 - Very Mild.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["Early photoaging and expressions creating fine dynamic lines", "Mild surface dehydration accentuating micro‑lines"], "score_explanation": "PPL/XPL images (image 3) show faint dynamic lines with very low depth and density (wrinkle_depth_index <0.25; density <0.2). Lines are visible only on close inspection; white-light reflection remains smooth. This fits Grade 1 - Very Mild.", "affected_area_image": "3"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "Score 1 - Mild Sensitivity", "possible_causes": ["Occasional product irritation or cleansing friction", "Environmental temperature changes causing transient flushing"], "score_explanation": "Red mode (image 8) shows faint erythema over cheeks/nasolabial area with low vascular pattern visibility; estimated erythema_intensity_index ~0.30–0.35 and vascular_pattern_index <0.3 while barrier_uniformity remains slightly reduced. These fall in the Mild sensitivity band.", "affected_area_image": "8"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "Score 1 - T-zone Predominant", "possible_causes": ["Physiologic T‑zone sebaceous dominance", "Makeup/sunscreen buildup centrally"], "score_explanation": "UV (image 4) shows porphyrin and shine concentrated on nose/central forehead with matte cheeks. Regional variance index ≈0.25–0.35 and porphyrin distribution index ≈0.30–0.40 with balanced symmetry. This pattern corresponds to Score 1 (T‑zone predominant).", "affected_area_image": "4"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "Score 1 - Mild Glow", "possible_causes": ["Mild dehydration reducing optical scatter", "Superficial pigmentation and texture reducing uniform reflection"], "score_explanation": "White mode indicates moderate surface reflectance uniformity (~0.55–0.65) and color luminance index around 0.5 with subsurface diffusion near 0.6; shadow contrast is moderate. These values correspond to a Mild glow (Score 1) rather than Healthy/Radiant.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Increased central facial sebum output enlarging follicular openings", "Dehydration causing transient roughness and pore visibility"], "score_explanation": "PPL/XPL analysis (image 3) shows visible pores on nose and medial cheeks with pore_diameter_ratio ~1.3–1.5× baseline and texture_uniformity_index ~0.65–0.8. Reflection pattern is slightly uneven but not coarse. These values correspond to the Mild category (grade 2).", "affected_area_image": "3"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "Score 1 - Mild Vascularity / Redness", "possible_causes": ["Reactive flushing or mild barrier compromise", "Environmental heat or spicy food triggers"], "score_explanation": "Red/PPL modes (image 8) show faint cheek and perinasal erythema with low vessel definition. Estimated indices: erythema_intensity_index ≈0.35, vascular_pattern_density ≈0.25–0.30, color_uniformity ~0.75. The weighted global_vascularity_index maps to Score 1.", "affected_area_image": "8"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "3 - Moderate", "possible_causes": ["Cumulative UV exposure and tanning response", "Post‑inflammatory hyperpigmentation and hormonal influences"], "score_explanation": "Brown mode (image 7) shows uneven tone across forehead, periorbital and perioral zones with macular patches occupying roughly 25–35% of visible area (coverage_area in the moderate bin). Mean intensity appears mid‑level (≈0.52–0.58) and uniformity shows mottling (contrast_uniformity ≈0.70). UV does not show deep, generalized enhancement (suggesting mostly superficial/mixed). According to scoring bins and weighted aggregation, this maps to Score 3 - Moderate.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "Score 1 - Mild Textural Irregularities", "possible_causes": ["Dehydration‑related dullness and prior minor breakouts", "Daily friction from masks or towels causing micro‑roughness"], "score_explanation": "PPL view (image 3) shows mild micro‑texture variance (~0.35–0.45) and slightly undulated gradients (~0.3–0.4) without deep shadows. Diffuse reflection loss is minimal. These values fit Score 1.", "affected_area_image": "3"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2 - Moderate", "possible_causes": ["Periorbital vascular congestion and thin skin", "Anatomical tear‑trough contour creating shadowing"], "score_explanation": "XPL/white (image 2) shows bluish‑brown under‑eye hue with appreciable darkness accentuated medially and along tear troughs; UV adds mild enhancement indicating vascular contribution rather than purely structural. This aligns with Score 2 (vascular pigmentation with mild hollowing).", "affected_area_image": "2"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Skin Type", "target_score": "Normal/Balanced Skin", "current_score": "Combination Skin"}, {"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "3 - Moderate"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1 - Very Mild"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0 - Clear / Smooth", "current_score": "Grade 2 - Mild"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 or lower appearance", "current_score": "Grade 1 - Very Mild"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 or sharper contour", "current_score": "Grade 1 - Very Mild"}, {"parameter": "Skin Hydration", "target_score": "Score 0 - Excellent Hydration", "current_score": "Score 1 - Mild Dehydration"}, {"parameter": "Skin Sebum Content", "target_score": "Score 1 - Low-Normal", "current_score": "Score 2 - Moderate / Normal-Oily"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0 - No Sensitivity", "current_score": "Score 1 - Mild Sensitivity"}, {"parameter": "Barrier Health", "target_score": "Score 0 - Strong / Healthy Barrier", "current_score": "Score 1 - Mildly Compromised Barrier"}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0 - No Vascularity / Redness", "current_score": "Score 1 - Mild Vascularity / Redness"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0 - None", "current_score": "Score 2 - Moderate"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3 (Healthy to Radiant)", "current_score": "Score 1 - Mild Glow"}, {"parameter": "Comedonal Density", "target_score": "Score 0 - No Comedones", "current_score": "Score 1 - Mild Comedonal Activity"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0 - Smooth / Even Texture", "current_score": "Score 1 - Mild Textural Irregularities"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 - Even / Balanced Oil Distribution", "current_score": "Score 1 - T-zone Predominant"}]}}',
