            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Regionally higher sebaceous activity in T‑zone", "Age-related and seasonal cheek dryness/dehydration"], "score_explanation": "White-light images (1/8, 3/8) show matte, slightly flaky cheeks with limited shine while the T‑zone (forehead, nose) appears slightly more reflective. UV/Woods images (4/8, 5/8) reveal increased fluorescence and porphyrin speckling localized to the T‑zone with relatively lower signal on the cheeks. PPL view (3/8) shows larger pores along the nose/medial cheeks and smaller pores laterally. This pattern fits: white.shine localized to T‑zone, uv.fluorescence pattern confined to T‑zone, and PPL pore ratio larger in T‑zone and small on cheeks → Combination.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "2 - Moderately Compromised Barrier", "possible_causes": ["Insufficient moisturizers/occlusives and disrupted lipid balance", "UV exposure and aging reducing barrier integrity"], "score_explanation": "PPL/white views (3/8, 1/8) reveal reduced surface texture uniformity (~0.6) with visible micro‑flaking and dullness. Hydration signal is low‑to‑slightly low (~0.40–0.45). Mild cheek redness (6/8) and flaking raise flaking_visibility_index to ~0.3–0.5. Combined indices map to a moderately compromised barrier.", "affected_area_image": "3"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "2 - Moderate Dehydration", "possible_causes": ["Insufficient moisturization and barrier lipids", "Environmental factors such as low humidity or cleansers stripping oils"], "score_explanation": "White/PPL views (1/8, 2/8, 3/8) show patchy dullness and fine micro‑flaking on forehead and cheeks. Estimated surface_reflectance_index ~0.35–0.50, microline_density_index ~0.25–0.35, and red-mode subsurface diffusion (6/8) in the moderate 0.55–0.70 range → consistent with moderate dehydration.", "affected_area_image": "2"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 3 - Moderate", "possible_causes": ["Age-related soft tissue descent and ligament laxity", "Loss of dermal collagen and elastin"], "score_explanation": "White-light image (1/8) shows visible jowl formation and blunting at the mandibular angle with submandibular shadowing. The implied mandibular angle change is ~10–15° with contour_smoothness_index ~0.5–0.7, matching moderate sagging.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure and dehydration of the lips", "Lifestyle factors such as tea/coffee, spices or previous inflammation"], "score_explanation": "Across white/brown/UV images (1/8, 7/8, 5/8) the lips appear noticeably darker than surrounding skin with patchy intensity, indicating lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "1 - Mild Comedonal Activity", "possible_causes": ["T‑zone sebum retention and oxidized debris", "Irregular cleansing or comedogenic products"], "score_explanation": "PPL/white (3/8, 1/8) show a few isolated open/closed comedones along the nose and medial cheeks. UV (5/8) shows only partial porphyrin overlap. Estimated comedone_count_density ~0.05–0.15 and cluster_index ~0.2–0.4.", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Genetic predisposition and thin periorbital skin", "Chronic sun exposure and inadequate sleep"], "score_explanation": "XPL (8/8) shows under‑eye darkening with a vascular/hemosiderin hue and mild trough shadowing; white views (1/8, 3/8) show persistent periorbital pigmentation. Overall pattern suggests moderate pigmentation/vascularity with mild hollowness and minimal puffiness.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "1 - Low-Normal Sebum", "possible_causes": ["Age‑related decline in oil output on cheeks", "Seasonal/environmental dryness"], "score_explanation": "White-light (1/8) shows overall matte finish with slight T‑zone sheen only. UV (5/8) demonstrates few porphyrins without dense clustering. Estimated sebum_quantity_index ≈0.40 and distribution_index ≈0.25 (T‑zone focused), mapping to a low‑normal score.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["T‑zone oil accumulation and comedogenesis", "Pore congestion from cosmetics or inadequate cleansing"], "score_explanation": "White/PPL views (1/8, 3/8) reveal a few scattered comedones in the T‑zone with no obvious papules, pustules, or nodules. Estimated total lesion count falls within 3–10 and inflammatory ratio remains <0.25. UV (5/8) shows limited porphyrin clustering, supporting a very mild grade.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Intrinsic aging with reduced collagen/elasticity", "Dehydration emphasizing fine lines"], "score_explanation": "Under PPL/XPL views (3/8, 8/8) faint fine lines are appreciable around the peri‑orbital and perioral regions at rest. Estimated wrinkle_depth_index ~0.25–0.45 and density ~0.2–0.4, consistent with mild superficial wrinkles.", "affected_area_image": "3"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "1 - Mild Sensitivity", "possible_causes": ["Compromised barrier from dryness/over-cleansing", "Environmental triggers or product irritation"], "score_explanation": "Red-mode image (6/8) shows faint, patchy cheek erythema without prominent telangiectasia. Barrier non‑uniformity and fine flaking in white/PPL (1/8, 3/8) suggest slight barrier disruption. Estimated erythema_intensity_index 0.25–0.45 and vascular_pattern_index <0.3 → mild sensitivity.", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "1 - T-zone Predominant", "possible_causes": ["Higher density of sebaceous glands in T‑zone", "Environmental dryness suppressing cheek sebum"], "score_explanation": "UV image (5/8) shows porphyrin/shine accentuation over forehead and nose with relatively matte cheeks; white view (1/8) corroborates slight T‑zone sheen. Estimated regional_variance_index ~0.3 and porphyrin_distribution_index ~0.3–0.4, indicating T‑zone predominance.", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "0 - Dull / Lackluster", "possible_causes": ["Dehydration and barrier compromise reducing light scatter", "Accumulated pigmentation and texture irregularities"], "score_explanation": "White and PPL images (1/8, 3/8) show patchy, uneven reflectance with low color luminance and minimal subsurface diffusion; shadow edges are moderately harsh. Estimated surface_reflectance_uniformity <0.5 and color_luminance_index <0.4, consistent with a dull score.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 3 - Moderate", "possible_causes": ["Sebaceous activity and chronic comedonal tendency", "Photoaging and loss of dermal support"], "score_explanation": "PPL image (3/8) shows obvious, enlarged pores over the nose and medial cheeks with coarse, non‑uniform reflection. Estimated pore_diameter_ratio ~1.6–2.0× baseline and texture_uniformity_index ~0.5–0.7, aligning with a moderate grade.", "affected_area_image": "3"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "1 - Mild", "possible_causes": ["Transient flushing and mild barrier weakness", "Environmental heat or topical actives causing mild vasodilation"], "score_explanation": "Red-light image (6/8) shows faint, localized erythema mainly over the cheeks and nasal alae. Vascular pattern is subtle without dense telangiectatic networks; color uniformity is only slightly patchy. Estimated erythema_intensity_index ~0.3 and vascular_pattern_density ~0.25.", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "4 - Marked", "possible_causes": ["Chronic sun exposure without adequate photoprotection", "Post‑inflammatory hyperpigmentation and hormonal influences"], "score_explanation": "Brown-mode image (7/8) shows confluent macules and patches across the malar areas, temples, upper lip, chin and forehead with patchy mottling. Coverage visually ~40–60% of analyzed face, mean intensity appears in the 0.65–0.75 bin, and contrast uniformity is reduced (~0.55–0.70). UV images (4/8, 5/8) indicate mixed epidermal–dermal pigmentation with modest UV enhancement, consistent with a marked superficial pigmentation score.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "2 - Moderate Textural Irregularities", "possible_causes": ["Post‑inflammatory changes from past acne/irritation", "Chronic dehydration and photodamage"], "score_explanation": "PPL (3/8) highlights patchy micro‑roughness and shallow micro‑shadows; brown mode (7/8) shows scattered PIH marks that disrupt uniform reflection. Estimated microtexture_variance_index ~0.5–0.6 and surface_gradient_irregularity ~0.45–0.55 with shallow shadows ~0.3–0.4.", "affected_area_image": "3"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2 - Moderate", "possible_causes": ["Thin peri‑orbital skin with visible venous plexus", "Volume loss in the tear trough producing shadows"], "score_explanation": "XPL/UV images (8/8, 5/8) reveal bluish‑brown discoloration consistent with vascular pigmentation, with a mild tear‑trough shadow visible in white light (1/8). The combination of vascular tint and structural hollowness aligns with a moderate score.", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1–2 (Minimal to Mild)", "current_score": "4 - Marked"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1 - Very Mild"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0–1 (Clear to Very Mild)", "current_score": "Grade 3 - Moderate"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 2 - Mild"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 3 - Moderate"}, {"parameter": "Skin Hydration", "target_score": "0–1 (Excellent to Mild Dehydration)", "current_score": "2 - Moderate Dehydration"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 - No Sensitivity", "current_score": "1 - Mild Sensitivity"}, {"parameter": "Barrier Health", "target_score": "0–1 (Strong to Mildly Compromised)", "current_score": "2 - Moderately Compromised"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0 - No Vascularity / Redness", "current_score": "1 - Mild"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0–1 (None to Mild)", "current_score": "Score 2 - Moderate"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2–3 (Healthy Glow to Radiant)", "current_score": "0 - Dull / Lackluster"}, {"parameter": "Comedonal Density", "target_score": "0 - No Comedones", "current_score": "1 - Mild Comedonal Activity"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0–1 (Smooth to Mild)", "current_score": "2 - Moderate Textural Irregularities"}, {"parameter": "Regional Oil Distribution", "target_score": "0 - Even / Balanced", "current_score": "1 - T-zone Predominant"}]}}',
                'post_diagnosis' => NULL,
