            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Regional sebum variation (T‑zone dominant)", "Genetic predisposition and hormonal influence"], "score_explanation": "White mode shows higher reflectance and subtle shine on the T‑zone (forehead, nose, chin) with relatively matte cheeks (estimated reflectance gap ≥0.3). UV mode reveals moderate porphyrin fluorescence clustered mainly on the nose and chin (T‑zone ≥40, cheeks <25). PPL shows pores moderate/enlarged on the T‑zone but small on cheeks. Weighted across modes this pattern best matches Combination skin.", "affected_area_image": "3"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "Score 1 - Mildly Compromised", "possible_causes": ["Under‑moisturization and cleanser overuse", "UV exposure weakening lipid barrier"], "score_explanation": "PPL shows mild roughness with fine flaking in UV highlights and slightly low hydration signal on white mode; redness mild. Composite indices suggest surface_texture_uniformity ~0.7–0.85 and hydration_signal 0.45–0.65.", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "Score 2 - Moderate Dehydration", "possible_causes": ["Insufficient moisturization/barrier impairment", "Low ambient humidity or excessive cleansing"], "score_explanation": "White mode shows dull, patchy reflectance and fine micro‑lines; PPL indicates increased microline density; red mode shows reduced subsurface diffusion. Indices align with surface_reflectance ~0.35–0.50, microline_density 0.25–0.35, diffusion 0.55–0.70.", "affected_area_image": "3"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 3 - Moderate", "possible_causes": ["Age‑related skin laxity and fat redistribution", "Collagen/elastin depletion"], "score_explanation": "White/XPL images show blunting of the mandibular contour with early jowl formation and submandibular shadowing. Estimated mandibular angle change ~10–15° and contour smoothness ~0.5–0.7.", "affected_area_image": "3"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure and dehydration", "Habit factors (e.g., lip licking/smoking)"], "score_explanation": "Across modes the lips appear darker than surrounding skin with uneven tone; cosmetic product is visible but underlying patchiness persists, indicating pigmentation tendency.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "Score 2 - Moderate", "possible_causes": ["Sebum and keratin buildup in follicles", "Irregular cleansing or occlusive products"], "score_explanation": "UV shows multiple orange‑red porphyrin dots over nose and central cheeks with localized clustering; PPL confirms several blackheads/whiteheads. Estimated comedone density ~0.15–0.3 with cluster index ~0.4–0.6.", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Vascular congestion and thin periorbital skin", "Chronic sun exposure and sleep/stress factors"], "score_explanation": "Under‑eye area shows visible dark circles with mixed brown‑bluish hue and slight tear‑trough hollowness; vascular accentuation is more evident under cross/UV views while puffiness is mild.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "Score 2 - Moderate / Normal-Oily", "possible_causes": ["Active sebaceous glands in T‑zone", "Hormonal and genetic factors"], "score_explanation": "White mode shows mild T‑zone shine without diffuse oiliness. UV reveals moderate porphyrin fluorescence clustered on nose/central cheeks. Estimated sebum_quantity_index ~0.55–0.65 with distribution index ~0.3 (T‑zone bias).", "affected_area_image": "3"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["Follicular congestion in T‑zone", "Cosmetic occlusion or inadequate cleansing"], "score_explanation": "White and PPL views show few comedones concentrated on the nose/central face with minimal inflammatory papules and no nodules. Estimated total lesion count within 3–10 and inflammatory ratio <0.25.", "affected_area_image": "3"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Intrinsic aging with early collagen loss", "Intermittent dehydration of the stratum corneum"], "score_explanation": "PPL/XPL emphasize fine lines on peri‑orbital area and nasolabial region visible at rest; depth and density correspond to wrinkle_depth_index ~0.25–0.45 and density ~0.2–0.4.", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "Score 1 - Mild Sensitivity", "possible_causes": ["Environmental triggers (heat/sun)", "Occasional product irritation"], "score_explanation": "Red/PPL imaging shows faint diffuse erythema on cheeks with minimal vascular enhancement and largely intact barrier pattern. Erythema_intensity ~0.3–0.4, vascular_pattern_index <0.3.", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "Score 1 - T-zone Predominant", "possible_causes": ["Higher sebaceous density in T‑zone", "Hormonal/sebaceous regulation differences across regions"], "score_explanation": "UV fluorescence and white‑mode reflectance are higher on the forehead, nose, and chin with relatively matte lateral cheeks. Regional variance and porphyrin distribution indices align with T‑zone focused pattern.", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "Score 1 - Mild Glow", "possible_causes": ["Dehydration reducing surface radiance", "Mottled pigmentation affecting luminance"], "score_explanation": "White mode reveals moderate reflectance uniformity (≈0.55–0.65) with dullness from dehydration and pigmentation; subsurface diffusion is limited, and shadow contrast is moderate—consistent with a mild glow rather than radiant.", "affected_area_image": "3"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2 - Mild", "possible_causes": ["T‑zone sebum activity enlarging follicular openings", "Photoaging and decreased dermal support"], "score_explanation": "PPL/XPL views show visible pores on nose and medial cheeks with extension slightly lateral; pore diameter appears ~1.3–1.6× baseline and texture uniformity around 0.6–0.8 with minor mottling in white mode.", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "Score 1 - Mild", "possible_causes": ["Intermittent flushing/heat exposure", "Early rosacea tendency or barrier dryness"], "score_explanation": "Red-mode view shows mild, symmetric cheek and nasal erythema without dense telangiectasia; color uniformity remains fair (≈0.7–0.8) and vascular pattern density ~0.2–0.35.", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "3 - Moderate", "possible_causes": ["Chronic UV exposure", "Post‑inflammatory hyperpigmentation and age-related lentigines"], "score_explanation": "Brown-light image shows mottled macules across forehead, nose and malar cheeks covering roughly 20–40% of the face with moderate intensity and uneven contrast (uniformity ~0.65–0.75). UV enhances some foci but without deep dermal dominance, supporting a moderate, mainly epidermal/mixed pattern.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "Score 2 - Moderate", "possible_causes": ["Post‑inflammatory changes and mild scarring", "Surface dehydration and photoaging"], "score_explanation": "PPL and brown images show micro‑roughness with patchy light distribution and shallow micro‑shadows on cheeks and chin, indicating microtexture variance ~0.5–0.7 and surface undulation ~0.45–0.6.", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2 - Moderate", "possible_causes": ["Thin peri‑orbital skin with visible vessels", "Anatomical hollowing causing shadowing"], "score_explanation": "Under-eye darkness shows bluish tone more prominent in cross/UV views indicating vascular component with additional structural hollowing (tear‑trough). Shadows persist across lighting, consistent with mixed vascular + structural etiology.", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "3 - Moderate"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1 - Very Mild"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0 - Clear / Smooth", "current_score": "Grade 2 - Mild"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 2 - Mild"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 3 - Moderate"}, {"parameter": "Skin Hydration", "target_score": "Score 0 - Excellent Hydration", "current_score": "Score 2 - Moderate Dehydration"}, {"parameter": "Skin Sebum Content", "target_score": "Score 1 - Low-Normal Sebum", "current_score": "Score 2 - Moderate / Normal-Oily"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0 - No Sensitivity", "current_score": "Score 1 - Mild Sensitivity"}, {"parameter": "Barrier Health", "target_score": "Score 0 - Strong / Healthy Barrier", "current_score": "Score 1 - Mildly Compromised"}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0 - No Vascularity / Redness", "current_score": "Score 1 - Mild"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0 - None", "current_score": "Score 2 - Moderate"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3 - Healthy to Radiant Glow", "current_score": "Score 1 - Mild Glow"}, {"parameter": "Comedonal Density", "target_score": "Score 0 - No Comedones", "current_score": "Score 2 - Moderate"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0 - Smooth / Even Texture", "current_score": "Score 2 - Moderate"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 - Even / Balanced Oil Distribution", "current_score": "Score 1 - T-zone Predominant"}]}}',
