nes", "current_score": "Score 2 - Moderate"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0 - Smooth / Even Texture", "current_score": "Score 2 - Moderate"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 - Even / Balanced Oil Distribution", "current_score": "Score 1 - T-zone Predominant"}]}',
