                'breastfeeding' => 'no',
            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Genetic sebum distribution pattern", "Hormonal variability affecting T‑zone oil"], "score_explanation": "White-light image (1/8) shows mild shine on the T‑zone (forehead and nose) with comparatively matte cheeks. UV (5/8) demonstrates scattered porphyrin fluorescence concentrated on the nose/central forehead while cheeks show sparse signals. PPL (2/8) reveals pores moderately enlarged in the T‑zone but smaller on lateral cheeks. This pattern fits the Combination criteria: localized T‑zone shine difference ≥0.3, UV fluorescence mainly in T‑zone (~40 range), and PPL pore size moderate/enlarged centrally but small on cheeks.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "Score 1", "possible_causes": ["Suboptimal moisturization and cleansing routine", "Intermittent irritation from active ingredients or friction"], "score_explanation": "PPL (2/8) indicates fairly uniform surface texture (≈0.75) with mild roughness; white-mode hydration signal is mid‑range (~0.5) and redness index ~0.3; flaking minimal. Aggregated indices align with Mildly Compromised Barrier (Score 1).", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "Score 2", "possible_causes": ["Insufficient moisturization or TEWL from air‑conditioning", "Low water intake or cleanser overuse"], "score_explanation": "White light (1/8) shows subdued glow with patchy reflectance (surface_reflectance_index ≈0.45–0.50). PPL (2/8) reveals faint micro‑lines on cheeks (microline_density_index ≈0.25–0.30). Red mode (6/8) displays only moderate subsurface diffusion (~0.6). Combined indices map to Moderate Dehydration (Score 2).", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 2", "possible_causes": ["Age‑related soft tissue descent and ligament laxity", "Reduced dermal collagen/elasticity"], "score_explanation": "White/XPL views (1/8, 8/8) show slightly blunted mandibular contour with early jowl prominence at the angles. Estimated mandibular_angle_change ≈5–8° and contour_smoothness_index ~0.75. Skin laxity index appears mild. These fit the Mild category (Grade 2).", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Chronic sun exposure/PIH", "Habitual lip licking or dehydration"], "score_explanation": "Despite lipstick, brown (7/8) and UV/Woods (5/8, 4/8) reveal darker vermilion borders compared with adjacent skin, suggesting underlying pigment accentuation. Therefore lip pigmentation is marked as present; cosmetic overlay may partly mask true extent.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "Score 1", "possible_causes": ["Retention keratin plugs in T‑zone", "Makeup residue or inconsistent cleansing"], "score_explanation": "UV (5/8) and PPL (2/8) indicate scattered comedones mainly on nose with density ~2–5 lesions/cm² (0.05–0.15), clustering index around 0.25–0.35, and low porphyrin overlap (<0.3). These match Mild Comedonal Activity (Score 1).", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Mild", "possible_causes": ["Genetic tear‑trough anatomy with thin skin", "Sleep deficiency or rubbing leading to PIH"], "score_explanation": "XPL (8/8) and brown mode (7/8) show mild lower‑lid pigmentation with slight structural shadowing medially; vascular prominence is minimal. Overall peri‑orbital composite across puffiness/hollowness/pigmentation/vascularity is predominantly mild.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "Score 1", "possible_causes": ["Balanced baseline sebum with mild T‑zone activity", "Seasonal/environmental variation"], "score_explanation": "White mode (1/8) shows mild T‑zone shine (shine_reflectance_index ~0.45). UV (5/8) demonstrates a few porphyrin dots (~30–40 range) centered on nose. Calculated sebum_quantity_index ≈0.48 and distribution_index ≈0.25 (T‑zone bias). Global sebum index ≈0.43, mapping to Low‑Normal Sebum (Score 1).", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1", "possible_causes": ["Mild follicular keratinization with T‑zone oil", "Cosmetic congestion or intermittent hormonal shifts"], "score_explanation": "White light (1/8) and PPL (2/8) reveal few comedonal lesions concentrated on nose and central cheeks with minimal erythema. Estimated total lesion count is within 3–10 and inflammatory elements are rare (inflammatory_ratio <0.25). UV (5/8) shows sparse porphyrin dots without clustering. This matches Grade 1 – Very Mild.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 1", "possible_causes": ["Early photoaging from UV exposure", "Transient dehydration accentuating micro‑lines"], "score_explanation": "Under PPL/XPL (2/8 and 8/8), only faint fine lines are appreciable on the forehead with shallow depth and low density. Indices correspond to wrinkle_depth_index <0.25 and wrinkle_density_index <0.2, meeting Very Mild criteria (Grade 1).", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "Score 1", "possible_causes": ["Occasional reactive flushing or product sensitivity", "Environmental stressors (heat, wind)"], "score_explanation": "Red light (6/8) shows faint diffuse erythema on cheeks without prominent telangiectasia. Estimated erythema_intensity_index ≈0.3–0.4 and vascular_pattern_index <0.3; barrier_uniformity remains slightly patchy. These values correspond to Mild Sensitivity (Score 1).", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "Score 1", "possible_causes": ["Physiologic T‑zone activity", "Heat/humidity increasing central facial oil"], "score_explanation": "UV (5/8) and white (1/8) show reflectance and porphyrin localization to forehead, nose, and chin with relatively matte cheeks. Regional variance index ~0.3 and porphyrin distribution index ~0.35, signifying a T‑zone predominant pattern (Score 1).", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "Score 1", "possible_causes": ["Dehydration reducing optical scatter", "Mottled pigmentation lowering perceived brightness"], "score_explanation": "White light (1/8) shows moderate surface reflectance uniformity (~0.6) and color luminance index around 0.5 with soft shadow contrast; subsurface diffusion is moderate on PPL/red (2/8, 6/8). These map to Mild Glow rather than radiant (global_luminosity_index in 0.3–0.5 bin).", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2", "possible_causes": ["T‑zone sebum output stretching follicular openings", "Loss of collagen/elastic support from photoaging or dehydration"], "score_explanation": "PPL image (2/8) displays visible pores across nose and medial cheeks with lateral extension but not confluent. Estimated pore_diameter_ratio ≈1.4–1.5× baseline and texture_uniformity_index ≈0.65–0.75; white-mode reflection is slightly uneven. These fall within the mild range (grade 2: pore 1.3–1.6×, texture 0.6–0.8).", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "Score 1", "possible_causes": ["Sensitivity/reactive flushing", "Environmental temperature changes"], "score_explanation": "Red mode (6/8) shows mild, diffuse cheek erythema without dense telangiectatic networks. Color uniformity remains moderate and symmetry is balanced. Global vascularity index falls in mild range (erythema ~0.35, vascular density <0.4).", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "3 - Moderate", "possible_causes": ["Cumulative UV exposure/melasma tendency", "Post‑inflammatory hyperpigmentation from past acne or irritation"], "score_explanation": "Brown mode (7/8) shows mottled hyperpigmented macules over forehead, malar cheeks, and nose with coverage ~30–40% of visible surface. Mean intensity appears mid‑tone (≈0.55) and uniformity is moderately mottled (≈0.7). UV (5/8) does not markedly deepen the lesions, suggesting predominantly epidermal/superficial component. These align with score 3 thresholds: coverage 20–40%, intensity 0.50–0.65, and uniformity 0.65–0.80.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "Score 1", "possible_causes": ["Dehydration‑related dullness", "Past low‑grade acne PIH and micro‑textural change"], "score_explanation": "PPL (2/8) reveals mild micro‑roughness on forehead and cheeks without deep undulation; indices approximate microtexture_variance 0.35–0.45 and surface_gradient_irregularity 0.3–0.4 with shallow shadowing only. This corresponds to Mild irregularities (Score 1).", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 1", "possible_causes": ["Mild tear‑trough hollowness casting shadows", "Thin peri‑orbital skin with visible subdermal tone"], "score_explanation": "XPL (8/8) highlights faint medial shadowing with subtle bluish tone but no pronounced vascular web; UV (5/8) does not intensify markedly. This corresponds to mild under‑eye darkness primarily from shallow structural shadowing with minimal vascular contribution.", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "3 - Moderate"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0 - Clear / Smooth", "current_score": "Grade 2"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 - Very Mild (maintain/prevent progression)", "current_score": "Grade 1"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 2"}, {"parameter": "Skin Hydration", "target_score": "Score 0 - Excellent Hydration", "current_score": "Score 2"}, {"parameter": "Skin Sebum Content", "target_score": "Score 0–1 (well balanced)", "current_score": "Score 1"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0 - No Sensitivity", "current_score": "Score 1"}, {"parameter": "Barrier Health", "target_score": "Score 0 - Strong / Healthy Barrier", "current_score": "Score 1"}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Mild"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3 (Healthy to Radiant)", "current_score": "Score 1"}, {"parameter": "Comedonal Density", "target_score": "Score 0 - No Comedones", "current_score": "Score 1"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0 - Smooth / Even Texture", "current_score": "Score 1"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 - Even / Balanced Oil Distribution", "current_score": "Score 1"}]}}',
