            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Dry Skin", "possible_causes": ["Age-related decrease in sebum output", "Over-cleansing or low environmental humidity"], "score_explanation": "White light (image 3) shows overall matte finish with minimal specular highlights indicating a low shine_reflectance_ratio (~0.3). UV/Woods images (4–5) show sparse porphyrin dots (<20 overall), and PPL (image 1) highlights fine micro-lines with small to moderate pores. Weighted across white (0.45), UV (0.35), and PPL (0.2), the criteria match the Dry Skin diagnostic logic.", "affected_area_image": "3"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "Score 1", "possible_causes": ["Insufficient lipids/ceramides in routine", "Over-exfoliation or harsh cleansers"], "score_explanation": "PPL (image 1) shows near-uniform but slightly rough texture (surface_texture_uniformity ~0.72–0.8). Hydration signal from white mode is modest (~0.5–0.6) and redness is mild (~0.3–0.4); minimal flaking detected. Combined indices indicate a mildly compromised barrier (score 1).", "affected_area_image": "1"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "Score 2", "possible_causes": ["Insufficient moisturization and ceramide support", "Environmental dehydration or AC exposure"], "score_explanation": "White mode (image 3) shows low surface reflectance (~0.4–0.5) with patchy brightness; PPL (image 1) indicates increased microline density (~0.28–0.33); red mode (image 8) demonstrates moderate subsurface diffusion (~0.6). Weighted indices align with Moderate Dehydration (score 2).", "affected_area_image": "3"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 3", "possible_causes": ["Age-related soft-tissue descent and ligament laxity", "Loss of dermal collagen and fat redistribution"], "score_explanation": "White light (image 3) reveals blunting of mandibular contour with early jowls; estimated mandibular_angle_change ~10–12°, contour_smoothness_index ~0.55–0.65, and skin_laxity_index ~0.5. These measures correspond to \'Moderate\' sagging (Grade 3).", "affected_area_image": "3"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Cumulative UV exposure without lip SPF", "Chronic dryness or irritant exposure"], "score_explanation": "Brown mode (image 7) and white mode (image 3) show the lips darker than adjacent perioral skin with patchy brown tone, confirming presence of lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "Score 1", "possible_causes": ["Sebaceous filaments and debris retention in T‑zone", "Comedogenic product use"], "score_explanation": "UV/Woods (image 4) and PPL (image 1) show scattered comedones on nose/medial cheeks. Estimated comedone_count_density ~0.08–0.12 with comedone_cluster_index ~0.25–0.35 and porphyrin_overlap_index ~0.25, corresponding to Mild activity (score 1).", "affected_area_image": "4"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Age-related volume loss at infraorbital rim", "Chronic sun exposure and thin periocular skin"], "score_explanation": "XPL/oblique (image 2) demonstrates mixed brown‑vascular darkening with visible tear‑trough shadowing; mild puffiness but evident hollowness and pigmentation. Overall severity across puffiness, hollowness, and pigmentation ranks as Moderate.", "affected_area_image": "2"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "Score 1", "possible_causes": ["Age-related decline in sebaceous activity", "Use of drying cleansers or alcohol-based toners"], "score_explanation": "White light (image 3) shows minimal shine (shine_reflectance_index ~0.45) and UV/Woods (images 4–5) display few porphyrins (~25–35) mainly in T‑zone. Sebum_quantity_index approximates 0.4–0.45 with relatively balanced distribution, mapping to Low‑Normal (score 1).", "affected_area_image": "3"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1", "possible_causes": ["Sebaceous filaments and minor congestion in T‑zone", "Comedogenic products or incomplete cleansing"], "score_explanation": "White light (image 3) and UV (image 4) show a few comedones concentrated in the T‑zone with scattered fluorescence dots; inflammatory papules are uncommon. Estimated total lesions 3–8 with inflammatory_ratio <0.1, mapping to Grade 1 - Very Mild.", "affected_area_image": "3"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 3", "possible_causes": ["Intrinsic aging with collagen/elastin loss", "Cumulative photodamage and dehydration"], "score_explanation": "PPL/XPL (images 1–2) show clear fine-to-moderate lines on forehead, peri‑orbital and perioral areas visible at rest. Estimated wrinkle_depth_index ~0.5 and wrinkle_density_index ~0.45–0.5 with moderate contrast visibility, matching Grade 3 (Moderate).", "affected_area_image": "1"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "Score 1", "possible_causes": ["Mild barrier compromise from actives or weather changes", "Transient flushing triggers (heat/spices)"], "score_explanation": "Red mode (image 8) shows faint cheek/nasal erythema with erythema_intensity_index ~0.3–0.4; vascular pattern remains subtle in PPL. Barrier_uniformity_index slightly reduced (~0.7–0.75). These observations align with Mild sensitivity (score 1).", "affected_area_image": "8"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "Score 1", "possible_causes": ["Physiologic central sebaceous dominance", "Intermittent occlusion in the T‑zone"], "score_explanation": "White (image 3) shows mild central shine; UV/Woods (images 4–5) display porphyrin concentration predominantly in the T‑zone with cheeks comparatively matte. Regional_variance_index and porphyrin_distribution_index both ~0.3–0.4, consistent with T‑zone predominant pattern (score 1).", "affected_area_image": "4"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "Score 1", "possible_causes": ["Dehydration and uneven pigmentation reducing brightness", "Age-related decline in light-scattering quality"], "score_explanation": "White (image 3) shows surface_reflectance_uniformity around 0.6–0.7 with mild dullness; PPL indicates soft but not radiant highlights; brown/red modes show moderate subsurface diffusion. Weighted global luminosity index maps to Mild Glow (score 1).", "affected_area_image": "3"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2", "possible_causes": ["Age-related collagen decline around follicular openings", "Chronic mild congestion/oxidized sebum"], "score_explanation": "PPL (image 1) demonstrates visible pores on nose and medial cheeks with pore_diameter_ratio roughly 1.4–1.5× baseline and texture_uniformity_index ~0.65–0.75; white-mode reflection shows minor patchiness. These align with the \'Mild\'–\'Moderate\' band; global index maps to Grade 2.", "affected_area_image": "1"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "Score 1", "possible_causes": ["Transient flushing or mild irritation", "Dryness-related background erythema"], "score_explanation": "Red mode (image 8) reveals faint, patchy cheek/nasal erythema (erythema_intensity_index ~0.35) with low vascular pattern density (~0.25–0.3) and moderate color uniformity (~0.7). These map to Mild vascularity/redness (score 1).", "affected_area_image": "8"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "4 - Marked", "possible_causes": ["Chronic UV exposure leading to lentigines/melasma tendencies", "Post-inflammatory hyperpigmentation"], "score_explanation": "Brown mode (image 7) reveals confluent macules and patches across forehead, malar cheeks, and perioral zone covering ~45–55% area. Mean intensity appears in the 0.65–0.7 band with uneven borders; UV (image 4) shows moderate enhancement, implying mixed epidermal–dermal depth. Aggregated indices by the scoring formula place the global score in the \'Marked\' (4) bin.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "Score 2", "possible_causes": ["Photoaging-related collagen remodeling", "Residual PIH and historic lesions altering microrelief"], "score_explanation": "PPL (image 1) highlights micro-roughness and patchy reflection particularly on cheeks/forehead. Estimated microtexture_variance_index ~0.55–0.6, surface_gradient_irregularity ~0.5, and shadow_depth_index ~0.35–0.45, placing severity in the Moderate range (score 2).", "affected_area_image": "1"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2", "possible_causes": ["Tear‑trough anatomy/volume loss causing shadows", "Periorbital vascular visibility through thin skin"], "score_explanation": "XPL (image 2) shows bluish‑brown discoloration with clear infraorbital trough shadowing; UV (image 4) has limited fluorescence, indicating mixed vascular pigmentation plus structural hollowness. Severity aligns with Moderate (score 2).", "affected_area_image": "2"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Skin Type", "target_score": "Normal/Balanced Skin", "current_score": "Dry Skin"}, {"parameter": "Superficial Pigmentation Score", "target_score": "1–2 (Minimal to Mild)", "current_score": "4 - Marked"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 (Clear)", "current_score": "Grade 1"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0–1", "current_score": "Grade 2"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1–2", "current_score": "Grade 3"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1–2", "current_score": "Grade 3"}, {"parameter": "Skin Hydration", "target_score": "Score 0 (Excellent Hydration)", "current_score": "Score 2"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Barrier Health", "target_score": "Score 0 (Strong / Healthy Barrier)", "current_score": "Score 1"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0–1", "current_score": "Score 2"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3", "current_score": "Score 1"}, {"parameter": "Comedonal Density", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter":