            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Genetic T‑zone sebaceous predominance", "Environmental dehydration on cheeks creating mixed behavior"], "score_explanation": "White light shows higher reflectance and sheen on the nose and central forehead with comparatively matte cheeks. UV/blue views reveal porphyrin signals concentrated in the T‑zone, and PPL reveals moderately larger pores centrally with smaller pores laterally. The localized T‑zone oil with low-to-moderate cheek reflectance fits Combination criteria.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "1 - Mildly Compromised Barrier", "possible_causes": ["Over‑cleansing or inadequate moisturization", "UV exposure and mild irritants"], "score_explanation": "PPL shows mild surface roughness with occasional micro‑flaking and white/red modes reveal slight erythema with reduced luminosity. Hydration signals are somewhat low, indicating a mild barrier compromise.", "affected_area_image": "3"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "2 - Moderate Dehydration", "possible_causes": ["Insufficient moisturizer/humectant use", "Low ambient humidity and UV exposure"], "score_explanation": "White mode shows dull, patchy reflectance; PPL displays increased micro‑line density; red-mode diffusion appears moderate rather than high. These indicators reflect reduced stratum corneum water content in the moderate range.", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "2 - Mild", "possible_causes": ["Early collagen/elastin decline with age", "Gravity-driven soft tissue descent"], "score_explanation": "White/XPL perspectives show slight blunting of the mandibular contour with early jowl shadowing at the angles and preserved line continuity, matching mild sagging.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure without lip SPF", "Chronic dryness or post‑inflammatory changes"], "score_explanation": "Lips appear uniformly darker than surrounding skin in white and brown modes, indicating discernible lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "1 - Mild Comedonal Activity", "possible_causes": ["T‑zone oil with partial pore blockage", "Cosmetic occlusion or inconsistent exfoliation"], "score_explanation": "UV and PPL reveal a few comedonal dots primarily on the nose with a scattered, non-confluent pattern and limited porphyrin overlap, consistent with mild density.", "affected_area_image": "4"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Genetic predisposition to peri‑orbital pigmentation/vascular show", "Rubbing or inadequate sun protection around the eyes"], "score_explanation": "Peri‑orbital areas show prominent dark circles with brown‑gray pigmentation and a vascular hue across modes, plus subtle tear‑trough shadowing and minimal puffiness. Overall severity is moderate.", "affected_area_image": "6"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "1 - Low-Normal Sebum", "possible_causes": ["Balanced but modest sebaceous output", "Seasonal/environmental reduction of oil"], "score_explanation": "White mode shows limited global shine aside from the nose; UV reveals few scattered porphyrin dots. Quantity appears modest with T‑zone bias, fitting the low‑normal category.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "0 - Clear", "possible_causes": ["Currently minimal inflammatory activity", "Non‑comedogenic skincare and routine cleansing"], "score_explanation": "White, UV and PPL images show no inflamed papules, pustules, or nodules; only a few small comedonal points on the nose. Total inflammatory lesion count is <3 and inflammatory ratio is near zero, meeting Grade 0.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "2 - Mild", "possible_causes": ["Intrinsic aging and repetitive expressions", "Intermittent dehydration reducing skin plumpness"], "score_explanation": "Fine horizontal forehead lines and peri‑orbital micro‑lines are detectable on PPL/XPL but are not deep or dense. Depth and density align with the mild range.", "affected_area_image": "3"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "1 - Mild Sensitivity", "possible_causes": ["Intermittent product or environmental triggers", "Suboptimal barrier hydration"], "score_explanation": "Red/XPL images show faint patchy erythema on the cheeks and peri‑nasal area with minimal visible vascular networks; PPL indicates slight barrier unevenness. This represents mild sensitivity.", "affected_area_image": "8"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "1 - T-zone Predominant", "possible_causes": ["Natural sebaceous density in the T‑zone", "Skincare controlling cheek oil more than the center"], "score_explanation": "UV/blue views display greater fluorescence and shine centered on the nose and central forehead with comparatively matte cheeks. The variance pattern indicates a clear T‑zone predominance.", "affected_area_image": "4"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "0 - Dull / Lackluster", "possible_causes": ["Dehydration and uneven pigmentation affecting light uniformity", "Low sebum glow with mild surface roughness"], "score_explanation": "White mode exhibits patchy reflectance and muted brightness; PPL lacks even, soft highlights and subsurface diffusion is weak. Shadow contrast around the eyes and mouth remains visible, producing a dull overall glow.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "2 - Mild", "possible_causes": ["T‑zone sebum activity increasing apparent pore size", "Photoaging and previous comedonal congestion"], "score_explanation": "PPL view reveals visible pores on the nose and medial cheeks with mild diffuse roughness; lateral cheeks appear finer. Estimated pore size ~1.3–1.6× baseline with slightly uneven specular reflection, consistent with Grade 2.", "affected_area_image": "3"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "1 - Mild", "possible_causes": ["Transient flushing or temperature changes", "Early vascular reactivity with mild barrier dryness"], "score_explanation": "Red/XPL views show light diffuse erythema over cheeks and peri‑nasal area with no dense telangiectatic networks and acceptable symmetry, consistent with a mild grade.", "affected_area_image": "8"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "4 - Marked", "possible_causes": ["Cumulative UV exposure without adequate photoprotection", "Post‑inflammatory hyperpigmentation tendency and hormonal/age-related melanogenesis"], "score_explanation": "Brown-mode image shows confluent dark macules and patches across forehead, malar regions, periorbital rims and perioral area, covering about 40–60% of the face. The intensity is high with mottled, irregular borders and UV enhancement in several areas, indicating a mixed superficial component consistent with a Marked score.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "1 - Mild Textural Irregularities", "possible_causes": ["Superficial dehydration and photoaging effects", "Residual PIH and past minor breakouts"], "score_explanation": "PPL images show fine micro‑roughness and slight surface undulation on cheeks and forehead without deep pits or scarring; reflection is mildly uneven, indicating a mild level.", "affected_area_image": "3"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "2 - Moderate", "possible_causes": ["Thin peri‑orbital skin with visible vasculature", "Anatomical hollowness creating shadows"], "score_explanation": "Under-eye zones display bluish‑purple hues with persistence across UV/XPL and a noticeable tear‑trough contour, indicating mixed vascular pigmentation with structural shadowing at a moderate level.", "affected_area_image": "6"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "4 - Marked"}, {"parameter": "Texture + Open Pores Grading", "target_score": "0 - Clear / Smooth", "current_score": "2 - Mild"}, {"parameter": "Superficial Wrinkles", "target_score": "1 - Very Mild", "current_score": "2 - Mild"}, {"parameter": "Jawline Sagging", "target_score": "1 - Very Mild", "current_score": "2 - Mild"}, {"parameter": "Skin Hydration", "target_score": "0 - Excellent Hydration", "current_score": "2 - Moderate Dehydration"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 - No Sensitivity", "current_score": "1 - Mild Sensitivity"}, {"parameter": "Barrier Health", "target_score": "0 - Strong / Healthy Barrier", "current_score": "1 - Mildly Compromised Barrier"}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0 - No Vascularity / Redness", "current_score": "1 - Mild"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "0 - None", "current_score": "2 - Moderate"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2–3 (Healthy to Radiant Glow)", "current_score": "0 - Dull / Lackluster"}, {"parameter": "Comedonal Density", "target_score": "0 - No Comedones", "current_score": "1 - Mild Comedonal Activity"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0 - Smooth / Even Texture", "current_score": "1 - Mild Textural Irregularities"}, {"parameter": "Regional Oil Distribution", "target_score": "0 - Even / Balanced Oil Distribution", "current_score": "1 - T-zone Predominant"}]}}',
