            'parameters_with_abnormal_scores' => '{"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "4 - Marked"}, {"parameter": "Texture + Open Pores Grading", "target_score": "0 - Clear / Smooth", "current_score": "2 - Mild"}, {"parameter": "Superficial Wrinkles", "target_score": "1 - Very Mild", "current_score": "2 - Mild"}, {"parameter": "Jawline Sagging", "target_score": "1 - Very Mild", "current_score": "2 - Mild"}, {"parameter": "Skin Hydration", "target_score": "0 - Excellent Hydration", "current_score": "2 - Moderate Dehydration"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 - No Sensitivity", "current_score": "1 - Mild Sensitivity"}, {"parameter": "Barrier Health", "target_score": "0 - Strong / Healthy Barrier", "current_score": "1 - Mildly Compromised Barrier"}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0 - No Vascularity / Redness", "current_score": "1 - Mild"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "0 - None", "current_score": "2 - Moderate"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2–3 (Healthy to Radiant Glow)", "current_score": "0 - Dull / Lackluster"}, {"parameter": "Comedonal Density", "target_score": "0 - No Comedones", "current_score": "1 - Mild Comedonal Activity"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0 - Smooth / Even Texture", "current_score": "1 - Mild Textural Irregularities"}, {"parameter": "Regional Oil Distribution", "target_score": "0 - Even / Balanced Oil Distribution", "current_score": "1 - T-zone Predominant"}]}',
