            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Dry Skin", "possible_causes": ["Age-related reduction in sebum production", "Environmental dehydration and inadequate moisturization"], "score_explanation": "White light (image 1) shows a matte surface with minimal specular shine (shine_reflectance_ratio estimated <0.3). UV images (4/5) reveal very few porphyrin fluorescence dots (<20, not generalized). PPL (image 2) shows high micro-line density and fine roughness with relatively small pores across cheeks, supporting a dry profile according to the diagnostic logic.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "Score 2 - Moderately Compromised Barrier", "possible_causes": ["Insufficient lipids/ceramides", "Overexposure to sun or harsh cleansers"], "score_explanation": "PPL (2) shows uneven surface texture; white (1) indicates low hydration signal (<0.45). Mild background redness (6) and occasional micro-flaking lead to a combined global_barrier_index mapped to score 2.", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "Score 2 - Moderate Dehydration", "possible_causes": ["Insufficient moisturization or humectants", "Environmental factors (dry climate/AC)"], "score_explanation": "White (1) shows dull, patchy reflectance and fine micro-lines; PPL (2) shows increased microline density (~0.25–0.35). Red mode (8/6) demonstrates reduced subsurface diffusion (~0.55–0.70). Combined indices align with moderate dehydration.", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 3 - Moderate", "possible_causes": ["Age-related soft tissue descent and ligament laxity", "Loss of dermal collagen and elastin"], "score_explanation": "White light (image 1) shows visible jowl formation and blunting of mandibular contour with submandibular shadowing. Estimated mandibular_angle_change ~10–15° and contour_smoothness_index ~0.5–0.7, indicating moderate sagging.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Chronic sun exposure without lip SPF", "Intrinsic aging or previous inflammation/smoking history"], "score_explanation": "Brown/white images (7/1) show lips darker than surrounding skin with diffuse tone irregularity, consistent with lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "Score 1 - Mild Comedonal Activity", "possible_causes": ["Sebaceous filament buildup in T‑zone", "Makeup residue or inadequate pore cleansing"], "score_explanation": "UV (4) and PPL (2) reveal scattered comedones concentrated in T‑zone with low cluster index (0.2–0.4) and density around 2–5 lesions/cm², meeting mild criteria.", "affected_area_image": "4"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Periorbital melanosis and thin skin", "Age-related fat pad changes and fluid retention"], "score_explanation": "XPL (3) and brown (7) reveal mixed under‑eye darkening with pigmentation and vascular contribution; mild puffiness and early hollowness visible on medial troughs. Overall severity is moderate.", "affected_area_image": "3"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "Score 1 - Low-Normal Sebum", "possible_causes": ["Age-related reduction in sebaceous activity", "Gentle/over-cleansing reducing surface lipids"], "score_explanation": "White light (1) shows minimal shine (shine_reflectance_index ~0.3–0.5). UV/Woods (4/5) display few porphyrin clusters (<40) with T‑zone emphasis only. Global sebum index falls in low-normal range without generalized oiliness.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1 - Very Mild", "possible_causes": ["Occasional follicular congestion in T‑zone", "Cosmetic occlusion or inadequate exfoliation"], "score_explanation": "White light (1) and PPL (2) reveal a few discrete comedones, primarily on the nose/medial cheeks, with no active inflammatory papules or pustules. UV (4) shows scattered fluorescence dots only, giving a very low inflammatory ratio (<0.25) and total lesion count within 3–10.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 3 - Moderate", "possible_causes": ["Intrinsic aging with collagen loss", "UV-induced photoaging"], "score_explanation": "PPL/XPL (2/3) reveal clearly defined fine lines on forehead, peri‑orbital and perioral regions that are visible at conversational distance. Estimated wrinkle_depth_index 0.45–0.65 and density_index 0.4–0.6 → moderate.", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "Score 1 - Mild Sensitivity", "possible_causes": ["Mild barrier disruption from dryness", "Environmental temperature changes or product irritation"], "score_explanation": "Red mode (image 6) shows faint erythema on cheeks and peri‑nasal area with low vascular pattern density (<0.3) and barrier uniformity slightly reduced but mostly intact. Overall indices meet mild sensitivity.", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "Score 1 - T-zone Predominant", "possible_causes": ["Higher sebaceous gland density in T‑zone", "Hormonal patterning of sebum output"], "score_explanation": "UV (4) indicates slightly higher fluorescence and reflectance on forehead and nose with relatively matte cheeks on white light (1). Regional variance index ~0.2–0.4 and porphyrin distribution index ~0.25–0.45 fit a T‑zone pattern.", "affected_area_image": "4"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "Score 0 - Dull / Lackluster", "possible_causes": ["Dehydration and texture roughness", "Accumulated pigmentation diminishing brightness"], "score_explanation": "White light (1) shows patchy reflectance with low surface_reflectance_uniformity (<0.5) and color_luminance index (<0.4). PPL (2) lacks soft diffuse highlights, indicating reduced subsurface diffusion, consistent with a dull appearance.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2 - Mild", "possible_causes": ["Chronic sun exposure causing collagen/elastin decline", "Age-related decreased skin elasticity"], "score_explanation": "PPL (image 2) shows visible pores on nose and medial cheeks extending slightly laterally with mild roughness. Estimated pore_diameter_ratio ~1.3–1.6× baseline and texture_uniformity_index ~0.6–0.8, consistent with grade 2.", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "Score 1 - Mild", "possible_causes": ["Transient vasodilation due to sensitivity/dryness", "Photodamage-related superficial vessels"], "score_explanation": "Red light (6) demonstrates faint, patchy erythema over cheeks and around nose; vascular pattern density remains low-to-mild (0.2–0.4) with reasonably even color uniformity (>0.6).", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "4 - Marked", "possible_causes": ["Chronic sun exposure (photoaging)", "Hormonal and age-related melanogenesis"], "score_explanation": "Brown mode (image 7) displays confluent brown macules and patches over cheeks, nose, and forehead with coverage estimated around 40–60%. Mean intensity appears in the 0.65–0.75 range and uniformity is uneven (contrast_uniformity_index ~0.55–0.70). UV (4) shows mixed enhancement suggesting a mixed epidermal–dermal component, aligning with score 4.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "Score 2 - Moderate Textural Irregularities", "possible_causes": ["Photoaging-related collagen degradation", "Healed acne/PIH contributing to uneven surface"], "score_explanation": "PPL (2) shows micro‑roughness with uneven reflection and subtle shadowing along cheeks and perioral area. Estimated microtexture_variance_index ~0.5–0.7 and surface_gradient_irregularity ~0.45–0.65, mapping to score 2.", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2 - Moderate", "possible_causes": ["Thin peri‑orbital skin with visible vasculature", "Anatomical tear‑trough hollowing and pigment deposition"], "score_explanation": "XPL (3) highlights bluish-brown peri‑orbital tone with clear medial trough shadowing; UV (4) shows some vascular/pigmentation enhancement. Combination of vascular pigmentation and structural hollowness supports a moderate score.", "affected_area_image": "3"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Skin Type (Dry Skin)", "target_score": "Balanced/Normal Skin", "current_score": "Dry Skin"}, {"parameter": "Superficial Pigmentation", "target_score": "1–2 (Minimal to Mild)", "current_score": "4 - Marked"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1 - Very Mild"}, {"parameter": "Texture + Open Pores", "target_score": "Grade 0–1 (Clear to Very Mild)", "current_score": "Grade 2 - Mild"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1–2 (Very Mild to Mild)", "current_score": "Grade 3 - Moderate"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1–2 (Very Mild to Mild)", "current_score": "Grade 3 - Moderate"}, {"parameter": "Skin Hydration", "target_score": "Score 0 - Excellent Hydration", "current_score": "Score 2 - Moderate Dehydration"}, {"parameter": "Skin Sensitivity", "target_score": "Score 0 - No Sensitivity", "current_score": "Score 1 - Mild"}, {"parameter": "Barrier Health", "target_score": "Score 0 - Strong / Healthy Barrier", "current_score": "Score 2 - Moderately Compromised"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent / Minimal", "current_score": "Present"}, {"parameter": "Vascularity / Redness", "target_score": "Score 0 - None", "current_score": "Score 1 - Mild"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0–1 (None to Mild)", "current_score": "Score 2 - Moderate"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3 (Healthy to Radiant)", "current_score": "Score 0 - Dull"}, {"parameter": "Comedonal Density", "target_score": "Score 0 - None", "current_score": "Score 1 - Mild"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0–1 (Smooth to Mild)", "current_score": "Score 2 - Moderate"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 - Even / Balanced", "current_score": "Score 1 - T-zone Predominant"}]}}',
