ies Beyond Pores", "post_treatment_image": "2", "post_treatment_score_or_label": "Score 1 - Mild Textural Irregularities", "before_treatment_score_or_label": "Score 2 - Moderate Textural Irregularities"}, "under_eye_vascularity_vs_structural_shadows": {"before_image": "3", "parameter_name": "Under Eye Vascularity vs Structural Shadows", "post_treatment_image": "3", "post_treatment_score_or_label": "Score 2 - Moderate", "before_treatment_score_or_label": "Score 2 - Moderate"}}}',
