            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Genetic variation in sebaceous activity", "Hormonal and environmental influences"], "score_explanation": "White light (1/8) shows localized shine and visible pores over the nose and central forehead with relatively matte cheeks; UV (5/8) concentrates porphyrin fluorescence in the T-zone; PPL (2/8) shows larger pores centrally and smaller laterally. This T-zone dominant activity with lower cheek reflectance matches Combination Skin by weighted logic.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "2 - Moderately Compromised Barrier", "possible_causes": ["Insufficient lipids/humectants in routine", "Irritant exposure or harsh cleansing"], "score_explanation": "PPL (2/8) shows non‑uniform texture with micro‑flaking; white light indicates low hydration signal; concurrent mild‑moderate redness is present. Combined indices place barrier function in the moderately compromised range.", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "2 - Moderate Dehydration", "possible_causes": ["Insufficient moisturizing or low humidity", "Compromised barrier increasing TEWL"], "score_explanation": "White mode (1/8) displays patchy, matte reflectance; PPL (2/8) shows increased micro‑line density and flaking; red mode (6/8) indicates only moderate subsurface diffusion (~0.55–0.70). Weighted indices map to score 2.", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "2 - Mild", "possible_causes": ["Age‑related collagen/elastic tissue reduction", "Gravity-related soft‑tissue descent"], "score_explanation": "White/XPL (1/8, 8/8) suggest slight blunting at the mandibular angle with early jowl prominence and mild submandibular shadowing—indicative of ~5–10° angle change and contour index ~0.7–0.85.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["UV exposure", "Dehydration or lifestyle factors"], "score_explanation": "Brown mode (7/8) shows lips darker than adjacent skin with patchy tone and dryness, confirming detectable pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "2 - Moderate", "possible_causes": ["Retention hyperkeratosis with elevated sebum", "Comedogenic makeup/sunscreen residues"], "score_explanation": "PPL/UV (2/8, 5/8) show multiple clustered comedones on the nose and medial cheeks with partial overlap of porphyrin fluorescence; lesion density approximates 0.15–0.3 lesions/cm², mapping to Grade 2.", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Thin peri‑orbital skin with visible vessels", "Early volume loss and fatigue"], "score_explanation": "XPL (8/8) reveals under‑eye darkness with purplish tone and mild tear‑trough hollowing; no severe edema. Mixed vascular/pigment contribution without severe puffiness supports a moderate assessment.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "2 - Moderate / Normal-Oily", "possible_causes": ["Hormonal regulation of sebaceous glands", "Use of occlusive cosmetics"], "score_explanation": "White light shows mild T‑zone sheen; UV (5/8) presents numerous porphyrin spots, mainly central with some cheek extension. Estimated sebum_quantity_index ~0.55–0.65 and distribution index ~0.25–0.35 yield a global index consistent with score 2.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "1 - Very Mild", "possible_causes": ["Pore congestion from sebum and keratin", "Comedogenic products or incomplete cleansing"], "score_explanation": "White and PPL images (1/8, 2/8) reveal few comedones over the nose and medial cheeks, minimal erythema, and no nodules. UV (5/8) shows scattered porphyrin dots without dense clustering. Total lesion count is in the 3–10 range with low inflammatory ratio, consistent with Grade 1.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "2 - Mild", "possible_causes": ["Photoaging and repetitive expressions", "Surface dehydration"], "score_explanation": "PPL/XPL (2/8, 8/8) show fine static lines on the forehead and peri‑orbital region with shallow depth and limited density (depth index ~0.25–0.45; density ~0.2–0.4). These are visible on close inspection, matching Grade 2.", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "2 - Moderate Sensitivity", "possible_causes": ["Over‑exfoliation/actives disrupting barrier", "Environmental triggers (heat, wind, UV)"], "score_explanation": "Red mode (6/8) shows persistent erythema over the nose and malar cheeks; PPL (2/8) reveals fine flaking and slightly disrupted uniformity. Erythema intensity approximates 0.45–0.6 with vascular pattern index 0.3–0.5, meeting score 2.", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "2 - Mixed Distribution", "possible_causes": ["Variable sebaceous activity across zones", "Climate and skincare influencing spread"], "score_explanation": "UV (5/8) displays porphyrin fluorescence concentrated in T‑zone with extension onto medial/lateral cheeks; regional variance index ~0.4–0.6 and symmetry <0.4 indicate a mixed pattern rather than purely T‑zone only.", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "0 - Dull / Lackluster", "possible_causes": ["Surface dehydration and barrier compromise", "Accumulated superficial pigmentation"], "score_explanation": "White mode (1/8) shows low surface reflectance uniformity (<0.5) and decreased luminance due to widespread pigmentation and dehydration; subsurface diffusion is limited and shadows are not soft, fulfilling the dull/low‑glow criteria.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "2 - Mild", "possible_causes": ["Increased central sebum output", "Early elasticity decline with age"], "score_explanation": "PPL (2/8) shows visible pores on the nose and medial cheeks approximating a 1.3–1.6× pore diameter increase vs baseline with slightly uneven reflection; white mode confirms mild roughness. These findings align with Grade 2.", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "2 - Moderate", "possible_causes": ["Sun sensitivity or early rosacea tendency", "Irritation from actives/fragrance"], "score_explanation": "Red and XPL modes (6/8, 8/8) show diffuse erythema across nose and malar cheeks with moderate vessel pattern density and color uniformity around 0.6–0.8, consistent with a moderate vascularity score.", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "4 - Marked", "possible_causes": ["Chronic photoexposure/photoaging", "Post‑inflammatory hyperpigmentation or hormonal effects"], "score_explanation": "Brown mode (7/8) demonstrates confluent dark macules and patches across the forehead and malar cheeks with ~40–60% coverage and high intensity; UV (5/8) enhances multiple spots indicating mixed depth. Uneven contrast and broad regional involvement meet score 4 thresholds.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "2 - Moderate", "possible_causes": ["Post‑inflammatory textural change", "Photoaging-related collagen remodeling"], "score_explanation": "PPL (2/8) exhibits micro‑roughness and patchy light distribution with shallow micro‑shadows along prior acne sites; indices (microtexture variance ~0.5–0.7; surface gradient ~0.45–0.6) align with a moderate classification.", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "2 - Moderate", "possible_causes": ["Thin dermis with visible venous plexus", "Early fat pad descent/volume loss"], "score_explanation": "XPL (8/8) highlights bluish‑purple coloration and linear shadowing along the tear trough suggesting vascular pigmentation combined with mild structural hollowing; not severe or confluent, matching Score 2.", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1–2 (Minimal to Mild)", "current_score": "4 - Marked"}, {"parameter": "Visual Acne Grading", "target_score": "0 - Clear", "current_score": "1 - Very Mild"}, {"parameter": "Texture + Open Pores Grading", "target_score": "0–1 (Clear to Very Mild)", "current_score": "2 - Mild"}, {"parameter": "Superficial Wrinkles", "target_score": "1 - Very Mild", "current_score": "2 - Mild"}, {"parameter": "Jawline Sagging", "target_score": "1 - Very Mild", "current_score": "2 - Mild"}, {"parameter": "Skin Hydration", "target_score": "0 - Excellent Hydration", "current_score": "2 - Moderate Dehydration"}, {"parameter": "Skin Sebum Content", "target_score": "1 - Low-Normal", "current_score": "2 - Moderate / Normal-Oily"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0–1 (No to Mild Sensitivity)", "current_score": "2 - Moderate Sensitivity"}, {"parameter": "Barrier Health", "target_score": "0–1 (Strong to Mildly Compromised)", "current_score": "2 - Moderately Compromised Barrier"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0–1 (None to Mild)", "current_score": "2 - Moderate"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "0–1 (None to Mild)", "current_score": "2 - Moderate"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2–3 (Healthy to Radiant)", "current_score": "0 - Dull / Lackluster"}, {"parameter": "Comedonal Density", "target_score": "0–1 (None to Mild)", "current_score": "2 - Moderate"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0–1 (Smooth to Mild)", "current_score": "2 - Moderate"}, {"parameter": "Regional Oil Distribution", "target_score": "0–1 (Even or T‑zone Predominant only)", "current_score": "2 - Mixed Distribution"}]}}',
                'post_diagnosis' => NULL,
            'parameters_with_abnormal_scores' => '{"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1–2 (Minimal to Mild)", "current_score": "4 - Marked"}, {"parameter": "Visual Acne Grading", "target_score": "0 - Clear", "current_score": "1 - Very Mild"}, {"parameter": "Texture + Open Pores Grading", "target_score": "0–1 (Clear to Very Mild)", "current_score": "2 - Mild"}, {"parameter": "Superficial Wrinkles", "target_score": "1 - Very Mild", "current_score": "2 - Mild"}, {"parameter": "Jawline Sagging", "target_score": "1 - Very Mild", "current_score": "2 - Mild"}, {"parameter": "Skin Hydration", "target_score": "0 - Excellent Hydration", "current_score": "2 - Moderate Dehydration"}, {"parameter": "Skin Sebum Content", "target_score": "1 - Low-Normal", "current_score": "2 - Moderate / Normal-Oily"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0–1 (No to Mild Sensitivity)", "current_score": "2 - Moderate Sensitivity"}, {"parameter": "Barrier Health", "target_score": "0–1 (Strong to Mildly Compromised)", "current_score": "2 - Moderately Compromised Barrier"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0–1 (None to Mild)", "current_score": "2 - Moderate"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "0–1 (None to Mild)", "current_score": "2 - Moderate"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2–3 (Healthy to Radiant)", "current_score": "0 - Dull / Lackluster"}, {"parameter": "Comedonal Density", "target_score": "0–1 (None to Mild)", "current_score": "2 - Moderate"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0–1 (Smooth to Mild)", "current_score": "2 - Moderate"}, {"parameter": "Regional Oil Distribution", "target_score": "0–1 (Even or T‑zone Predominant only)", "current_score": "2 - Mixed Distribution"}]}',
