                'breastfeeding' => 'no',
            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Genetic sebaceous distribution", "Climate and hormonal variability"], "score_explanation": "White-light image shows higher specular shine on the nose and central forehead with relatively matte cheeks. UV/Woods images reveal clustered porphyrin fluorescence confined mainly to the T‑zone while cheeks remain comparatively quiet. PPL view shows moderately larger pores in the T‑zone and smaller pores laterally. Together these fulfill the T‑zone-dominant oil with drier cheeks pattern consistent with Combination skin.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "Score 1", "possible_causes": ["Under-moisturizing and low ceramide support", "Occasional over-cleansing or exfoliation"], "score_explanation": "PPL shows generally smooth surface with mild roughness; white-mode hydration signal is slightly reduced and there is faint cheek redness with minimal flaking. Indices align with surface_texture_uniformity 0.7–0.85 and hydration 0.45–0.65 with mild erythema, indicating a Mildly Compromised Barrier (Score 1).", "affected_area_image": "3"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "Score 2", "possible_causes": ["Insufficient moisturization or humectants", "Air-conditioned/dry environment"], "score_explanation": "White mode shows mild dullness and fine micro-lines; blue/UV modes display scattered superficial flake-like highlights on cheeks and around eyes with only moderate subsurface diffusion under red lighting. These indicate surface_reflectance index in the 0.35–0.50 range with microline density 0.25–0.35, consistent with Moderate Dehydration (Score 2).", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 2", "possible_causes": ["Age-related collagen/elastic fiber decline", "Lifestyle factors affecting skin firmness"], "score_explanation": "White-light contour shows slight blunting along the mandibular line with minimal submandibular shadowing and early jowl prominence near the angles. These findings align with mild geometric change and laxity, mapping to Grade 2.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure without lip SPF", "Dehydration or lifestyle factors (e.g., hot beverages, smoking history)"], "score_explanation": "Across white and brown modes, the lips show a darker tone than adjacent skin with mild patchiness, confirming presence of lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "Score 1", "possible_causes": ["T‑zone oil with keratin plug formation", "Use of occlusive/comedogenic products"], "score_explanation": "UV/PPL modes show scattered comedones concentrated on the nose with small localized clusters; porphyrin overlap is present but limited. Estimated comedone density in the 0.05–0.15 band with scattered clustering fits Mild activity (Score 1).", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Anatomical tear‑trough hollowing with thin periorbital skin", "Sleep/stress and microvascular congestion"], "score_explanation": "XPL view demonstrates mild puffiness of upper lids, a visible tear‑trough hollow with shadowing, and mild brown‑violet discoloration under the eyes. Combined features place overall peri‑orbital status at a Moderate severity level.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "Score 2", "possible_causes": ["Hormonal sebum regulation", "T‑zone gland density"], "score_explanation": "White light shows moderate shine on nose/forehead; UV/Woods reveal multiple orange‑red porphyrin dots concentrated on the nose with fewer on cheeks. This yields a sebum_quantity_index in the 0.5–0.7 band and a T‑zone-biased distribution index around 0.2–0.4, mapping to Moderate/Normal‑Oily (Score 2).", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1", "possible_causes": ["T‑zone sebum accumulation clogging pores", "Comedogenic residue or inconsistent cleansing"], "score_explanation": "White/UV views show a few comedonal lesions predominantly on the nose and medial cheeks with scattered porphyrin dots but no nodules and minimal inflammatory redness. Estimated total lesion count falls in the 3–10 range and inflammatory ratio is low, fitting Grade 1 - Very Mild.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 2", "possible_causes": ["Early photoaging", "Dehydration of the stratum corneum"], "score_explanation": "PPL/XPL views reveal fine lines on the forehead and peri‑orbital areas visible at rest without deep furrows. The pattern suggests wrinkle_depth_index and density in the mild bands, consistent with Grade 2.", "affected_area_image": "3"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "Score 1", "possible_causes": ["Transient vasoreactivity to heat or products", "Slight barrier disruption from cleansers/exfoliants"], "score_explanation": "Red-light imaging shows faint erythema over the cheeks and nose without prominent vascular patterns; PPL indicates relatively intact barrier with only slight unevenness. Erythema intensity falls in the mild band and vascular index low, consistent with Mild Sensitivity (Score 1).", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "Score 1", "possible_causes": ["Higher sebaceous gland density in T‑zone", "Hormonal and environmental influences"], "score_explanation": "UV images reveal porphyrin fluorescence centered on the nose and central forehead with relatively quiet cheeks; white mode shows corresponding shine pattern. Regional variance and porphyrin distribution indices align with T‑zone predominant pattern (Score 1).", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "Score 1", "possible_causes": ["Dehydration reducing optical diffusion", "Mottled pigmentation and mild texture unevenness"], "score_explanation": "White mode shows moderate reflectance but some patchiness from pigmentation and texture; PPL indicates only modest subsurface diffusion and soft highlights are limited. Indices align with surface_reflectance_uniformity around 0.5–0.7 and luminance 0.4–0.6, consistent with Mild Glow (Score 1).", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2", "possible_causes": ["Genetic pore size with T‑zone oiliness", "Loss of elasticity around pores from photoaging"], "score_explanation": "PPL image shows visible pores on nose and extending to medial cheeks with mild surface roughness; pore diameter appears around 1.3–1.6× baseline on central face while lateral cheeks remain finer. Reflection pattern is slightly uneven but not coarse, corresponding to Mild (Grade 2).", "affected_area_image": "3"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "Score 1", "possible_causes": ["Heat or product-induced flushing", "Early background telangiectasia from sun exposure"], "score_explanation": "Red/XPL modes show faint diffuse cheek and nasal erythema with minimal detectable linear vessels and fairly even color distribution. Erythema intensity is in the 0.25–0.45 band with low vascular density, mapping to Mild (Score 1).", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "3 - Moderate", "possible_causes": ["Chronic sun exposure", "Post-inflammatory hyperpigmentation from previous breakouts or irritation"], "score_explanation": "Brown-mode image shows mottled macules across forehead, malar cheeks and nasal sidewalls with coverage roughly 20–40% of visible skin. Mean intensity is mid-toned (not very dark) and distribution is uneven (contrast uniformity in the moderate mottling band). UV enhancement is present but not confluent, indicating mostly epidermal to mixed depth. These match the score-3 criteria.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "Score 1", "possible_causes": ["Residual PIH/PIE and minor post-acne changes", "Surface dehydration and daily friction"], "score_explanation": "PPL indicates fine micro-roughness with occasional shallow shadowing along previous spots but no deep undulation or scarring. Microtexture variance and surface gradient fall within the mild bands, giving a Mild score (1).", "affected_area_image": "3"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2", "possible_causes": ["Thin periorbital skin with visible vasculature", "Anatomical hollowness creating shadowing"], "score_explanation": "XPL/UV views show bluish-violet hue under the eyes with a clear tear‑trough shadow; vascular tint is notable and accentuated without severe darkness. This corresponds to Moderate under‑eye darkness with vascular contribution and structural hollowing (Score 2).", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "3 - Moderate"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0–1", "current_score": "Grade 2"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1", "current_score": "Grade 2"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1", "current_score": "Grade 2"}, {"parameter": "Skin Hydration", "target_score": "Score 0–1", "current_score": "Score 2"}, {"parameter": "Skin Sebum Content", "target_score": "Score 1 (Low-Normal)", "current_score": "Score 2"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Barrier Health", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0–1", "current_score": "Score 2"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3", "current_score": "Score 1"}, {"parameter": "Comedonal Density", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0", "current_score": "Score 1"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 (Even / Balanced)", "current_score": "Score 1"}]}}',
