                'is_pregnant' => 0,
                'breastfeeding' => 'no',
            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Greater sebaceous activity in T‑zone vs cheeks", "Age-related reduction in cheek sebum and barrier function"], "score_explanation": "White light images show a generally matte appearance with slightly increased shine on the nose and central forehead compared with the cheeks; UV mode reveals porphyrin fluorescence mainly in the T‑zone with minimal signal on the cheeks; PPL displays pores that are moderate centrally and small on the cheeks. The higher T‑zone vs cheek contrast across modes fulfills the Combination criteria.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "1", "possible_causes": ["Suboptimal hydration routine", "Cumulative mild irritation from cleansers or active ingredients"], "score_explanation": "PPL indicates surface texture uniformity around 0.7–0.8; white-mode hydration signal is slightly low and erythema is mild, with minimal micro‑flaking. The composite index aligns with a Mildly Compromised barrier.", "affected_area_image": "3"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "2", "possible_causes": ["Inadequate moisturization and environmental low humidity", "Compromised barrier leading to increased transepidermal water loss"], "score_explanation": "White mode shows subdued, patchy highlights (surface reflectance ~0.40–0.50); PPL indicates increased micro‑line density (~0.25–0.35) and red mode shows only moderate subsurface diffusion. Combined indices indicate Moderate dehydration.", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 3", "possible_causes": ["Age-related soft tissue descent and ligament laxity", "Loss of dermal collagen/elasticity"], "score_explanation": "White light shows blunting of the mandibular contour with visible jowl formation and submandibular shadowing; implied mandibular angle change ~10–14° and reduced contour smoothness align with Moderate sagging.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Chronic sun exposure without lip SPF", "Post‑inflammatory or constitutional pigmentation"], "score_explanation": "Brown-filter image shows the lips noticeably darker than adjacent perioral skin with a uniform-to-patchy pattern, confirming presence of pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "1", "possible_causes": ["Localized T‑zone oil and dead skin buildup", "Irregular pore cleansing/exfoliation habits"], "score_explanation": "UV mapping shows scattered follicular plugs mainly on the nose with comedone density around 0.08–0.12 and cluster index near 0.3; porphyrin overlap is partial, consistent with Mild comedonal activity.", "affected_area_image": "4"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Dermal thinning with vascular show-through", "Periorbital hyperpigmentation and early fat pad changes"], "score_explanation": "Under-eye areas show brown‑bluish discoloration with visible creasing and slight puffiness; XPL/UV enhance vascular coloration while white light demonstrates structural trough shadowing. Combined features indicate overall Moderate peri‑orbital concern.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "1", "possible_causes": ["Age-related decline in sebaceous output on cheeks", "Cleansing habits reducing surface oil"], "score_explanation": "Surface shine in white light is mild (≈0.4–0.5) and UV reveals few porphyrins localized to the T‑zone (≈20–35). The integrated quantity index is low‑normal with a modest T‑zone predominance, mapping to Score 1.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1", "possible_causes": ["T‑zone keratin plug formation in enlarged pores", "Intermittent oil buildup with insufficient exfoliation"], "score_explanation": "White and UV images show a few comedonal lesions concentrated on the nose/medial cheeks; inflammatory papules or pustules are rare and nodules are absent. Total lesion count appears <10 with inflammatory ratio <0.25—consistent with Very Mild acne.", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 3", "possible_causes": ["Chronological collagen/elastin reduction", "Cumulative photoaging"], "score_explanation": "Peri‑orbital, forehead, and nasolabial regions display clearly visible lines under PPL/XPL with moderate depth and density (depth index ~0.5; density index ~0.45). Lines are apparent at rest and from conversational distance—meeting Moderate severity.", "affected_area_image": "3"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "1", "possible_causes": ["Mild barrier impairment due to dryness", "Environmental reactivity (temperature changes, detergents)"], "score_explanation": "Red-mode imaging shows mild diffuse erythema over the cheeks (erythema index ~0.3–0.4) with low vascular pattern density (<0.3) and slightly reduced barrier uniformity without significant flaking. These findings correspond to Mild sensitivity.", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "1", "possible_causes": ["Higher sebaceous gland density in central face", "Skincare that controls oil more on cheeks leading to contrast"], "score_explanation": "UV/white modes show higher reflectance and porphyrins on the nose and central forehead relative to the cheeks, giving a regional variance index around 0.3 and porphyrin distribution index ~0.35, characteristic of a T‑zone predominant pattern.", "affected_area_image": "4"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "0", "possible_causes": ["Dehydration decreasing surface smoothness/light spread", "Patchy pigmentation reducing brightness"], "score_explanation": "White mode demonstrates low reflectance uniformity (~0.5) and LAB luminance is subdued (~0.45–0.55); subsurface diffusion is moderate and shadow contrast remains noticeable, yielding a global glow index in the Dull range.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2", "possible_causes": ["Loss of dermal support with age causing widened pores", "Past comedonal activity and surface congestion"], "score_explanation": "PPL view shows visible pores on the nose and medial cheeks with a pore diameter ratio around 1.3–1.5× baseline and texture uniformity ~0.6–0.75; specular reflection is mildly uneven. These indices correspond to Mild texture/pores.", "affected_area_image": "3"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "1", "possible_causes": ["Reactive flushing with dryness", "Early photo-damage affecting superficial vessels"], "score_explanation": "Red mode reveals low‑to‑mild erythema intensity across cheeks and nose with sparse linear vascular features and overall color uniformity around 0.7–0.8. Weighted indices map to Mild vascularity/redness.", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "4 - Marked", "possible_causes": ["Chronic UV exposure and photoaging", "Post‑inflammatory hyperpigmentation and hormonal/age-related melanin changes"], "score_explanation": "Brown mode highlights numerous macules and confluent patches across the cheeks, forehead, and chin with coverage ~40–60% and mean darkness in the 0.65–0.75 band; UV/woods views enhance several of these areas indicating mixed epidermal–dermal components. The mottled/patchy distribution and intensity match a Marked score.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "2", "possible_causes": ["Post‑inflammatory changes from previous breakouts", "Chronic dehydration contributing to surface unevenness"], "score_explanation": "PPL reveals elevated microtexture variance (~0.5–0.6) and surface gradient irregularity (~0.5) with subtle micro‑shadows on oblique light but without deep pits, indicating Moderate superficial roughness.", "affected_area_image": "3"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2 - Moderate", "possible_causes": ["Vascular prominence through thin peri‑orbital skin", "Anatomical trough/hollowness causing shadowing"], "score_explanation": "XPL shows bluish-purple hue beneath eyes accentuated in UV, and white light displays tear‑trough shadowing; severity is more than mild but not severe, consistent with Moderate vascular pigmentation plus structural hollowing.", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1-2 (Minimal to Mild)", "current_score": "4 - Marked", "is_primary_concern": "false"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 (Clear)", "current_score": "Grade 1", "is_primary_concern": "false"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0-1", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1-2", "current_score": "Grade 3", "is_primary_concern": "false"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1-2", "current_score": "Grade 3", "is_primary_concern": "false"}, {"parameter": "Skin Hydration", "target_score": "0-1 (Excellent to Mild Dehydration)", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Skin Sebum Content", "target_score": "1-2 (Balanced/Normal-Oily)", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 (No Sensitivity)", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Barrier Health", "target_score": "0 (Strong / Healthy Barrier)", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "PeriOrbital Health", "target_score": "None - Mild", "current_score": "Moderate", "is_primary_concern": "false"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present", "is_primary_concern": "false"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0-1", "current_score": "Score 2 - Moderate", "is_primary_concern": "false"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2-3 (Healthy to Radiant Glow)", "current_score": "0", "is_primary_concern": "false"}, {"parameter": "Comedonal Density", "target_score": "0", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0-1", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Regional Oil Distribution", "target_score": "0 (Even / Balanced)", "current_score": "1", "is_primary_concern": "false"}]}}',
                'post_diagnosis' => '{"metadata": {"phase": "reassessment", "evaluation_type": "post_treatment", "treatment_session": "Session 1"}, "reassessment": {"skin_type": {"before_image": "1", "parameter_name": "Skin Type", "post_treatment_image": "1", "post_treatment_score_or_label": "Combination Skin", "before_treatment_score_or_label": "Combination Skin"}, "barrier_health": {"before_image": "3", "parameter_name": "Barrier Health", "post_treatment_image": "3", "post_treatment_score_or_label": "1", "before_treatment_score_or_label": "1"}, "skin_hydration": {"before_image": "1", "parameter_name": "Skin Hydration", "post_treatment_image": "1", "post_treatment_score_or_label": "1", "before_treatment_score_or_label": "2"}, "jawline_sagging": {"before_image": "1", "parameter_name": "Jawline Sagging", "post_treatment_image": "1", "post_treatment_score_or_label": "Grade 3", "before_treatment_score_or_label": "Grade 3"}, "lip_pigmentation": {"before_image": "7", "parameter_name": "Lip Pigmentation", "post_treatment_image": "7", "post_treatment_score_or_label": "Present", "before_treatment_score_or_label": "Present"}, "comedonal_density": {"before_image": "4", "parameter_name": "Comedonal Density", "post_treatment_image": "4", "post_treatment_score_or_label": "0", "before_treatment_score_or_label": "1"}, "periorbital_health": {"before_image": "8", "parameter_name": "Periorbital Health", "post_treatment_image": "8", "post_treatment_score_or_label": "Mild", "before_treatment_score_or_label": "Moderate"}, "skin_sebum_content": {"before_image": "1", "parameter_name": "Skin Sebum Content", "post_treatment_image": "1", "post_treatment_score_or_label": "1", "before_treatment_score_or_label": "1"}, "visual_acne_grading": {"before_image": "1", "parameter_name": "Visual Acne Grading", "post_treatment_image": "1", "post_treatment_score_or_label": "Grade 1", "before_treatment_score_or_label": "Grade 1"}, "superficial_wrinkles": {"before_image": "3", "parameter_name": "Superficia