ant Glow)", "current_score": "0", "is_primary_concern": false}, {"parameter": "Comedonal Density", "target_score": "0", "current_score": "1", "is_primary_concern": false}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0-1", "current_score": "2", "is_primary_concern": false}, {"parameter": "Regional Oil Distribution", "target_score": "0 (Even / Balanced)", "current_score": "1", "is_primary_concern": false}]}',
