                'breastfeeding' => 'no',
            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Genetic sebum distribution pattern", "Climate and hormonal modulation of T‑zone oil"], "score_explanation": "White-light images (1/8, 3/8) show moderate shine with a clear T‑zone > cheeks difference (delta reflectance ≈ ≥0.3). UV/Woods images (5/8, 4/8) show porphyrin fluorescence concentrated on nose/forehead while cheeks remain comparatively low (T‑zone ≥40, cheeks <25). PPL image (2/8) shows pores moderate/enlarged on T‑zone and small on cheeks. This fulfills the Combination criteria per decision logic with highest weighted confidence from white (0.45) and UV (0.35).", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "Score 1", "possible_causes": ["Over‑cleansing or insufficient emollients", "Occasional exposure to irritants or actives without buffer"], "score_explanation": "PPL (2/8) indicates mild texture roughness (surface_texture_uniformity ~0.7–0.8). White mode reflectance suggests slightly low hydration (~0.50–0.60) and only mild redness (<0.45). Minimal flaking visible under UV/Woods. These align with Mildly Compromised Barrier (Score 1).", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "Score 2", "possible_causes": ["Insufficient moisturization or transepidermal water loss", "Frequent cleansing or low ambient humidity"], "score_explanation": "White mode (1/8) shows slight dullness and patchy reflectance; PPL (2/8) reveals mild micro‑line density; red mode (6/8) shows only moderate subsurface diffusion (not strong). Indices align with surface_reflectance ~0.35–0.50 to 0.55–0.65 mixed and microline density ~0.25–0.35, consistent with Moderate Dehydration (Score 2).", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 1", "possible_causes": ["Normal facial soft‑tissue anatomy", "Early collagen/elastin variation with age"], "score_explanation": "White/XPL views (1/8, 8/8) show a clean mandibular contour with minimal blunting; estimated mandibular angle change <5° and high contour smoothness (>0.85). This meets Very Mild sagging.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Chronic sun exposure without lip SPF", "Post‑inflammatory or genetic pigmentation tendency"], "score_explanation": "Brown/XPL/white images (7/8, 8/8, 1/8) reveal lips slightly darker than surrounding perioral skin with uniform tone; this confirms presence of lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "Score 1", "possible_causes": ["T‑zone oiliness with keratin plug formation", "Irregular exfoliation or pore‑clogging cosmetics"], "score_explanation": "PPL and UV (2/8, 5/8) show scattered comedones mainly on nose with low cluster index (<0.4) and density roughly 2–5 lesions/cm² (0.05–0.15). Porphyrin overlap is limited. This supports Mild Comedonal Activity (Score 1).", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Mild", "possible_causes": ["Thin peri‑orbital skin with visible vasculature", "Sleep irregularity or eye strain"], "score_explanation": "XPL/white modes (8/8, 1/8) show slight under‑eye darkening with minimal puffiness or hollowness and faint vascular tint; no marked structural troughs. Overall severity fits Mild across pigmentation/vascularity dimensions.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "Score 2", "possible_causes": ["Hormonal stimulation of sebaceous glands", "Warm/humid environment increasing oiliness"], "score_explanation": "White light shows moderate T‑zone sheen; UV/Woods (5/8, 4/8) display multiple porphyrin dots on nose/forehead. The combined shine and fluorescence suggest sebum_quantity_index ~0.55–0.65 with a T‑zone dominant distribution (distribution index ~0.25–0.35). This maps to Moderate / Normal‑Oily (Score 2).", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1", "possible_causes": ["T‑zone oil with pore congestion", "Comedogenic products or inadequate cleansing around nose"], "score_explanation": "White/PPL images (1/8, 2/8) show a few comedones predominantly on the nose and scattered tiny macules on cheeks; inflamed papules/pustules are rare → total lesion count appears within 3–10 and inflammatory ratio <0.25. UV (5/8) shows scattered porphyrin dots without clustering. This aligns with Very Mild (Grade 1).", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 1", "possible_causes": ["Early dehydration lines", "Habitual facial expressions with thin peri‑orbital skin"], "score_explanation": "PPL/XPL views (2/8, 8/8) show only faint micro‑lines on forehead/peri‑orbital areas with very low depth and density (depth index <0.25; density <0.2 by visual estimate). Smooth white‑mode reflections corroborate a Very Mild grade.", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "Score 1", "possible_causes": ["Transient flushing/heat or product use", "Slight barrier disruption from dehydration"], "score_explanation": "Red/PPL views (6/8, 2/8) show faint cheek/nasal erythema with low vascular pattern visibility. Estimated erythema_intensity ~0.3–0.4, vascular_pattern_index <0.3, and barrier_uniformity mildly reduced. These meet Mild Sensitivity (Score 1).", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "Score 1", "possible_causes": ["Higher sebaceous gland density in T‑zone", "Daily heat/exertion increasing central face oil"], "score_explanation": "White and UV (1/8, 5/8) demonstrate higher reflectance and porphyrin concentration on forehead, nose, and chin with comparatively matte cheeks. Regional variance falls in 0.2–0.4 and porphyrin distribution 0.25–0.45, indicating a T‑zone Predominant pattern (Score 1).", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "Score 1", "possible_causes": ["Dehydration reducing translucency", "Patchy superficial pigmentation lowering brightness"], "score_explanation": "White/PPL (1/8, 2/8) show moderate surface reflectance uniformity (~0.55–0.65) and color luminance around 0.5; subsurface diffusion is moderate and shadow contrast not harsh. This matches Mild Glow (Score 1) rather than dull or radiant extremes.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2", "possible_causes": ["Increased sebum output in T‑zone", "Previous comedones stretching pore openings"], "score_explanation": "PPL mode (2/8) demonstrates visible pores on nose and medial cheeks with pore diameter ratio visually in the 1.3–1.6 range and texture uniformity around 0.6–0.8. White-light reflection shows minor unevenness. This maps to Mild (Grade 2) on the Bitmoji A5 scale.", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "Score 1", "possible_causes": ["Heat, exercise, or temporary irritation", "Early vascular reactivity in sensitive skin"], "score_explanation": "Red/PPL modes (6/8, 2/8) show faint cheek/nasal erythema with low vessel‑like linear features; symmetry is good and color uniformity only mildly patchy (uniformity >0.7). Erythema and vascular density fall in mild bins → final score 1.", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "4 - Marked", "possible_causes": ["Cumulative sun exposure without adequate SPF", "Post‑inflammatory hyperpigmentation from previous acne or irritation"], "score_explanation": "Brown-mode image (7/8) reveals confluent macules and patches over forehead, malar cheeks and nose with estimated coverage ~45–55% (marked). Mean intensity appears in the 0.65–0.75 band with mottled/uneven contrast uniformity ~0.55–0.70. UV enhancement is moderate, suggesting mixed epidermal‑dermal depth. These meet the ‘Marked’ bin per v3.2 thresholds.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "Score 1", "possible_causes": ["Dehydration-related micro‑roughness", "Post‑inflammatory subtle textural change from past acne"], "score_explanation": "PPL/brown (2/8, 7/8) show fine, superficial roughness with minimal micro‑shadows and slight undulation (microtexture variance ~0.3–0.5; surface gradient <0.45). These meet Mild irregularities (Score 1).", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 1", "possible_causes": ["Thin skin allowing vessels to show through", "Mild volume deficit or lighting angle creating slight shadow"], "score_explanation": "XPL (8/8) displays faint bluish tint along infraorbital area with minimal shadowing and no deep hollowness. Features correspond to mild vascular pigmentation with mild shadowing → Score 1.", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Skin Type", "target_score": "Normal/Balanced Skin", "current_score": "Combination Skin", "is_primary_concern": "false"}, {"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "4 - Marked", "is_primary_concern": "false"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1", "is_primary_concern": "false"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0 - Clear / Smooth", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 (Very Mild) or lower appearance with hydration", "current_score": "Grade 1", "is_primary_concern": "false"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 (Very Mild) / stable", "current_score": "Grade 1", "is_primary_concern": "false"}, {"parameter": "Skin Hydration", "target_score": "Score 0 - Excellent Hydration", "current_score": "Score 2", "is_primary_concern": "false"}, {"parameter": "Skin Sebum Content", "target_score": "Score 1 (Low-Normal Sebum)", "current_score": "Score 2", "is_primary_concern": "false"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0 - No Sensitivity", "current_score": "Score 1", "is_primary_concern": "false"}, {"parameter": "Barrier Health", "target_score": "Score 0 - Strong / Healthy Barrier", "current_score": "Score 1", "is_primary_concern": "false"}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Mild", "is_primary_concern": "false"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present", "is_primary_concern": "false"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0 - No Vascularity / Redness", "current_score": "Score 1", "is_primary_concern": "false"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0 - None", "current_score": "Score 1", "is_primary_concern": "false"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "Score 2–3 (Healthy to Radiant)", "current_score": "Score 1", "is_primary_concern": "false"}, {"parameter": "Comedonal Density", "target_score": "Score 0 - No Comedones", "current_score": "Score 1", "is_primary_concern": "false"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "Score 0 - Smooth / Even Texture", "current_score": "Score 1", "is_primary_concern": "false"}, {"parameter": "Regional Oil Distribution", "target_score": "Score 0 - Even / Balanced Oil Distribution", "current_score": "Score 1", "is_primary_concern": "false"}]}}',
