            'parameters_with_abnormal_scores' => '{"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Skin Type", "target_score": "Normal/Balanced Skin", "current_score": "Combination Skin", "is_primary_concern": false}, {"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "4 - Marked", "is_primary_concern": false}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1", "is_primary_concern": false}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0 - Clear / Smooth", "current_score": "Grade 2", "is_primary_concern": false}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 (Very Mild) or lower appearance with hydration", "current_score": "Grade 1", "is_primary_concern": false}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 (Very Mild) / stable", "current_score": "Grade 1", "is_primary_concern": false}, {"parameter": "Skin Hydration", "target_score": "Score 0 - Excellent Hydration", "current_score": "Score 2", "is_primary_concern": false}, {"parameter": "Skin Sebum Content", "target_score": "Score 1 (Low-Normal Sebum)", "current_score": "Score 2", "is_primary_concern": false}, {"parameter": "Skin Sensitivity Scoring", "target_score": "Score 0 - No Sensitivity", "current_score": "Score 1", "is_primary_concern": false}, {"parameter": "Barrier Health", "target_score": "Score 0 - Strong / Healthy Barrier", "current_score": "Score 1", "is_primary_concern": false}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Mild", "is_primary_concern": false}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present", "is_primary_concern": false}, {"parameter": "Vascularity / Redness Profiling", "target_score": "Score 0 - No Vascularity / Redness", "current_score": "Scor