                'breastfeeding' => 'no',
            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Higher sebaceous gland density in the T‑zone", "Zone-specific skincare or environmental exposure"], "score_explanation": "White-light views show low-to-moderate overall shine with a clear T‑zone emphasis; cheeks appear comparatively matte. UV/Woods reveal porphyrin clusters concentrated on the nose and medial cheeks with relatively quiet lateral cheeks. PPL shows pores that are moderate/enlarged in the T‑zone but smaller on the cheeks. Together this meets the logic for Combination: localized T‑zone shine, T‑zone-only fluorescence (≥40) with cheeks <25, and larger pores centrally than laterally.", "affected_area_image": "3"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "1", "possible_causes": ["Insufficient moisturizer and lipid replenishment", "UV/photoexposure weakening the barrier"], "score_explanation": "PPL/white demonstrate slight roughness and dullness; hydration signal is moderately low and redness mild. Indices correspond to surface_texture_uniformity ~0.7–0.85, hydration_signal 0.45–0.65, redness_index 0.25–0.45 → Mildly compromised barrier (Score 1).", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "2", "possible_causes": ["Insufficient daily moisturization/humectants", "Barrier stress from UV exposure and cleansing habits"], "score_explanation": "White/PPL show patchy reflectance and fine micro‑lines; red/XPL indicate modest subsurface diffusion. Indices align with surface_reflectance 0.35–0.50, microline_density 0.25–0.35, subsurface_diffusion 0.55–0.70 → Moderate dehydration (Score 2).", "affected_area_image": "3"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 2", "possible_causes": ["Age‑related collagen/elastic fiber decline", "Subcutaneous fat redistribution and gravity"], "score_explanation": "White light shows slight blunting of the mandibular contour and early jowl formation at the angles without deep submandibular shadowing. Estimated mandibular angle change ~5–10° and contour smoothness 0.7–0.85 → Mild sagging (Grade 2).", "affected_area_image": "3"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure without lip SPF", "Post‑inflammatory or lifestyle factors/irritants"], "score_explanation": "Brown mode shows darker vermilion and perioral discoloration relative to surrounding skin, indicating lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "2", "possible_causes": ["Sebum accumulation with inadequate pore turnover", "Use of occlusive cosmetics or insufficient exfoliation"], "score_explanation": "UV/Woods show multiple orange‑red porphyrin dots clustered around the nose and medial cheeks; PPL confirms grouped pore openings. Estimated comedone_count_density 0.15–0.3 with cluster index 0.4–0.6 and partial porphyrin overlap → Moderate (Score 2).", "affected_area_image": "6"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Thin peri‑orbital skin with vascular show‑through", "Anatomical hollowing and chronic pigmentation"], "score_explanation": "Peri‑orbital zones show evident darkening with a mixed pigment‑vascular appearance and mild hollowing; lines are present but not severe. Overall burden across pigmentation/vascularity/hollowness sits in the Moderate band.", "affected_area_image": "2"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "2", "possible_causes": ["Physiologic sebaceous activity in the T‑zone", "Warm climate or occlusive cosmetics increasing oiliness"], "score_explanation": "UV/Woods reveal multiple porphyrin fluorescences mainly on the nose and central cheeks, while overall white-light shine is moderate. This yields a sebum_quantity_index around 0.5–0.6 with T‑zone bias, mapping to Moderate/normal‑oily (Score 2).", "affected_area_image": "3"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1", "possible_causes": ["Sebum buildup and pore congestion in the T‑zone", "Comedogenic products or infrequent exfoliation"], "score_explanation": "White/PPL images show a few comedones in the T‑zone and a healing spot on the chin; UV shows scattered porphyrin dots without dense clustering. Estimated total lesions 5–10 and inflammatory ratio <0.25 → Very Mild (Grade 1).", "affected_area_image": "3"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 2", "possible_causes": ["Early collagen/elastin changes from sun exposure", "Surface dehydration accentuating fine lines"], "score_explanation": "Cross/parallel polarized views reveal multiple fine lines on the forehead and peri‑orbital areas visible at rest but without deep etched furrows. Estimated indices: wrinkle_depth 0.25–0.45 and density 0.2–0.4 → Mild (Grade 2).", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "1", "possible_causes": ["Environmental triggers such as heat or UV", "Mild dehydration leading to transient reactivity"], "score_explanation": "Red/XPL views show mild diffuse cheek/nasal erythema with minimal visible vessels and largely intact barrier pattern. Estimated erythema intensity ~0.3–0.4, vascular pattern index <0.3, barrier uniformity slightly reduced → Mild sensitivity (Score 1).", "affected_area_image": "8"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "1", "possible_causes": ["Higher sebaceous activity centrally (physiologic pattern)", "Central occlusion/makeup use contributing to uneven oil"], "score_explanation": "UV images demonstrate porphyrins concentrated on the nose and central cheeks with comparatively matte lateral cheeks; white light mirrors this with localized shine. Regional variance 0.2–0.4 and porphyrin distribution 0.25–0.45 fit a T‑zone predominant pattern (Score 1).", "affected_area_image": "6"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "1", "possible_causes": ["Diffuse pigmentation reducing even reflectance", "Moderate dehydration and mild texture roughness"], "score_explanation": "White and PPL modes show moderate surface reflection but uneven brightness due to pigmentation and mild roughness; subsurface diffusion is modest. Surface_reflectance_uniformity ~0.5–0.7 and color_luminance_index 0.4–0.6 correspond to Mild Glow (Score 1).", "affected_area_image": "3"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2", "possible_causes": ["T‑zone oil output enlarging follicular openings", "Photoaging and long‑standing comedonal activity"], "score_explanation": "PPL shows visible pores on the nose and medial cheeks extending slightly laterally with diffuse mild roughness. This corresponds to a pore_diameter_ratio of ~1.3–1.6 and texture_uniformity 0.6–0.8 → Mild (Grade 2).", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "1", "possible_causes": ["Sun/heat exposure causing reactive vasodilation", "Mild barrier dryness contributing to redness"], "score_explanation": "Red mode reveals faint diffuse erythema on cheeks and nose with minimal linear vessel enhancement; color uniformity is slightly patchy. Erythema intensity ~0.3–0.4 and vascular pattern density ~0.25–0.35 → Mild (Score 1).", "affected_area_image": "8"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "4 - Marked", "possible_causes": ["Chronic sun exposure/photoaging", "Post‑inflammatory hyperpigmentation and hormonal influences"], "score_explanation": "Brown mode displays confluent macules and patches across the forehead, malar cheeks, nose and perioral area with coverage approaching 40–60%. Mean lesion darkness is high and tone is uneven (contrast uniformity around 0.6). UV enhances many lesions, indicating a mixed epidermal-dermal component. These map to coverage/intensity/homogeneity thresholds for a Marked score.", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "1", "possible_causes": ["Superficial photodamage and dehydration", "Post‑inflammatory surface changes from prior breakouts"], "score_explanation": "PPL reveals mild micro‑roughness with shallow micro‑shadows along previous lesions; no deep undulations or pits. Microtexture_variance ~0.3–0.5 and surface_gradient_irregularity 0.25–0.45 → Mild (Score 1).", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2", "possible_causes": ["Peri‑orbital vascular prominence in thin skin", "Anatomical hollowing generating structural shadows"], "score_explanation": "Under‑eye areas display bluish‑brown tone with noticeable shadowing along the tear trough and enhancement under polarized views, consistent with combined vascular pigmentation and mild hollowing. This maps to Moderate (Score 2).", "affected_area_image": "2"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "4 - Marked", "is_primary_concern": "false"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1", "is_primary_concern": "false"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0 - Clear / Smooth", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 - Very Mild", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Skin Hydration", "target_score": "0 - Excellent Hydration", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Skin Sebum Content", "target_score": "1 - Low-Normal Sebum", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 - No Sensitivity", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Barrier Health", "target_score": "0 - Strong / Healthy Barrier", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "PeriOrbital Health", "target_score": "None", "current_score": "Moderate", "is_primary_concern": "false"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present", "is_primary_concern": "false"}, {"parameter": "Vascularity / Redness Profiling (XPL / Red Light)", "target_score": "0 - No Vascularity / Redness", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "target_score": "Score 0 - None", "current_score": "Score 2", "is_primary_concern": "false"}, {"parameter": "Skin Luminosity / Glow Index (White / PPL)", "target_score": "3 - Radiant / Luminous Skin", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Comedonal Density (PPL / UV)", "target_score": "0 - No Comedones", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Texture Irregularities Beyond Pores (PPL / Brown)", "target_score": "0 - Smooth / Even Texture", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Regional Oil Distribution (White / UV)", "target_score": "0 - Even / Balanced Oil Distribution", "current_score": "1", "is_primary_concern": "false"}]}}',
