            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["Genetic predisposition to higher sebaceous activity in T-zone", "Environmental factors and daily habits leading to mixed oiliness and dehydration"], "score_explanation": "White light (1/8) shows localized shine centered on the forehead and nose with comparatively matte cheeks. UV mode (5/8) reveals porphyrin fluorescence clustered in the T‑zone rather than the cheeks. PPL/XPL (3/8, 8/8) show pores that are moderate-to-enlarged on the nose/medial cheeks but small on the lateral cheeks. This pattern fulfills the Combination criteria: higher T‑zone reflectance, T‑zone–only fluorescence, and larger pores limited to the T‑zone.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "2", "possible_causes": ["Inadequate moisturization and disrupted lipid balance", "UV exposure and intermittent irritation from grooming or products"], "score_explanation": "PPL (3/8) shows mild-to-moderate surface roughness and micro‑line visibility; white (1/8) reveals slight dullness; red/white demonstrate mild erythema. These indicate moderate compromise: reduced texture uniformity and lower hydration signals with mild redness and faint micro‑flaking.", "affected_area_image": "3"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "2", "possible_causes": ["Insufficient moisturization or humectants", "Environmental dehydration (air‑conditioning, sun exposure)"], "score_explanation": "White (1/8) shows reduced, patchy glow and mild micro‑scaling texture; PPL (3/8) highlights fine micro‑lines; red mode (6/8) indicates moderate subsurface diffusion rather than high. The combination suggests moderate dehydration according to the hydration scoring (surface reflectance 0.35–0.50 and microline density 0.25–0.35 tendencies).", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 2", "possible_causes": ["Early dermal collagen and elastin decline", "Fluid retention and habitual postures affecting lower‑face contour"], "score_explanation": "White/XPL views (1/8, 8/8) show slight blunting at the mandibular angle and softening of the lower‑cheek contour without pronounced jowls or deep submandibular shadowing, corresponding to a mild degree of sagging.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure without lip SPF", "Lifestyle factors such as heat, dehydration, or irritants"], "score_explanation": "Brown mode (2/8) shows the lips slightly darker than adjacent perioral skin with a uniform cast rather than focal lesions, consistent with mild lip hyperpigmentation.", "affected_area_image": "2"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "2", "possible_causes": ["Sebum accumulation and incomplete pore clearing", "Comedogenic products or inadequate makeup/sunscreen removal"], "score_explanation": "UV (5/8) shows moderate clusters of porphyrin fluorescence centered on the nose with extension to the central cheeks; PPL (3/8) corroborates visible comedones and pore congestion. Clustering is localized rather than confluent, consistent with Moderate comedonal activity.", "affected_area_image": "5"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Vascular congestion and thin under‑eye skin", "Post‑inflammatory or sun‑related pigmentation with mild volume loss"], "score_explanation": "Across white/PPL/XPL (1/8, 3/8, 8/8) there are noticeable under‑eye dark circles with a blend of pigmentation and vascular hue; minimal puffiness but some hollowness is apparent. The visibility from conversational distance categorizes the peri‑orbital concern as Moderate.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "2", "possible_causes": ["Genetic sebaceous activity concentrated in the T‑zone", "Warm climate or occlusive products increasing oil output"], "score_explanation": "White (1/8) shows moderate T‑zone sheen; UV (5/8) demonstrates multiple porphyrin fluorescence points centered on the nose/central forehead, indicating moderate sebum presence. Distribution is more T‑zone dominant than global. These match a moderate/normal‑oily level with T‑zone bias.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 1", "possible_causes": ["T‑zone oiliness leading to comedone formation", "Inconsistent cleansing or occlusive products"], "score_explanation": "White/PPL (1/8, 3/8) show a few comedones concentrated on the nose and central cheeks with minimal inflammatory papules. UV (5/8) shows scattered porphyrin fluorescence dots clustered around the nose but without dense, generalized fluorescence. Total lesion count appears low with a low inflammatory ratio, consistent with Very Mild acne (Grade 1).", "affected_area_image": "1"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 2", "possible_causes": ["Epidermal dehydration contributing to micro‑lines", "Photoaging from cumulative UV exposure"], "score_explanation": "PPL/XPL (3/8, 8/8) show fine dynamic lines on the forehead and peri‑orbital area visible at rest on close inspection, without deep etched grooves. Contrast in white mode is modest. This aligns with Mild wrinkles: shallow depth and low-to-moderate density.", "affected_area_image": "3"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "1", "possible_causes": ["Occasional irritant exposure or over‑cleansing", "Environmental temperature changes or shaving‑related reactivity"], "score_explanation": "Red mode (6/8) shows faint background erythema on cheeks and nose without dense telangiectatic networks. PPL indicates generally intact barrier with mild reflectance variability. These findings align with Mild sensitivity (low vascular prominence and slightly patchy redness).", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "1", "possible_causes": ["Higher density of sebaceous glands in the T‑zone", "Daily environment and stress increasing central sebum activity"], "score_explanation": "UV (5/8) and white (1/8) show shine and porphyrin fluorescence mainly in the T‑zone (forehead, nose, chin) with relatively matte cheeks. This pattern matches a T‑zone predominant distribution rather than mixed or global.", "affected_area_image": "5"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "1", "possible_causes": ["Dehydration and mild texture roughness reducing light scatter", "Uneven pigmentation dampening brightness"], "score_explanation": "White/PPL (1/8, 3/8) exhibit moderate reflectance uniformity with patchy brightness and soft highlights; subsurface diffusion is not high. Edge shadows are not harsh but present, yielding a Mild glow rather than healthy/radiant.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2", "possible_causes": ["Sebum accumulation and chronic T‑zone congestion", "Loss of collagen/elasticity around pore openings with age or sun exposure"], "score_explanation": "PPL (3/8) reveals visibly enlarged pores on the nose and medial cheeks with mild diffuse roughness; XPL/white confirm non-uniform reflection. The apparent pore size exceeds fine but not into very large, and texture uniformity is slightly reduced—matching the Mild category (pore_diameter_ratio approx. 1.3–1.6; texture 0.6–0.8).", "affected_area_image": "3"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "1", "possible_causes": ["Transient flushing or mild sensitivity", "Barrier dehydration increasing background redness"], "score_explanation": "Red/PPL modes (6/8, 3/8) reveal mild diffuse erythema on the central cheeks and nose with limited vessellike patterning and overall even color distribution. This corresponds to Mild vascularity/redness.", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "3 - Moderate", "possible_causes": ["Cumulative sun exposure without adequate broad-spectrum protection", "Post-inflammatory hyperpigmentation following acne or irritation"], "score_explanation": "Brown mode (2/8) displays mottled macules on the cheeks, temples, and nose with 20–40% coverage and mid-brown intensity. UV (5/8) enhances some of these areas but not diffusely, indicating a mostly epidermal/mixed depth. Tone is uneven with patchy borders rather than confluent dark patches, aligning with the Moderate (score 3) band.", "affected_area_image": "2"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "2", "possible_causes": ["Past acne leading to superficial textural changes", "Dehydration and photodamage altering surface uniformity"], "score_explanation": "PPL (3/8) demonstrates micro‑roughness and non‑uniform reflection on cheeks and forehead with subtle micro‑shadows; brown (2/8) shows post‑inflammatory marks contributing to surface unevenness. These findings represent Moderate textural irregularity.", "affected_area_image": "3"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2", "possible_causes": ["Subdermal vascular visibility through thin skin", "Anatomical hollowness causing persistent shadowing"], "score_explanation": "XPL and white (8/8, 1/8) show bluish‑brown discoloration with noticeable hollowing at the tear trough creating a visible shadow component. The color persists in cross‑polarized view, indicating mixed vascular/pigment with structural shadow—consistent with Moderate (Score 2).", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "3 - Moderate", "is_primary_concern": "false"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1", "is_primary_concern": "false"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0-1", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Skin Hydration", "target_score": "0-1", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Skin Sebum Content", "target_score": "1", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Barrier Health", "target_score": "0-1", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "PeriOrbital Health", "target_score": "Mild / None", "current_score": "Moderate", "is_primary_concern": "false"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present", "is_primary_concern": "false"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0-1", "current_score": "Score 2", "is_primary_concern": "false"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2-3", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Comedonal Density", "target_score": "0-1", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0-1", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Regional Oil Distribution", "target_score": "0", "current_score": "1", "is_primary_concern": "false"}]}}',
                'post_diagnosis' => '{"metadata": {"phase": "reassessment", "evaluation_type": "post_treatment", "treatment_session": "Session 1"}, "reassessment": {"skin_type": {"before_image": "1", "parameter_name": "Skin Type", "post_treatment_image": "1", "post_treatment_score_or_label": "Combination Skin", "before_treatment_score_or_label": "Combination Skin"}, "barrier_health": {"before_image": "3", "parameter_name": "Barrier Health", "post_treatment_image": "3", "post_treatment_score_or_label": "1", "before_treatment_score_or_label": "2"}, "skin_hydration": {"before_image": "1", "parameter_name": "Skin Hydration", "post_treatment_image": "1", "post_treatment_score_or_label": "1", "before_treatment_score_or_label": "2"}, "jawline_sagging": {"before_image": "1", "parameter_name": "Jawline Sagging", "post_treatment_image": "1", "post_treatment_score_or_label": "Grade 2", "before_treatment_score_or_label": "Grade 2"}, "lip_pigmentation": {"before_image": "2", "parameter_name": "Lip Pigmentation", "post_treatment_image": "2", "post_treatment_score_or_label": "Present", "before_treatment_score_or_label": "Present"}, "comedonal_density": {"before_image": "5", "parameter_name": "Comedonal Density", "post_treatment_image": "5", "post_treatment_score_or_label": "1", "before_treatment_score_or_label": "2"}, "periorbital_health": {"before_image": "8", "parameter_name": "Periorbital Health", "post_treatment_image": "8", "post_treatment_score_or_label": "Moderate", "before_treatment_score_or_label": "Moderate"}, "skin_sebum_content": {"before_image": "1", "parameter_name": "Skin Sebum Content", "post_treatment_image": "1", "post_treatment_score_or_label": "1", "before_treatment_score_or_label": "2"}, "visual_acne_grading": {"before_image": "1", "parameter_name": "Visual Acne Grading", "post_treatment_image": "1", "post_treatment_score_or_label": "Grade 1", "before_treatment_score_or_label": "Grade 1"}, "superficial_wrinkles": {"before_image": "3", "parameter_name": "Superf