                'parameters_with_abnormal_scores' => '{"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1 - Minimal / Almost Clear", "current_score": "3 - Moderate", "is_primary_concern": false}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0 - Clear", "current_score": "Grade 1", "is_primary_concern": false}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0-1", "current_score": "Grade 2", "is_primary_concern": false}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1", "current_score": "Grade 2", "is_primary_concern": false}, {"parameter": "Jawline Sagging", "target_score": "Grade 1", "current_score": "Grade 2", "is_primary_concern": false}, {"parameter": "Skin Hydration", "target_score": "0-1", "current_score": "2", "is_primary_concern": false}, {"parameter": "Skin Sebum Content", "target_score": "1", "current_score": "2", "is_primary_concern": false}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0", "current_score": "1", "is_primary_concern": false}, {"parameter": "Barrier Health", "target_score": "0-1", "current_score": "2", "is_primary_concern": false}, {"parameter": "PeriOrbital Health", "target_score": "Mild / None", "current_score": "Moderate", "is_primary_concern": false}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present", "is_primary_concern": false}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0", "current_score": "1", "is_primary_concern": false}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0-1", "current_score": "Score 2", "is_primary_concern": false}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2-3", "current_score": "1", "is_primary_concern": false}, {"parameter": "Comedonal Density", "target_score": "0-1", "curr