            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "This parameter identifies the primary characteristics of your skin, which can be oily, dry, combination, or normal. Understanding your skin type is the foundation for a proper skincare routine.", "parameter_name": "Skin Type", "score_or_label": "Combination Skin", "possible_causes": ["T‑zone sebaceous activity influenced by hormones", "Genetic distribution of pores and sebum glands"], "score_explanation": "White light shows localized shine confined to the T‑zone (forehead, nose, chin) while cheeks remain comparatively matte; UV mode reveals porphyrin fluorescence clustered on the nose rather than generalized; PPL images show visibly larger pores on the T‑zone with smaller pores on the cheeks. These meet the Combination criteria: shine_T‑zone > cheeks by a noticeable margin, UV fluorescence stronger in T‑zone, and pore size moderate/enlarged centrally but small laterally.", "affected_area_image": "1"}, "barrier_health": {"description": "This parameter evaluates the health of the skin\'s protective barrier, which is essential for retaining moisture and protecting against external aggressors.", "parameter_name": "Barrier Health", "score_or_label": "1", "possible_causes": ["Under‑moisturizing or over‑cleansing", "Environmental stressors such as pollution and AC"], "score_explanation": "PPL shows slight texture unevenness and fine peri‑oral flaking; hydration signal from white mode appears slightly low and there is mild central redness. Combined indices suggest surface_texture_uniformity ~0.7–0.85 and hydration_signal 0.45–0.65 with mild erythema, consistent with a Mildly Compromised barrier (Score 1).", "affected_area_image": "2"}, "skin_hydration": {"description": "This parameter measures the water content in the skin, which is crucial for maintaining a healthy skin barrier and a plump, youthful appearance.", "parameter_name": "Skin Hydration", "score_or_label": "2", "possible_causes": ["Insufficient moisturizer or humectants", "Air‑conditioning/indoor low‑humidity exposure"], "score_explanation": "White light shows a somewhat matte, slightly dull surface with patchy reflectance; PPL reveals increased micro‑line density over cheeks; red mode shows only moderate subsurface diffusion. These cues map to surface_reflectance 0.35–0.50 and microline_density 0.25–0.35, supporting Moderate Dehydration (Score 2).", "affected_area_image": "1"}, "jawline_sagging": {"description": "This parameter evaluates the firmness and definition of the jawline, which can be affected by loss of skin elasticity and gravity.", "parameter_name": "Jawline Sagging", "score_or_label": "Grade 1", "possible_causes": ["Early soft‑tissue laxity with age", "Posture and gravity effects over time"], "score_explanation": "White/XPL contours show a fairly sharp mandibular line with minimal blunting and no pronounced jowls; estimated mandibular angle change is <5° and contour smoothness remains high (>0.85). This fits Very Mild sagging.", "affected_area_image": "1"}, "lip_pigmentation": {"description": "This parameter assesses the presence of discoloration or dark spots on the lips.", "parameter_name": "Lip Pigmentation", "score_or_label": "Present", "possible_causes": ["Sun exposure without lip SPF", "Post‑inflammatory or habitual lip licking/smoking history"], "score_explanation": "Compared with surrounding skin, the lips appear darker and more uneven in brown/XPL modes with mild perioral pigmentation, supporting the presence of lip pigmentation.", "affected_area_image": "7"}, "comedonal_density": {"description": "Detection of open and closed comedones visible in polarized or UV imaging modes.", "parameter_name": "Comedonal Density (PPL / UV)", "score_or_label": "2", "possible_causes": ["T‑zone oil accumulation and dead‑cell buildup", "Irregular pore cleansing or occlusive cosmetics"], "score_explanation": "UV shows clustered porphyrin dots on the nose with additional lesions on chin and medial cheeks; spatial grouping is localized clusters rather than confluent. Estimated comedone density ~0.15–0.3 with cluster index ~0.4–0.6 and partial porphyrin overlap, consistent with Moderate (Score 2).", "affected_area_image": "4"}, "periorbital_health": {"description": "This parameter assesses the health of the skin around the eyes, including puffiness, hollowness, pigmentation, and vascularity.", "parameter_name": "PeriOrbital Health", "score_or_label": "Moderate", "possible_causes": ["Genetic/constitutional periorbital pigmentation", "Chronic eye strain or insufficient sleep"], "score_explanation": "Across XPL/white/brown modes there is visible under‑eye darkening with a brown‑to‑bluish cast, mild trough shadowing, and minimal puffiness. The combination of pigmentation with some vascular contribution places peri‑orbital changes in the Moderate range.", "affected_area_image": "8"}, "skin_sebum_content": {"description": "This parameter measures the amount of sebum (oil) produced by the sebaceous glands in the skin.", "parameter_name": "Skin Sebum Content", "score_or_label": "2", "possible_causes": ["Physiologic sebaceous activity in T‑zone", "Warm climate or occlusive makeup increasing shine"], "score_explanation": "White light exhibits noticeable T‑zone sheen while cheeks remain relatively matte; UV/Woods highlights multiple porphyrin dots concentrated on the nose, indicating active follicles. This yields a moderate sebum_quantity_index (~0.5–0.7) with a T‑zone‑biased distribution (sebum_distribution_index ~0.2–0.4), scoring 2 – Moderate/Normal‑Oily.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "This parameter assesses the severity of acne based on the number and type of lesions, such as blackheads, whiteheads, papules, and pustules.", "parameter_name": "Visual Acne Grading", "score_or_label": "Grade 2", "possible_causes": ["Sebum congestion in T‑zone", "Irregular cleansing or comedogenic products"], "score_explanation": "White/PPL views reveal scattered open/closed comedones with several small papules across T‑zone and chin; total visible lesions are roughly in the 11–25 range; UV shows clustered porphyrins over the nose indicating active follicles but no nodules/cysts. Inflammatory component is present but limited (~0.25–0.4), consistent with Grade 2 – Mild.", "affected_area_image": "3"}, "superficial_wrinkles": {"description": "This parameter assesses the presence and depth of superficial wrinkles and fine lines, which are early signs of aging.", "parameter_name": "Superficial Wrinkles", "score_or_label": "Grade 1", "possible_causes": ["Mild dehydration of superficial stratum corneum", "Normal facial expressions and blinking"], "score_explanation": "Under PPL/XPL there are faint peri‑orbital fine lines without clear etched creases; wrinkle depth and density appear very low (depth index <0.25; density <0.2). This corresponds to Very Mild (Grade 1).", "affected_area_image": "2"}, "skin_sensitivity_scoring": {"description": "This parameter assesses the skin\'s reactivity to external stimuli, such as skincare products, environmental factors, and touch.", "parameter_name": "Skin Sensitivity Scoring", "score_or_label": "1", "possible_causes": ["Reactive capillaries to heat or cleansing", "Mild barrier dehydration increasing reactivity"], "score_explanation": "Red/XPL views show mild erythema around the nose and central cheeks without dense vascular patterns; barrier uniformity appears slightly disrupted in PPL with minor patchiness and no overt flaking. These correspond to erythema 0.25–0.45 and low vascular pattern index, giving Mild sensitivity (Score 1).", "affected_area_image": "6"}, "regional_oil_distribution": {"description": "Distribution mapping of oil secretion across facial zones, highlighting T-zone vs U-zone differences.", "parameter_name": "Regional Oil Distribution (White / UV)", "score_or_label": "1", "possible_causes": ["Higher sebaceous gland density in T‑zone", "Heat/humidity increasing central facial oil"], "score_explanation": "UV fluorescence and white‑mode shine are concentrated on the nose and central forehead with relatively matte cheeks; left‑right symmetry is acceptable. This pattern corresponds to a T‑zone predominant distribution (regional_variance_index ~0.2–0.4), i.e., Score 1.", "affected_area_image": "4"}, "skin_luminosity_glow_index": {"description": "Quantitative evaluation of skin radiance and uniformity under white and parallel polarized light.", "parameter_name": "Skin Luminosity / Glow Index (White / PPL)", "score_or_label": "1", "possible_causes": ["Dehydration reducing light diffusion", "Textural and pigment mottling dulling reflectance"], "score_explanation": "White/PPL views show moderate surface reflectance uniformity (≈0.5–0.7) with patchy brightness and limited subsurface diffusion; shadow contrast is moderate. These map to Mild Glow (Score 1) rather than healthy radiant.", "affected_area_image": "1"}, "texture_open_pores_grading": {"description": "This parameter evaluates the skin\'s texture, including the visibility of open pores.", "parameter_name": "Texture + Open Pores Grading", "score_or_label": "Grade 2", "possible_causes": ["T‑zone oiliness enlarging pore appearance", "Past comedonal activity causing mild texture roughness"], "score_explanation": "PPL images show visible pores on the nose and medial cheeks with lateral extension but not widespread; estimated pore_diameter_ratio falls around 1.3–1.6 and texture_uniformity ~0.6–0.8 with minor specular unevenness in white light. These match the Mild (Grade 2) category.", "affected_area_image": "2"}, "vascularity_redness_profiling": {"description": "Mapping of visible and sub-dermal redness, capillary dilation, and vascular congestion using cross-polarized or red light imaging.", "parameter_name": "Vascularity / Redness Profiling (XPL / Red Light)", "score_or_label": "1", "possible_causes": ["Transient flushing or heat exposure", "Barrier dehydration increasing visibility of capillaries"], "score_explanation": "Red/XPL imaging shows faint diffuse redness over central cheeks and nose with sparse vessel patterns and largely even color uniformity. Indices align with mild erythema (0.25–0.45) and low vascular density (<0.4), mapping to Score 1 – Mild.", "affected_area_image": "6"}, "superficial_pigmentation_score": {"description": "This parameter measures the amount of superficial pigmentation, such as sun spots, age spots, and post-inflammatory hyperpigmentation (PIH), on the skin\'s surface.", "parameter_name": "Superficial Pigmentation Score", "score_or_label": "3 - Moderate", "possible_causes": ["Cumulative UV exposure without adequate sunscreen", "Post‑inflammatory hyperpigmentation from acne"], "score_explanation": "Brown mode shows multiple macules and patches over forehead, malar areas, nose bridge and perioral region with mottled tone; estimated coverage ~20–40% of face with moderate intensity and uneven borders. UV enhances some areas slightly, suggesting a mixed but mainly epidermal component. This pattern aligns with the score-3 criteria (moderate coverage, intensity 0.50–0.65, and contrast uniformity in the 0.65–0.80 range).", "affected_area_image": "7"}, "texture_irregularities_beyond_pores": {"description": "Identification of micro-surface irregularities, roughness, and post-inflammatory marks beyond pore-related texture.", "parameter_name": "Texture Irregularities Beyond Pores (PPL / Brown)", "score_or_label": "2", "possible_causes": ["Post‑inflammatory changes from past acne", "Dehydration‑related superficial roughness"], "score_explanation": "PPL highlights micro‑roughness and mild undulation over cheeks and perioral areas with subtle micro‑shadows; indices correspond to microtexture variance ~0.5–0.7 and surface gradient irregularity ~0.45–0.6, meeting Moderate irregularities (Score 2).", "affected_area_image": "2"}, "under_eye_vascularity_vs_structural_shadows": {"description": "Differentiation between pigmentation, vascular congestion, and anatomical shadowing under the eyes.", "parameter_name": "Under-Eye Vascularity vs Structural Shadows (Peri-orbital Detail)", "score_or_label": "Score 2", "possible_causes": ["Thin lower‑eyelid skin showing vessels", "Early volume deficit along the tear trough"], "score_explanation": "XPL/UV reveal bluish‑purple tone with persistent darkness and a mild tear‑trough shadow; features are more than faint but not severe, consistent with Moderate involvement (Score 2) from vascular pigmentation plus structural shadowing.", "affected_area_image": "8"}}, "treatable_concerns_summary": {"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1-2 (Minimal to Mild)", "current_score": "3 - Moderate", "is_primary_concern": "false"}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0-1", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0-1", "current_score": "Grade 2", "is_primary_concern": "false"}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 (Very Mild/Physiologic)", "current_score": "Grade 1", "is_primary_concern": "false"}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 (Very Mild)", "current_score": "Grade 1", "is_primary_concern": "false"}, {"parameter": "Skin Hydration", "target_score": "0-1 (Excellent to Mild Dehydration)", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Skin Sebum Content", "target_score": "1 (Low-Normal Sebum)", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 (No Sensitivity)", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Barrier Health", "target_score": "0 (Strong / Healthy Barrier)", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate", "is_primary_concern": "false"}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present", "is_primary_concern": "false"}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0 (No Vascularity / Redness)", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0-1", "current_score": "Score 2", "is_primary_concern": "false"}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2-3 (Healthy to Radiant Glow)", "current_score": "1", "is_primary_concern": "false"}, {"parameter": "Comedonal Density", "target_score": "0-1", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0-1", "current_score": "2", "is_primary_concern": "false"}, {"parameter": "Regional Oil Distribution", "target_score": "0 (Even / Balanced)", "current_score": "1", "is_primary_concern": "false"}]}}',
