            'parameters_with_abnormal_scores' => '{"description": "Parameters showing deviations that can be treated or improved with appropriate interventions.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Score", "target_score": "1-2 (Minimal to Mild)", "current_score": "3 - Moderate", "is_primary_concern": false}, {"parameter": "Visual Acne Grading", "target_score": "Grade 0-1", "current_score": "Grade 2", "is_primary_concern": false}, {"parameter": "Texture + Open Pores Grading", "target_score": "Grade 0-1", "current_score": "Grade 2", "is_primary_concern": false}, {"parameter": "Superficial Wrinkles", "target_score": "Grade 1 (Very Mild/Physiologic)", "current_score": "Grade 1", "is_primary_concern": false}, {"parameter": "Jawline Sagging", "target_score": "Grade 1 (Very Mild)", "current_score": "Grade 1", "is_primary_concern": false}, {"parameter": "Skin Hydration", "target_score": "0-1 (Excellent to Mild Dehydration)", "current_score": "2", "is_primary_concern": false}, {"parameter": "Skin Sebum Content", "target_score": "1 (Low-Normal Sebum)", "current_score": "2", "is_primary_concern": false}, {"parameter": "Skin Sensitivity Scoring", "target_score": "0 (No Sensitivity)", "current_score": "1", "is_primary_concern": false}, {"parameter": "Barrier Health", "target_score": "0 (Strong / Healthy Barrier)", "current_score": "1", "is_primary_concern": false}, {"parameter": "PeriOrbital Health", "target_score": "None to Mild", "current_score": "Moderate", "is_primary_concern": false}, {"parameter": "Lip Pigmentation", "target_score": "Absent", "current_score": "Present", "is_primary_concern": false}, {"parameter": "Vascularity / Redness Profiling", "target_score": "0 (No Vascularity / Redness)", "current_score": "1", "is_primary_concern": false}, {"parameter": "Under-Eye Vascularity vs Structural Shadows", "target_score": "Score 0-1", "current_score": "Score 2", "is_primary_concern": false}, {"parameter": "Skin Luminosity / Glow Index", "target_score": "2-3 (Healthy to Radiant Glow)", "current_score": "1", "is_primary_concern": false}, {"parameter": "Comedonal Density", "target_score": "0-1", "current_score": "2", "is_primary_concern": false}, {"parameter": "Texture Irregularities Beyond Pores", "target_score": "0-1", "current_score": "2", "is_primary_concern": false}, {"parameter": "Regional Oil Distribution", "target_score": "0 (Even / Balanced)", "current_score": "1", "is_primary_concern": false}]}',
