                'is_pregnant' => 0,
                'breastfeeding' => 'no',
            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Combination", "possible_causes": ["Sebaceous gland predominance in the T‑zone", "Environmental dehydration and cleansing/shaving routines"], "score_explanation": "Image 1 (white) shows visible pores and mild shine on the nose/medial cheeks with comparatively matte lateral cheeks. Image 5 (UV) demonstrates dense porphyrin fluorescence over the nose and malar areas indicating active sebaceous follicles, while Image 6 (woods) shows scattered dry/keratin speckles on the forehead and cheeks consistent with surface dehydration. Image 3 (positive) highlights pore-edge contrast but not heavy overall gloss. Pattern = oily T‑zone with drier cheeks → Combination type.", "affected_area_image": "1"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "3", "possible_causes": ["Active sebaceous glands in the T‑zone", "Clogged follicles increasing porphyrin fluorescence"], "score_explanation": "Image 3 (positive) shows moderate specular highlights concentrated on the nose/central face; Image 4 (blue) displays limited superficial fluorescence; Image 5 (UV) reveals high porphyrin load on the nose and cheeks; Image 6 (woods) shows follicular debris/congestion. Together these suggest moderate overall sebum with deeper follicular activity rather than excessive surface oil.", "affected_area_image": "4"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "2", "possible_causes": ["T‑zone sebum accumulation with inadequate comedolysis", "Bacterial porphyrin activity within follicles"], "score_explanation": "Image 5 (UV) shows numerous orange-red porphyrin dots clustered on the nose and bilateral malar zones indicating comedonal activity/clogged follicles. Image 1 (white) and Image 3 (positive) show few if any inflamed papules or pustules. Woods (6) supports superficial congestion. Pattern = mild, comedonal-predominant acne with minimal inflammation.", "affected_area_image": "1"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "2", "possible_causes": ["Insufficient moisturizer or harsh cleansers", "Dry indoor climate/air-conditioning exposure"], "score_explanation": "Image 6 (woods) demonstrates scattered bright dry-fluorescence across the forehead and cheeks indicating keratinized dry patches. Image 2 (negative) shows mild micro-line texture on the forehead and cheeks; Image 1 (white) appears slightly matte with reduced plumpness. These findings indicate moderate dehydration.", "affected_area_image": "1"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "2", "possible_causes": ["Surface dryness diminishing smooth reflectance", "Mottled pigmentation reducing perceived brightness"], "score_explanation": "Image 1 (white) shows uneven reflectance with duller cheeks; Image 3 (positive) highlights patchy hotspots rather than a continuous glossy glow. Image 6 (woods) reveals keratin/dryness speckles that reduce optical luminosity. Net effect: mild glow loss.", "affected_area_image": "1"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "insufficient_data", "possible_causes": ["Insufficient lateral view of jawline", "Submental/mandibular contour not fully visible"], "score_explanation": "The front-facing images do not adequately show mandibular contour continuity, pre‑jowl sulcus, or submental profile needed for reliable sag assessment; lateral views are typically required.", "affected_area_image": "1"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "1", "possible_causes": ["Physiologic lip tone within normal range", "Low intrinsic melanin deposition on vermilion"], "score_explanation": "Image 1 (white) shows uniform pink lips without visible darkening; Images 5 and 6 (UV/Woods) do not reveal significant intrinsic melanin or deep fluorescence. Perioral shadowing is minimal. Overall minimal lip pigmentation.", "affected_area_image": "6"}, "textual_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textural Radiance Index", "score_or_label": "3", "possible_causes": ["Keratin/dryness buildup lowering optical smoothness", "Mild texture irregularity and mottled pigment reducing clarity"], "score_explanation": "Images 1 and 3 show fair micro-clarity with some patchy haze; Image 2 (negative) indicates moderate surface scatter from micro-roughness; Image 6 (woods) shows mild-to-moderate keratin fluorescence. Overall radiance is moderate with evident room for improvement.", "affected_area_image": "3"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "3", "possible_causes": ["Allergy/sleep-related fluid retention with vascular pooling", "Surface dehydration accentuating peri-orbital tone"], "score_explanation": "Images 1 and 2 show mild edema/puffiness of the upper eyelids and a faint violaceous hue infraorbitally; no deep tear-trough hollowness or heavy brown pigmentation on Woods/UV. Score reflects moderate concerns driven primarily by vascular tint and edema rather than dense pigment.", "affected_area_image": "2"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "2", "possible_causes": ["Transient irritation or post-shave reactivity", "Barrier dehydration increasing visible redness"], "score_explanation": "Image 1 (white) shows near-neutral overall tone; Image 2 (negative) reveals faint diffuse cheek/eyelid erythema; Image 3 (positive) does not show clear telangiectatic lines; Images 5/6 (UV/Woods) lack strong inflammatory hotspots. This aligns with mild reactive redness rather than structural vascular prominence.", "affected_area_image": "3"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "3", "possible_causes": ["Over-cleansing or frequent shaving causing micro-irritation", "Low humidity/sun exposure leading to surface dehydration"], "score_explanation": "Image 2 (negative) shows mild diffuse erythema and micro-texture roughness over cheeks/eyelids. Image 6 (woods) reveals widespread fine dry-fluorescence speckles (keratin/dehydration). Image 3 (positive) shows slightly uneven reflectance without strong cracks. UV does not reveal intense inflammatory hotspots. Overall this indicates a moderately compromised barrier driven mainly by dehydration with low-to-moderate sensitivity.", "affected_area_image": "2"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "3", "possible_causes": ["Combination skin with T‑zone oil production", "Comedonal congestion enlarging pore appearance"], "score_explanation": "Image 3 (positive) highlights moderate pore diameters and density on the nose and medial cheeks with clear boundaries; Image 1 (white) corroborates visible pores. Images 5/6 (UV/Woods) show comedonal/clogging signals in the same zones, contributing to perceived pore prominence. Outside the T‑zone texture remains relatively even.", "affected_area_image": "3"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "2", "possible_causes": ["Dehydration-related micro-lines", "Early photoaging on the forehead"], "score_explanation": "Image 2 (negative) reveals mild fine-line patterning across the forehead with shallow depth; Image 3 (positive) shows limited edge contrast of lines and no etched furrows; UV (5) does not accentuate chronic deep lines. This represents mild early wrinkles/dehydration lines.", "affected_area_image": "2"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "insufficient_data", "possible_causes": ["Lack of dynamic recoil cues", "Front view limits lower-face firmness estimation"], "score_explanation": "Static front-view images provide limited cues for elastic recoil and regional firmness mapping; no standardized recoil or motion-based signals present to grade accurately.", "affected_area_image": "1"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "3", "possible_causes": ["Cumulative sun exposure causing lentiginous changes", "Post-inflammatory marks following prior breakouts"], "score_explanation": "Image 1 (white) shows scattered brown macules over malar cheeks, nose, and forehead. Image 6 (woods) enhances multiple discrete epidermal clusters compatible with freckles/PIH; Image 3 (positive) shows moderately defined borders. Image 5 (UV) adds only mild depth enhancement, suggesting largely superficial pigment. Overall burden = moderate and mottled.", "affected_area_image": "6"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Skin Hydration Score", "current_score": "2", "is_primary_concern": "true", "reason_for_selection": "Woods shows widespread dry fluorescence with micro-lines on negative mode; hydration typically improves after professional moisturizing/LED/occlusive care.", "target_single_session_score": "3"}, {"parameter": "Visual Acne Grading (v5.1 Spatial)", "current_score": "2", "is_primary_concern": "true", "reason_for_selection": "High UV porphyrin load and comedonal congestion on T‑zone respond quickly to antibacterial/keratolytic cleansing and extractions.", "target_single_session_score": "1"}, {"parameter": "Skin Sebum Index (v6.0)", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Moderate sebum with porphyrins; blue/UV‑guided deep cleanse and BHA can reduce surface oil and follicular congestion in one session.", "target_single_session_score": "2"}, {"parameter": "Superficial Pigmentation Scoring", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Predominantly superficial epidermal macules on Woods; mild lightening achievable with gentle peel/antioxidants/LED.", "target_single_session_score": "2"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Pore prominence is comedone-driven and superficial; extraction/BHA/hydration can reduce visibility promptly.", "target_single_session_score": "2"}, {"parameter": "Vascularity / Redness Scoring (v6)", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild reactive redness without telangiectasia; calming mask + yellow/red LED often downshifts severity.", "target_single_session_score": "1"}, {"parameter": "Skin Luminosity / Glow Index", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Dullness mainly from dryness/keratin; exfoliation + hydration quickly improve reflectance.", "target_single_session_score": "3"}, {"parameter": "Peri-Orbital Health Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Vascular tint/edema may decrease with cooling, lymphatic drainage, and targeted hydration.", "target_single_session_score": "2"}, {"parameter": "Textural Radiance Index", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Radiance limited by keratin/roughness; smoothing/hydrating treatments can improve optical harmony in one visit.", "target_single_session_score": "2"}]}}',
