            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Combination (Fitzpatrick III)", "possible_causes": ["Sebaceous gland density higher in T‑zone", "Environmental dehydration (air‑conditioning, sun exposure) affecting cheeks/forehead"], "score_explanation": "White and PPL views show mild shine and visible pores limited to the T‑zone (nose > central forehead) while cheeks remain matte. Blue mode highlights dotted fluorescence concentrated on the nose with low activity on cheeks. Woods shows scattered dry-keratin specks on forehead/cheeks indicating mild dehydration in non–T‑zone areas. Redness/sensitivity is low in XPL/UV. These patterns map to a combination skin profile with moderate T‑zone oil and mildly dehydrated cheeks.", "affected_area_image": "3"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "3", "possible_causes": ["Physiologic sebaceous activity concentrated in the T‑zone", "Warm climate or daytime occlusion increasing oil film"], "score_explanation": "Blue mode shows moderate dotted fluorescence at the nose and central forehead. White/PPL display mild specular highlights over the T‑zone, while cheeks are relatively matte. UV reveals only a light porphyrin signal. Net result indicates moderate, T‑zone‑focused sebum.", "affected_area_image": "4"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "2", "possible_causes": ["T‑zone sebaceous activity with follicular plugging", "Sunscreen/makeup residue contributing to pore congestion"], "score_explanation": "White/PPL reveal several open comedones across the nose and a few on the cheeks with very few if any inflamed papules. Blue/UV show low porphyrin burden and no strong inflammatory halos. Distribution is T‑zone predominant without clusters—consistent with mild comedonal acne.", "affected_area_image": "3"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "3", "possible_causes": ["Insufficient humectants/occlusives in routine", "Air‑conditioning or sun exposure reducing water content"], "score_explanation": "White/XPL show overall smoothness with decent surface reflectance. Woods reveals scattered dry‑patch fluorescence on forehead and cheeks, and PPL shows minimal micro‑lines. Findings indicate mild dehydration rather than true dryness.", "affected_area_image": "3"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "3", "possible_causes": ["Mild surface dehydration reducing optical scatter", "Pore texture at the nose disrupting uniform highlights"], "score_explanation": "White/PPL show fairly even reflectance with mild shadowing around pores at the nose and subtle dryness‑linked dullness over the forehead. Glow is healthy but limited by minor dehydration and T‑zone texture.", "affected_area_image": "3"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "insufficient_data", "possible_causes": ["Imaging field did not capture full jawline contour", "Assessment requires lateral illumination/angle not provided"], "score_explanation": "Mandibular border and submental region are partially obscured in the frontal capture, limiting measurement of deflection angle, pre‑jowl sulcus depth, and submental fullness. A lateral/oblique view is required for accurate grading.", "affected_area_image": "3"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "2", "possible_causes": ["Physiologic melanin in vermilion border", "Dryness or habitual lip friction causing mild darkening"], "score_explanation": "White shows natural pink lips with slight perimeter darkening. Woods/UV do not demonstrate dense deep melanin; pattern suggests mild intrinsic pigmentation with minimal perioral shadowing.", "affected_area_image": "6"}, "textural_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textual Radiance Index", "score_or_label": "3", "possible_causes": ["Thin oil film and pore texture disrupting highlight uniformity", "Superficial dryness/keratin debris reducing optical clarity"], "score_explanation": "PPL shows fair micro‑clarity with uniform highlights in most zones; XPL reveals mild micro‑shadowing from pores at the nose; Woods detects light keratin fluorescence that can mute glow. Net result is healthy but not maximal radiance.", "affected_area_image": "1"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "2", "possible_causes": ["Natural tear‑trough contour and thin peri‑orbital skin", "Mild dehydration accentuating shadows"], "score_explanation": "XPL/white reveal faint infraorbital shadows with minimal brown discoloration; UV/blue do not show strong vascular pooling. Puffiness is negligible. Mild concerns primarily from slight shadowing/early fine lines.", "affected_area_image": "2"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "2", "possible_causes": ["Transient irritation around the nose (wiping, products)", "Environmental triggers such as heat or spicy foods"], "score_explanation": "In XPL there is faint background redness around the nasal area but cheeks remain mostly neutral. PPL does not show prominent linear vessels or telangiectasia. UV/Woods do not show dense inflammatory hotspots. Pattern is mild/reactive rather than vascular-structural.", "affected_area_image": "1"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "2", "possible_causes": ["Inadequate moisturization leading to superficial dryness", "Intermittent environmental stress (UV, low humidity)"], "score_explanation": "XPL shows minimal diffuse erythema with localized pinkness around the nasal folds. Woods displays scattered fine fluorescent specks on forehead/cheeks consistent with dry keratin and early barrier dryness. Texture remains smooth in PPL with no cracking. Overall picture: mildly compromised barrier with low reactivity.", "affected_area_image": "2"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "3", "possible_causes": ["Higher sebaceous density and elastic fiber stretching in T‑zone", "Comedonal congestion intermittently enlarging pore openings"], "score_explanation": "PPL shows clearly defined pores over the nose and central area; cheeks remain comparatively smooth. XPL indicates mild micro‑roughness but no coarse scarring. This corresponds to moderate pore visibility limited to the T‑zone.", "affected_area_image": "1"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "2", "possible_causes": ["Early dehydration lines", "Dynamic expression lines starting at the outer eye"], "score_explanation": "XPL reveals faint fine lines mainly peri‑orbital; PPL/UV do not show etched deep furrows or chronicity. Lines are mild and likely dehydration‑accentuated rather than structural.", "affected_area_image": "2"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "2", "possible_causes": ["Normal early collagen softening with age", "Subclinical dehydration reducing perceived snap‑back"], "score_explanation": "PPL/white indicate good collagen reflectance uniformity in the cheeks with only mild micro‑laxity patterns on XPL; no significant crepe changes. This suggests mild early elasticity drop, overall firm.", "affected_area_image": "3"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "3", "possible_causes": ["Cumulative UV exposure leading to freckles/lentigines", "Post‑inflammatory marks from prior comedones"], "score_explanation": "White mode shows small brown macules on the cheeks/nose and mottled forehead patches. Woods highlights discrete epidermal clusters consistent with freckles/lentiginous spots; UV does not show deep dermal dominance. Overall moderate superficial pigment burden with even distribution.", "affected_area_image": "6"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Scoring", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Discrete epidermal macules on cheeks/nose and mottled forehead on Woods; largely superficial and responsive to brightening/peel or IPL spot passes.", "target_single_session_score": "2"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Moderate T‑zone pores with low inflammation; extractions/BHA and pore‑focused facial can smooth surface quickly.", "target_single_session_score": "2"}, {"parameter": "Skin Hydration Score", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Woods shows scattered dry patches; hydration is highly treatment‑responsive with humectant infusion and barrier‑repair masks.", "target_single_session_score": "4"}, {"parameter": "Skin Sebum Index", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Blue‑mode fluorescence localized to T‑zone; oil control and deep cleansing can reduce immediate shine.", "target_single_session_score": "2"}, {"parameter": "Visual Acne Grading", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild comedonal activity without inflammation; comedone extraction and keratolytics can quickly reduce visible count.", "target_single_session_score": "1"}, {"parameter": "Vascularity / Redness Scoring", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Only faint nasal redness; calming protocols/LED can visibly reduce reactive erythema.", "target_single_session_score": "1"}, {"parameter": "Skin Luminosity / Glow Index", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Radiance limited by mild dryness and T‑zone texture; polishing + hydration typically produce immediate glow gains.", "target_single_session_score": "4"}, {"parameter": "Peri-Orbital Health Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild shadows with minimal pigment/vascular signal; modest improvement expected with hydration and cooling but structural component limits rapid change.", "target_single_session_score": "2"}, {"parameter": "Lip Pigmentation Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild intrinsic pigmentation; short‑term gains mainly from hydration/exfoliation rather than significant lightening.", "target_single_session_score": "2"}, {"parameter": "Superficial Wrinkles Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Early dehydration lines; small immediate softening expected with moisturization but baseline already mild.", "target_single_session_score": "2"}, {"parameter": "Skin Firmness & Elasticity Index", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Overall firm with mild micro‑laxity; noticeable tightening generally needs a series rather than single session.", "target_single_session_score": "2"}]}}',
