                'allergies' => '["Vitamin C"]',
                'is_pregnant' => 0,
                'breastfeeding' => 'no',
            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Dry", "possible_causes": ["Age-related decline in sebum production", "Environmental dryness and low humectant use"], "score_explanation": "White/positive modes show minimal surface shine across the T‑zone and cheeks; blue mode reveals very low sebum fluorescence and few clogged follicles; pores are generally small to moderate and not actively oily; negative mode reveals fine dehydration lines and a matte appearance—together indicating a dry skin type rather than combination/oily.", "affected_area_image": "1"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "2", "possible_causes": ["Age-related sebaceous downregulation", "Frequent cleansing or low-oil skincare reducing surface lipid film"], "score_explanation": "White/positive modes show little specular shine; blue mode exhibits weak sebum fluorescence; UV displays low porphyrin spots. Distribution is fairly even without oily hotspots—indicating low‑normal sebum rather than true dryness score 1.", "affected_area_image": "4"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "1", "possible_causes": ["Low sebaceous activity overall", "Occasional comedones due to keratin buildup rather than active inflammation"], "score_explanation": "Across white/positive modes there are no clusters of papules or pustules; a few scattered comedonal dots are visible on the nose/cheeks but blue/UV show low porphyrin signal and no inflammatory halos—consistent with minimal acne activity.", "affected_area_image": "1"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "2", "possible_causes": ["Insufficient humectants/occlusives and low water intake", "Barrier lipid depletion with age"], "score_explanation": "White light reveals dullness with reduced surface glow; negative mode highlights fine micro‑lines on forehead, peri‑oral, and under‑eye zones; Woods shows scattered dry fluorescence patches. These indicate moderate dehydration rather than severe deficiency.", "affected_area_image": "1"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "2", "possible_causes": ["Epidermal dryness reducing smooth reflectance", "Superficial pigment mottling causing patchy brightness"], "score_explanation": "White/positive modes show muted reflectance with patchy brightness from superficial pigmentation and dryness; shadow transitions are relatively firm rather than silky, lowering perceived glow.", "affected_area_image": "1"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "4", "possible_causes": ["Soft‑tissue descent from collagen/elastic fiber loss", "Submental fat pad contributing to contour blunting"], "score_explanation": "White light shows reduced mandibular contour with evident jowl formation and pre‑jowl hollow; submental zone appears moderately full. These structural cues indicate marked lower‑face laxity.", "affected_area_image": "1"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "3", "possible_causes": ["Melanin-dominant lip pigmentation", "Cumulative sun exposure of the vermilion"], "score_explanation": "White mode shows clear brownish discoloration of upper and lower lips; Woods/UV reveal intrinsic melanin signal along the vermilion with mild perioral shadowing; no obvious cosmetic overlay pattern—consistent with moderate intrinsic pigmentation.", "affected_area_image": "6"}, "textual_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textural Radiance Index", "score_or_label": "3", "possible_causes": ["Surface dryness increasing scatter", "Pigment mottling reducing uniform glow"], "score_explanation": "Positive mode reveals mild haze with non‑uniform highlights; negative mode indicates moderate scatter from micro‑roughness; Woods shows mild keratin fluorescence. Combined, this yields moderate radiance loss rather than severe dullness.", "affected_area_image": "2"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "4", "possible_causes": ["Mixed pigmentary changes and age-related volume loss", "Chronic photoaging with thin peri‑orbital skin"], "score_explanation": "Prominent infraorbital darkening with brown-gray tone in white light; UV/Woods accentuate pigment; visible tear‑trough demarcation suggests structural hollowness; puffiness is mild. Pigmentation + hollowness primarily drive the score.", "affected_area_image": "3"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "1", "possible_causes": ["Naturally low vascular reactivity", "Well-controlled triggers with minimal irritation"], "score_explanation": "White mode shows minimal clinical erythema; positive mode does not reveal distinct telangiectatic lines; negative mode lacks diffuse background redness; UV/Woods do not show hot inflammatory clusters. Overall redness burden is minimal.", "affected_area_image": "2"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "3", "possible_causes": ["Chronic dehydration and insufficient occlusive/emollient support", "Cumulative photoaging weakening barrier proteins"], "score_explanation": "Negative mode shows uneven microtexture with fine dehydration lines; Woods mode shows scattered dry keratin fluorescence; white light shows minimal overt erythema, suggesting barrier stress from dryness rather than inflammatory sensitivity. Overall pattern fits a moderately compromised barrier with low hydration but limited redness.", "affected_area_image": "3"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "3", "possible_causes": ["Keratin build-up within follicles", "Age-related reduction in skin smoothness"], "score_explanation": "Positive mode shows visible but not enlarged pores on nose and medial cheeks with mild boundary contrast; negative mode indicates moderate micro‑roughness without coarse scarring; blue mode shows few clogged pores. Overall texture is moderately uneven.", "affected_area_image": "2"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "3", "possible_causes": ["Photoaging-related collagen decline", "Dehydration lines superimposed on structural folds"], "score_explanation": "Negative mode highlights fine lines around peri‑orbital region and peri‑oral areas with early etched nasolabial/ marionette folds; white mode shows these visible at conversational distance but not deeply etched—indicating moderate wrinkles.", "affected_area_image": "3"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "4", "possible_causes": ["Dermal collagen fragmentation from chronic photoaging", "Intrinsic aging reducing elastic fiber quality"], "score_explanation": "Negative mode displays micro‑laxity/crepe patterns on cheeks and lower face; white/woods suggest only fair collagen reflectance uniformity; positive-mode edge response implies reduced elastic recoil—together indicating marked firmness decline.", "affected_area_image": "1"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "4", "possible_causes": ["Chronic sun exposure leading to lentigines and mottling", "Age-related melanocyte dysregulation"], "score_explanation": "White mode shows widespread mottled brown macules across cheeks, nose, and forehead; Woods/UV accentuate dense epidermal clusters with uneven distribution and visible borders—consistent with marked superficial pigmentation/photo-damage.", "affected_area_image": "6"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Scoring", "current_score": "4", "is_primary_concern": "true", "reason_for_selection": "Marked epidermal pigment clusters on Woods/white—can lighten and even tone modestly with a single peel/laser-toning session.", "target_single_session_score": "3"}, {"parameter": "Peri-Orbital Health Score", "current_score": "4", "is_primary_concern": "true", "reason_for_selection": "Pigment-dominant dark circles with structural troughs; pigment/vascular components respond partially to brightening + LED, though hollowness remains.", "target_single_session_score": "3"}, {"parameter": "Jawline Sagging Score", "current_score": "4", "is_primary_concern": "true", "reason_for_selection": "Structural laxity with jowls—limited immediate change; needs a course of tightening or lifting modalities.", "target_single_session_score": "4"}, {"parameter": "Skin Hydration Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Dehydration lines and dry fluorescence should respond quickly to hydrating facial, humectants, and occlusives.", "target_single_session_score": "3-4"}, {"parameter": "Skin Luminosity / Glow Index", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Glow limited by dryness and mottling; hydration + gentle exfoliation often give immediate radiance gains.", "target_single_session_score": "3"}, {"parameter": "Barrier Health + Sensitivity (Combined Score)", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Moderate barrier compromise from dryness; soothing barrier-repair session can reduce roughness and reactivity.", "target_single_session_score": "2"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Moderate micro‑roughness; exfoliation/low‑energy resurfacing can smooth texture slightly in one session.", "target_single_session_score": "2-3"}, {"parameter": "Skin Sebum Index", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Low sebum can be balanced with barrier-supportive emollients; shine remains controlled.", "target_single_session_score": "2-3"}, {"parameter": "Superficial Wrinkles Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Hydration and light resurfacing can soften fine lines, while deeper structural lines require longer plans.", "target_single_session_score": "2-3"}, {"parameter": "Lip Pigmentation Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Melanin-dominant lip darkening may improve slightly with targeted brightening/UV protection in one session.", "target_single_session_score": "2-3"}]}}',
