            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Combination", "possible_causes": ["Physiologic sebaceous predominance of the T‑zone", "Environmental dehydration (AC, sun) causing cheek dryness"], "score_explanation": "White (Img1) and PPL-positive (Img3) show clear T‑zone sheen with visible pores on the nose and inner cheeks while the outer cheeks remain matte. Blue mode (Img4) highlights sebum fluorescence concentrated on the nose > cheeks. Woods (Img5) shows scattered fine dry specks on the forehead indicating mild dehydration overlay. Overall pattern = oily T‑zone with relatively normal/drier cheeks.", "affected_area_image": "1"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "3", "possible_causes": ["Physiologic sebaceous activity in T‑zone", "Warm/humid environment increasing oil output"], "score_explanation": "PPL/white (Imgs3/1) show clear specular shine on the nose; Blue mode (Img4) highlights numerous fluorescent dots centered on the nose with lesser cheeks; Woods (Img5) shows focal follicular fluorescence without diffuse oil film. Overall indicates moderate sebum with T‑zone predominance.", "affected_area_image": "4"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "2", "possible_causes": ["T‑zone sebum retention and follicular debris", "Comedogenic residue or inconsistent cleansing"], "score_explanation": "White (Img1) shows a few open comedones/blackheads on the nose and scattered closed comedones on the cheeks; no obvious inflammatory papules or pustules. Blue (Img4) and Woods (Img5) show localized follicular fluorescence on the nose supporting comedonal activity rather than active inflammation.", "affected_area_image": "1"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "3", "possible_causes": ["Inadequate humectants/occlusives in routine", "Air-conditioned environment reducing skin water content"], "score_explanation": "White (Img1) shows overall good surface brightness but not very plump on the forehead. Negative (Img2) indicates smooth micro-topography with mild micro-lines. Woods (Img5) demonstrates scattered dry-fluorescent specks on the forehead and cheeks consistent with surface dehydration. Net: mild dehydration.", "affected_area_image": "1"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "3", "possible_causes": ["Surface dehydration reducing smooth reflectance", "Uneven T‑zone oil distribution causing patchy gloss"], "score_explanation": "White/PPL (Imgs1/3) show healthy overall brightness and fairly uniform reflection with some patchy reduction over the forehead. Woods (Img5) reveals dryness-related specks that slightly dull glow. Result: healthy glow with mild dryness limitation.", "affected_area_image": "1"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "1", "possible_causes": ["Good dermal support and minimal soft‑tissue descent", "Healthy body composition"], "score_explanation": "White (Img1) maintains a continuous mandibular contour without pre‑jowl indentation or submental fullness; negative (Img2) shows no bulging shadows. Indicates taut jawline.", "affected_area_image": "1"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "2", "possible_causes": ["Physiologic melanin at vermilion border", "Sun exposure without lip SPF"], "score_explanation": "White (Img1) shows natural pink lips with faint duskiness, more at the vermilion border. Woods (Img5) and UV (Img6) do not reveal dense deep melanin bands. Overall mild intrinsic pigmentation.", "affected_area_image": "5"}, "textural_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textual Radiance Index", "score_or_label": "2", "possible_causes": ["Light keratin/dead-cell buildup on the forehead", "Uneven T‑zone oil film affecting micro‑clarity"], "score_explanation": "Positive (Img3) and white (Img1) show good clarity and even gloss with slight patchiness over the forehead. Negative (Img2) is smooth, while Woods (Img5) indicates mild keratin specking that subtly reduces radiance. Net: good radiance with minor clarity loss.", "affected_area_image": "3"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "2", "possible_causes": ["Anatomical tear-trough contour creating light shadow", "Minor overnight fluid shifts or fatigue"], "score_explanation": "White/negative (Imgs1/2) show faint infraorbital shadows without pronounced hollowness or puffiness; minimal brown or bluish tint seen. Lines are very fine only. Mild concerns primarily from slight shadowing.", "affected_area_image": "2"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "2", "possible_causes": ["Transient vasodilation around the nose", "Minor irritant exposure or cleansing friction"], "score_explanation": "White (Img1) shows faint redness at the nasal tip only. PPL-positive (Img3) does not reveal prominent linear vessels, and XPL-negative (Img2) lacks diffuse facial erythema. UV/Woods (Imgs6/5) do not show strong inflammatory hotspots. Mild/reactive pattern only.", "affected_area_image": "3"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "2", "possible_causes": ["Under‑moisturizing or over‑cleansing", "Occasional sun/wind exposure reducing barrier lipids"], "score_explanation": "Negative/XPL (Img2) shows generally smooth, even surface without fissuring. Woods (Img5) reveals scattered fine fluorescent specks on the forehead and cheeks consistent with mild dry keratin/dehydration. White (Img1) shows minimal baseline erythema limited to the nasal tip. Pattern fits a mildly compromised barrier from light surface dehydration with low sensitivity.", "affected_area_image": "2"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "2", "possible_causes": ["Sebum retention in the T‑zone", "Comedonal debris widening pore appearance"], "score_explanation": "PPL-positive (Img3) outlines visible but small pores on the nose and medial cheeks; cheeks and forehead remain relatively smooth. Blue (Img4) confirms some clogged pores on the nose. Overall mild pores/texture.", "affected_area_image": "3"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "1", "possible_causes": ["Good intrinsic elasticity and hydration baseline", "Low cumulative photoaging"], "score_explanation": "Negative (Img2) and white (Img1) show minimal fine lines with no etched furrows on the forehead, peri-orbital area, or cheeks. UV (Img6) lacks signs of chronic etched lines.", "affected_area_image": "2"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "1", "possible_causes": ["Preserved collagen/elastin matrix", "Consistent photoprotection or low photoaging"], "score_explanation": "White/PPL (Imgs1/3) show crisp contours without laxity creping; Woods (Img5) and negative (Img2) do not indicate diffuse collagen-loss patterns. Overall high firmness with strong recoil appearance.", "affected_area_image": "1"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "2", "possible_causes": ["Sun exposure leading to freckles/PIH", "Post-inflammatory marks from past comedones"], "score_explanation": "White (Img1) shows scattered small macules on the cheeks, nose, and a few on the forehead. Woods (Img5) accentuates these as discrete superficial clusters rather than large patches. Coverage is limited and intensity light-to-mild.", "affected_area_image": "5"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Barrier Health + Sensitivity (Combined Score)", "current_score": "2", "is_primary_concern": "true", "reason_for_selection": "Woods highlights mild dehydration/keratin specks; hydrating + barrier-repair session can quickly normalize.", "target_single_session_score": "1"}, {"parameter": "Skin Hydration Score", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Scattered dry fluorescence and mild micro-lines suggest surface dehydration responsive to humectants/occlusives and hydration facial.", "target_single_session_score": "4"}, {"parameter": "Skin Sebum Index (v6.0)", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Moderate T‑zone fluorescence; decongesting cleanse/BHA can lower shine and pore fluorescence in one session.", "target_single_session_score": "2"}, {"parameter": "Visual Acne Grading (v5.1 Spatial)", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Primarily comedonal; extraction/BHA can reduce visible comedone count rapidly.", "target_single_session_score": "1"}, {"parameter": "Texture & Open Pores Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild pore visibility centered on nose; cleansing/extraction and smoothing mask can visibly refine.", "target_single_session_score": "1"}, {"parameter": "Vascularity / Redness Scoring (v6)", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild nasal redness often calms with soothing/anti‑inflammatory care or LED.", "target_single_session_score": "1"}, {"parameter": "Superficial Pigmentation Scoring", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Scattered freckles/PIH are light; single session may brighten but unlikely to shift a full grade.", "target_single_session_score": "2"}, {"parameter": "Peri-Orbital Health Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild shadowing/clarity loss can improve with hydration, cooling, and brightening care.", "target_single_session_score": "1"}, {"parameter": "Lip Pigmentation Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild intrinsic pigmentation typically needs multiple sessions; minimal immediate change expected.", "target_single_session_score": "2"}, {"parameter": "Textual Radiance Index", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Keratin specks on Woods suggest quick radiance gains after exfoliation and hydration.", "target_single_session_score": "1"}]}}',
