            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Combination", "possible_causes": ["Physiologic T‑zone sebaceous dominance", "Intermittent moisturization leading to drier cheeks"], "score_explanation": "White (image 2) shows visible pores and mild central shine with comparatively matte cheeks; blue (image 1) concentrates fluorescence at the nose/T‑zone with less activity on the cheeks; negative (image 6) reveals slight micro‑dryness on peri‑oral/cheeks. This mixed oil distribution with mild dehydration aligns with a combination skin type without strong sensitivity spikes.", "affected_area_image": "2"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "3", "possible_causes": ["Physiologic central facial sebaceous activity", "Partial cleansing inefficiency or comedogenic residues at T‑zone"], "score_explanation": "Blue mode (image 1) shows moderate fluorescence and shine mainly at the nose with relatively matte cheeks and forehead; UV/Woods (images 3/4) support localized porphyrin activity but not widespread oil film. This indicates moderate overall sebum with T‑zone predominance.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "2", "possible_causes": ["T‑zone oil and retained keratin causing follicular blockage", "C. acnes porphyrin activity visible under UV/Woods"], "score_explanation": "White (image 2) shows few inflamed lesions; UV/Woods (images 3/4) reveal many small orange‑red fluorescence dots across the nose, chin, and medial cheeks consistent with comedonal/clogged follicles rather than active pustules; clustering is mild. Hence a mild, comedone‑predominant acne pattern.", "affected_area_image": "2"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "3", "possible_causes": ["Insufficient daily humectants/occlusives", "Low ambient humidity or air‑conditioning exposure"], "score_explanation": "White (image 2) shows moderate surface reflectance without a dewy sheen; negative (image 6) reveals fine micro‑lines/roughness around cheeks and peri‑oral area; Woods (image 4) highlights scattered dryness/keratin along the lip margin and chin. These cues indicate mild dehydration rather than severe dryness.", "affected_area_image": "2"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "3", "possible_causes": ["Superficial pigmentation mottling reducing reflectance uniformity", "Mild dehydration and pore texture increasing micro‑shadowing"], "score_explanation": "White and positive (images 2 and 5) show generally even reflectance with some patchy dullness from freckles and peri‑oral darkness; negative (image 6) shows micro‑roughness that scatters light. Overall glow is healthy‑moderate with room for improvement.", "affected_area_image": "2"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "2", "possible_causes": ["Early collagen and elastin softening", "Normal age‑related tissue descent"], "score_explanation": "White (image 2) maintains a largely continuous mandibular contour with only slight softening near the jowl and minimal submental fullness; negative (image 6) does not show pronounced bulging. This corresponds to mild early sagging.", "affected_area_image": "2"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "3", "possible_causes": ["Sun exposure contributing to vermilion border darkening", "Dryness/keratin buildup accentuating perioral shade"], "score_explanation": "White (image 2) shows slightly darker vermilion and perioral margin; Woods/UV (images 4/3) reveal superficial fluorescence along the vermilion border and peri‑oral band, indicating shallow melanin/keratin involvement rather than strong cosmetic overlay. This supports moderate lip pigmentation.", "affected_area_image": "4"}, "textural_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textural Radiance Index", "score_or_label": "3", "possible_causes": ["Keratin/porphyrin speckling diminishing clarity", "Uneven micro‑texture and pigmentation increasing scatter"], "score_explanation": "Positive (image 5) reveals fair clarity yet patchy reflectance from pores and freckles; negative (image 6) shows micro‑roughness; woods (image 4) shows keratin/porphyrin speckling that contributes to haze. Radiance is moderate with clear upside.", "affected_area_image": "5"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "3", "possible_causes": ["Mixed melanin and vascular tint of thin infraorbital skin", "Anatomical tear‑trough shadowing"], "score_explanation": "White (image 2) and negative (image 6) show visible under‑eye darkness with soft trough shadowing; blue/UV (images 1/3) suggest a vascular‑brown mix rather than pronounced edema; fine lines are mild. Overall indicates moderate peri‑orbital concern dominated by pigment/shadow.", "affected_area_image": "6"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "2", "possible_causes": ["Transient dryness‑related flushing", "Sun exposure history with low‑grade vascular reactivity"], "score_explanation": "White and PPL-positive (images 2 and 5) show only faint cheek erythema without visible telangiectatic lines; negative (image 6) reveals mild diffuse background tone but not widespread erythema; UV/Woods (images 3/4) lack dense inflammatory hotspots. This fits mild reactive redness.", "affected_area_image": "5"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "3", "possible_causes": ["Inadequate lipid barrier support and environmental drying", "Subclinical congestion maintaining micro‑irritation"], "score_explanation": "Negative (image 6) shows mild micro‑texture and faint dryness around the cheeks and peri‑oral zone; Woods/UV (images 4/3) show scattered keratin/porphyrin speckling but no confluent inflammatory plaques; white (image 2) shows slight cheek erythema only on close inspection. Overall pattern indicates moderate, dryness‑leaning barrier compromise with low‑to‑moderate reactivity.", "affected_area_image": "6"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "3", "possible_causes": ["T‑zone sebum activity enlarging pore appearance", "Retained keratin and comedones maintaining texture"], "score_explanation": "Positive (image 5) emphasizes moderate pore visibility on the nose and medial cheeks; blue/UV (images 1/3) show fluorescence in several follicles indicating clogging; forehead/outer cheeks remain smoother. Net burden is moderate.", "affected_area_image": "5"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "2", "possible_causes": ["Suboptimal hydration enhancing micro‑lines", "Early photoaging with repeated expressions"], "score_explanation": "Negative (image 6) shows mild fine lines around peri‑orbital/peri‑oral zones; white (image 2) lacks deep etched furrows; UV (image 3) does not show chronic deep lines. This pattern fits mild superficial/dehydration lines.", "affected_area_image": "6"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "2", "possible_causes": ["Early photoaging of collagen matrix", "Chronic mild dehydration reducing elastic snap"], "score_explanation": "Positive (image 5) shows soft edge transitions without strong recoil cues at the lower face; white + woods (images 2/4) suggest mild diffuse collagen uniformity drop but no marked laxity. Overall reflects mild firmness/elasticity decline.", "affected_area_image": "2"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "4", "possible_causes": ["Cumulative sun exposure causing freckles/lentiginous changes", "Post‑inflammatory hyperpigmentation from prior comedones"], "score_explanation": "Woods (image 4) highlights dense clusters of bright epidermal macules on the nose, malar cheeks, and peri‑oral area; UV (image 3) and white (image 2) confirm widespread freckles/mottling with sharp borders. Coverage and density are high, consistent with marked superficial pigment load.", "affected_area_image": "4"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Scoring", "current_score": "4", "is_primary_concern": "true", "reason_for_selection": "Dense Woods/UV macules over nose and cheeks indicate marked epidermal pigment that typically lightens with brightening peels/laser toning and strict SPF.", "target_single_session_score": "3"}, {"parameter": "Skin Hydration Score", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Negative and Woods show dryness/keratin; hydration often responds quickly to humectant + occlusive + barrier repair treatments.", "target_single_session_score": "4"}, {"parameter": "Skin Luminosity / Glow Index", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Glow limited by dryness and mottled pigment; exfoliation, decongestion, and hydration usually yield notable immediate improvement.", "target_single_session_score": "4"}, {"parameter": "Textural Radiance Index", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Keratin/porphyrin speckling and fine roughness reduce clarity; a decongesting facial/BHA and hydrating LED typically boost radiance promptly.", "target_single_session_score": "4"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Moderate pore visibility with clogging on T‑zone can improve after extractions and BHA/retinoid initiation.", "target_single_session_score": "2"}, {"parameter": "Peri-Orbital Health Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Mixed pigment/shadow pattern may show early brightening and hydration benefits around the infraorbital area.", "target_single_session_score": "2"}, {"parameter": "Lip Pigmentation Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Shallow vermilion/perioral pigmentation and keratin accentuation often respond to gentle exfoliation and SPF protection.", "target_single_session_score": "2"}, {"parameter": "Skin Sebum Index", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Moderate T‑zone sebum and porphyrins typically decrease after deep cleansing/BHA and antibacterial steps.", "target_single_session_score": "2"}, {"parameter": "Visual Acne Grading", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Comedonal, low‑inflammation acne may partially decongest after a session, but grading often stays mild while counts reduce.", "target_single_session_score": "2"}, {"parameter": "Vascularity / Redness Scoring", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild reactive redness; calming LED and barrier repair can reduce flares though baseline severity is already low.", "target_single_session_score": "2"}, {"parameter": "Skin Firmness & Elasticity Index", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Early firmness changes; single session yields subtle improvements, series required for noticeable lift.", "target_single_session_score": "2"}, {"parameter": "Jawline Sagging Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild early contour softening; meaningful change usually needs a treatment series.", "target_single_session_score": "2"}, {"parameter": "Superficial Wrinkles Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Fine dehydration lines may soften after hydration in one session but overall severity is already mild.", "target_single_session_score": "2"}]}}',
