                'parameters_with_abnormal_scores' => '{"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Scoring", "current_score": "4", "is_primary_concern": false, "reason_for_selection": "Dense Woods/UV macules over nose and cheeks indicate marked epidermal pigment that typically lightens with brightening peels/laser toning and strict SPF.", "target_single_session_score": "3"}, {"parameter": "Skin Hydration Score", "current_score": "3", "is_primary_concern": false, "reason_for_selection": "Negative and Woods show dryness/keratin; hydration often responds quickly to humectant + occlusive + barrier repair treatments.", "target_single_session_score": "4"}, {"parameter": "Skin Luminosity / Glow Index", "current_score": "3", "is_primary_concern": false, "reason_for_selection": "Glow limited by dryness and mottled pigment; exfoliation, decongestion, and hydration usually yield notable immediate improvement.", "target_single_session_score": "4"}, {"parameter": "Textural Radiance Index", "current_score": "3", "is_primary_concern": false, "reason_for_selection": "Keratin/porphyrin speckling and fine roughness reduce clarity; a decongesting facial/BHA and hydrating LED typically boost radiance promptly.", "target_single_session_score": "4"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": false, "reason_for_selection": "Moderate pore visibility with clogging on T‑zone can improve after extractions and BHA/retinoid initiation.", "target_single_session_score": "2"}, {"parameter": "Peri-Orbital Health Score", "current_score": "3", "is_primary_concern": false, "reason_for_selection": "Mixed pigment/shadow pattern may show early brightening and hydration benefits around the infraorbital area.", "target_single_session_score": "2"}, {"parameter": "Lip Pigmentation Score", "current_score": "3",