                'breastfeeding' => 'no',
            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Dry", "possible_causes": ["Age-related reduction in sebaceous output", "Low ambient humidity or insufficient emollient use"], "score_explanation": "White (Img2) and positive (Img3) views show a matte surface with minimal T‑zone shine; blue mode (Img1) shows low sebum fluorescence and few oily hotspots. Negative mode (Img5) reveals micro-dryness and fine micro-lines, and Woods (Img6) shows scattered dry keratin fluorescence. Pores are only mildly active around the nose. These patterns map to low sebum with a measurable hydration deficit → Dry skin type without strong sensitivity/photo-reactivity signals.", "affected_area_image": "2"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "2", "possible_causes": ["Age-related sebaceous decline", "Frequent cleansing or alcohol-based products reducing surface oil"], "score_explanation": "Blue mode (Img1) shows low fluorescence with sparse oily hotspots; white/positive (Imgs2–3) display minimal specular shine, mainly a matte finish. UV (Img4) shows low porphyrin count and Woods (Img6) shows limited congestion clusters. → Low‑normal sebum.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "1", "possible_causes": ["Occasional follicular congestion at the nose", "Cosmetic residue or environmental debris"], "score_explanation": "White (Img2) and positive (Img3) do not show inflamed papules or pustules; only a few small comedonal plugs are visible on the nose. Blue (Img1) and UV (Img4) show low porphyrin signal and no inflammatory clusters. No nodules detected. → Minimal acne.", "affected_area_image": "2"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "2", "possible_causes": ["Insufficient use of humectants/occlusives", "Environmental dryness and photoaging"], "score_explanation": "White (Img2) shows reduced surface glow and slight dullness; negative (Img5) reveals increased micro-line density and micro-roughness; Woods (Img6) demonstrates scattered dry keratin fluorescence. Blue (Img1) indicates low sebum support. Overall pattern indicates moderately low hydration.", "affected_area_image": "2"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "2", "possible_causes": ["Surface dryness and microtexture scatter", "Superficial pigmentation reducing uniform brightness"], "score_explanation": "White (Img2) shows uneven reflectance with muted brightness; positive (Img3) shows limited, patchy highlights rather than uniform gloss. Negative (Img5) exhibits micro-shadowing from texture/dryness, and Woods (Img6) shows keratin fluorescence reducing optical clarity. → Mild glow only.", "affected_area_image": "2"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "3", "possible_causes": ["Dermal collagen thinning and ligament laxity with age", "Gravity-related soft tissue descent"], "score_explanation": "White (Img2) reveals softening of the mandibular border with early jowl formation and mild submental heaviness; negative mode (Img5) accentuates contour shadowing along the marionette area. The features represent moderate lower-face sagging rather than marked descent.", "affected_area_image": "2"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "3", "possible_causes": ["Chronic sun exposure without lip SPF", "Constitutional melanin tendency with age"], "score_explanation": "White (Img2) shows visible brown tone of the vermilion; Woods (Img6) demonstrates defined melanin signal across both lips; UV (Img4) confirms an intrinsic component rather than surface stain. Distribution is fairly uniform without intense congestion → Moderate lip pigmentation.", "affected_area_image": "6"}, "textural_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textural Radiance Index", "score_or_label": "3", "possible_causes": ["Surface dryness and keratin buildup", "Mottled pigmentation reducing uniform reflectance"], "score_explanation": "Positive (Img3) indicates non-uniform specular highlights; negative (Img5) reveals micro-shadow scatter from texture; Woods (Img6) shows keratin fluorescence contributing to haze. Overall effect produces moderate radiance loss.", "affected_area_image": "3"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "4", "possible_causes": ["Mixed melanin and vascular pooling in thin under‑eye skin", "Volume loss/tear‑trough shadowing with age"], "score_explanation": "White (Img2) and negative (Img5) show pronounced infraorbital darkening with clear boundary and multiple fine lines; UV/blue (Imgs4 & 1) add a bluish/vascular component, and Woods (Img6) highlights brown pigmentation along the lower lids. Minimal edema but visible hollowness shadows. → Significant peri‑orbital concerns dominated by pigment + vascular mix.", "affected_area_image": "5"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "2", "possible_causes": ["Barrier dehydration increasing transient reactivity", "Sun exposure increasing superficial vascular tone"], "score_explanation": "White (Img2) shows only faint cheek/alar erythema. Positive (Img3) does not reveal prominent telangiectasia. Negative (Img5) shows mild diffuse background tone variation rather than intense redness. UV/Woods (Imgs4 & 6) show limited inflammatory hotspots. → Mild reactive redness.", "affected_area_image": "3"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "3", "possible_causes": ["Under-moisturizing and cleanser-induced lipid removal", "Cumulative photoaging weakening barrier proteins"], "score_explanation": "Negative mode (Img5) shows uneven microtexture with fine micro-lines and scattered rough patches; Woods (Img6) shows keratin/dryness fluorescence in multiple zones. White (Img2) shows mild dullness without strong erythema. UV (Img4) shows only small hotspots of subclinical inflammation. Overall pattern = moderate dehydration/texture disruption with low-to-moderate sensitivity → Moderately Compromised.", "affected_area_image": "5"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "3", "possible_causes": ["Age-related collagen support decline around follicular walls", "Dryness-related micro-roughness accentuating pore appearance"], "score_explanation": "Positive mode (Img3) shows mild-to-moderate pore edge visibility on nose and medial cheeks with scattered roughness; negative mode (Img5) confirms micro-roughness patches, while blue (Img1) shows limited clogging fluorescence. → Moderate pores/texture.", "affected_area_image": "3"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "3", "possible_causes": ["Dehydration emphasizing micro-lines", "Progressive collagen/elastin loss with photoaging"], "score_explanation": "Negative mode (Img5) highlights multiple fine lines under the eyes, peri-oral creases, and forehead micro-lines; white (Img2) shows these are visible at conversational distance mainly peri‑orbital and nasolabial. Depth appears mild-to-moderate without deep etched grooves. → Moderate wrinkles.", "affected_area_image": "5"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "3", "possible_causes": ["Photoaging-driven collagen decline", "Reduced elastic fiber quality with age"], "score_explanation": "Negative (Img5) shows mild crepe-like micro-laxity on cheeks; white/woods (Imgs2 & 6) indicate uneven collagen-linked reflectance; positive (Img3) shows softer recoil patterns at lower face transitions. These signs align with a moderate decline in firmness/elasticity.", "affected_area_image": "2"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "4", "possible_causes": ["Chronic sun exposure/photoaging (lentiginous changes)", "Hormonal/age-related melanin regulation shifts leading to mottling"], "score_explanation": "White (Img2) shows numerous brown macules/patches over malar, temples, and peri-oral areas. Woods (Img6) enhances these as dense epidermal clusters with mottling. UV (Img4) shows additional subclinical accentuation under cheeks/infraorbital. Coverage and intensity are high with mottled uniformity → Marked superficial pigment load.", "affected_area_image": "6"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Barrier Health + Sensitivity", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Moderate dehydration/keratin fluorescence and micro-roughness suggest barrier repair can quickly reduce burden.", "target_single_session_score": "2"}, {"parameter": "Skin Hydration Score", "current_score": "2", "is_primary_concern": "true", "reason_for_selection": "Hydration markers indicate responsiveness to humectant/occlusive therapy and hydrating facial.", "target_single_session_score": "3"}, {"parameter": "Skin Luminosity / Glow Index", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Dullness largely from dryness/keratin; exfoliation and hydration typically improve glow within one session.", "target_single_session_score": "3"}, {"parameter": "Superficial Pigmentation Scoring", "current_score": "4", "is_primary_concern": "true", "reason_for_selection": "Dense Woods-mode epidermal clusters indicate superficial component that responds to peels/laser toning.", "target_single_session_score": "3"}, {"parameter": "Peri-Orbital Health Score", "current_score": "4", "is_primary_concern": "true", "reason_for_selection": "Mixed pigment/vascular dark circles with texture lines; cooling/yellow LED and brightening agents can provide noticeable early gains.", "target_single_session_score": "3"}, {"parameter": "Lip Pigmentation Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Woods/UV show superficial melanin; gentle peel/brightening balm can lighten appearance quickly.", "target_single_session_score": "2"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Moderate pores/roughness with low clogging; superficial smoothing treatments are effective short-term.", "target_single_session_score": "2"}, {"parameter": "Superficial Wrinkles Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Dehydration lines dominate; hydration/LED can soften line appearance.", "target_single_session_score": "2"}, {"parameter": "Jawline Sagging Score", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Structural laxity typically needs multiple sessions; minimal immediate change expected.", "target_single_session_score": "3"}, {"parameter": "Skin Firmness & Elasticity Index", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Moderate firmness decline; tightening modalities need a series for visible improvement.", "target_single_session_score": "3"}, {"parameter": "Textural Radiance Index", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Radiance limited by surface haze/keratin which respond quickly to exfoliation and hydration.", "target_single_session_score": "2"}, {"parameter": "Skin Sebum Index", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Low sebum with dryness; barrier-supporting emollients can rebalance sheen without oiliness.", "target_single_session_score": "3"}, {"parameter": "Vascularity / Redness", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild reactive redness should calm with barrier repair and anti-inflammatory LED.", "target_single_session_score": "1"}]}}',
