            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Combination", "possible_causes": ["Central sebaceous activity exceeding cheeks", "Mild surface dehydration increasing contrast between T‑zone and periphery"], "score_explanation": "White (1) shows minimal overall shine with visible pores concentrated on the nose. Blue mode (4) reveals numerous fluorescent follicular dots across the T‑zone and medial cheeks, indicating active sebum in central areas, while cheeks/chin look comparatively matte in white (1) and negative (3). Woods (6) shows scattered keratin fluorescence consistent with mild dehydration but not diffuse. UV (5) lacks strong inflammatory hotspots. Combined, this maps to combination skin with oily T‑zone and relatively drier periphery.", "affected_area_image": "1"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "3", "possible_causes": ["Active sebaceous glands in the T‑zone", "Use of occlusive products causing congestion"], "score_explanation": "Blue (4) displays moderate, dense follicular fluorescence across nose/medial cheeks; white/positive (1/2) show mild shine on nose but not generalized. UV (5) indicates mild porphyrin signal. Woods (6) shows some congestion signatures. Overall indicates moderate sebum with central predominance.", "affected_area_image": "4"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "2", "possible_causes": ["Comedonal clogging in T‑zone follicles", "Sebum + keratin buildup without significant inflammation"], "score_explanation": "White (1) reveals few visible comedones mainly on the nose and medial cheeks without clear inflamed papules. Blue (4) shows numerous fluorescent follicular dots (comedonal congestion/porphyrins) concentrated in T‑zone; UV (5) lacks strong inflammatory halos or nodular signals. Lesion load low with a low inflammatory ratio → mild acne.", "affected_area_image": "1"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "3", "possible_causes": ["Inconsistent moisturization or low water intake", "Air‑conditioning/indoor environment increasing TEWL"], "score_explanation": "White (1) shows slightly dull surface with limited glow; Negative (3) reveals fine micro‑lines around peri‑oral/under‑eye zones; Woods (6) shows scattered dry‑patch fluorescence. Blue (4) indicates sebum is present, favoring dehydration over oil‑deficiency. Net result → mild dehydration.", "affected_area_image": "1"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "3", "possible_causes": ["Mild surface dehydration diminishing reflectance", "Keratin micro‑buildup reducing uniform glow"], "score_explanation": "White (1) shows moderate, even reflectance but not high radiance; Positive (2) indicates soft specular highlights with some patchiness; Negative (3) shows mild micro‑shadowing. Woods (6) shows slight keratin fluorescence contributing to dullness. Overall glow is average/healthy with room to improve.", "affected_area_image": "1"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "1", "possible_causes": ["Good soft‑tissue tone and collagen support", "Absence of significant submental fullness"], "score_explanation": "White (1) demonstrates a taut mandibular contour without visible jowl bulge; negative (3) shows no notable pre‑jowl depth or submental heaviness. UV/Woods show no chronic laxity patterns. Overall minimal sagging.", "affected_area_image": "1"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "2", "possible_causes": ["Sun exposure of vermilion border", "Surface dryness accentuating tone unevenness"], "score_explanation": "White (1) shows slightly darker vermilion border and mild uneven tone. Woods (6) and UV (5) indicate shallow melanin signal without deep dermal component; vascular congestion appears low. Overall suggests mild intrinsic pigmentation and dryness rather than deep discoloration.", "affected_area_image": "6"}, "textural_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textural Radiance Index", "score_or_label": "3", "possible_causes": ["Thin keratin film and micro‑texture causing scatter", "Mild dehydration reducing surface clarity"], "score_explanation": "Positive (2) shows moderate micro‑clarity with some patchy highlights; negative (3) reveals mild surface scatter from micro‑texture; woods (6) shows low‑to‑moderate keratin shadowing. Combined these yield a mid‑range radiance score with clear potential to brighten.", "affected_area_image": "2"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "3", "possible_causes": ["Epidermal melanin deposition around periorbital skin", "Subtle vascular tint contributing to darkness"], "score_explanation": "White (1) shows visible dark circles with brown‑gray hue; Negative (3) accentuates shadows but structural hollowness appears mild; UV/Blue (5/4) suggest a vascular/melanin mix without intense pooling. Puffiness minimal. Overall = moderate peri‑orbital concern dominated by pigmentation with a vascular component.", "affected_area_image": "3"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "2", "possible_causes": ["Transient reactivity from dryness or cleansing", "Heat/temperature changes causing temporary flushing"], "score_explanation": "White (1) shows faint background cheek redness only on close view. Positive (2) reveals minimal visible vascular lines; Negative (3) shows slight diffuse erythema, not widespread. UV/Woods (5/6) show few subclinical hotspots. Overall pattern consistent with mild reactive redness.", "affected_area_image": "2"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "2", "possible_causes": ["Inadequate moisturization leading to surface dryness", "Environmental exposure/air‑conditioning causing transient sensitivity"], "score_explanation": "Negative (3) shows slight micro‑roughness around perioral/chin with fine dryness lines; Woods (6) displays scattered keratin fluorescence indicating mild dryness/keratin buildup. White (1) shows minimal erythema and even tone; UV (5) shows no strong inflammatory hotspots. Overall pattern = mildly compromised barrier with low reactivity.", "affected_area_image": "3"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "2", "possible_causes": ["Central sebaceous activity enlarging nasal pores", "Keratin/sebum accumulation in follicles"], "score_explanation": "Positive (2) and white (1) show fine‑to‑moderate pores mainly on the nose with relatively smooth cheeks. Blue (4) highlights some clogged pores in the T‑zone, but negative (3) shows generally smooth micro‑topography. Hence mild pores/texture burden.", "affected_area_image": "2"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "2", "possible_causes": ["Surface dehydration accentuating micro‑lines", "Normal expression lines beginning to appear"], "score_explanation": "Negative (3) reveals fine micro‑lines around the peri‑orbital region and subtle forehead lines; Positive (2) shows shallow edge contrast; UV (5) does not indicate chronic etched patterns. Overall mild superficial/dehydration lines.", "affected_area_image": "3"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "2", "possible_causes": ["Early collagen softening typical with dehydration", "Minor micro‑laxity patterns without structural sag"], "score_explanation": "Negative (3) shows faint micro‑laxity patterns on cheeks; white/woods (1/6) indicate fairly uniform collagen reflectance; positive (2) suggests decent recoil with soft shadow edges. Interpreted as mild early elasticity drop only.", "affected_area_image": "1"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "2", "possible_causes": ["Sun exposure causing light freckling/tan", "Post‑inflammatory marks from prior minor breakouts"], "score_explanation": "White (1) shows mild tone unevenness on forehead and cheeks. Woods (6) reveals scattered superficial pigment/keratin dots without dense clusters; borders are soft on positive/negative (2/3). UV (5) does not show strong deep enhancement. Net perceived superficial pigment load is mild.", "affected_area_image": "6"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Barrier Health + Sensitivity (Combined Score)", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild dryness/keratin fluorescence on Woods and micro‑roughness on negative; typically improves quickly with barrier‑repair hydration.", "target_single_session_score": "1"}, {"parameter": "Visual Acne Grading (v5.1 Spatial)", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Comedonal fluorescence in T‑zone without inflammation; decongestion/clarifying session can reduce lesion load.", "target_single_session_score": "1"}, {"parameter": "Skin Sebum Index (v6.0)", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Moderate blue‑mode fluorescence and T‑zone shine suggest manageable sebum burden responsive to deep cleansing/BHA.", "target_single_session_score": "2"}, {"parameter": "Skin Hydration 