            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "insufficient_data", "possible_causes": ["Insufficient visibility of regional oil/hydration patterns", "Lack of clear UV/Woods contrast for sensitivity and pigment response"], "score_explanation": "Cross-mode indicators for sebum distribution (blue/white), hydration deficit (woods/negative), pore activity (positive/white), barrier integrity (woods), sensitivity (white/UV), and photo-reactivity (UV vs white) are not discernible from the provided images, preventing reliable composite skin type and Fitzpatrick determination.", "affected_area_image": "1"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "insufficient_data", "possible_causes": ["Weak or ambiguous blue-mode fluorescence for sebum", "Lack of measurable specular shine patterns"], "score_explanation": "Specular highlights (white/positive), blue-mode sebum fluorescence, UV porphyrins, and Woods congestion patterns are not quantifiable; SSI, regional sebum map, and hotspot grid cannot be determined.", "affected_area_image": "4"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "insufficient_data", "possible_causes": ["No clear comedone or papule/pustule signatures", "Insufficient UV porphyrin hotspots to map activity"], "score_explanation": "Lesion morphology and porphyrin activity are not reliably visible across white/blue/UV modes; per-lesion coordinates, cluster analysis, and ASI cannot be produced without discernible comedones or inflammatory lesions.", "affected_area_image": "1"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "insufficient_data", "possible_causes": ["Fine micro-line and dry-patch cues not visible", "Subsurface diffusion signals not measurable"], "score_explanation": "Surface reflectance uniformity, micro-line density (positive/negative), diffusion (white/UV), and Woods dry-patch fluorescence are not extractable to compute HSI or regional hydration mapping.", "affected_area_image": "1"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "insufficient_data", "possible_causes": ["Inadequate specular uniformity/brightness data", "No reliable dryness-dullness fluorescence signal"], "score_explanation": "Key inputs—surface reflectance uniformity, LAB L-channel brightness, shadow softness, sebum gloss evenness, and Woods dryness-dullness—lack discernible patterns, preventing GLI computation.", "affected_area_image": "1"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "insufficient_data", "possible_causes": ["Jawline contours and shadow edges not well defined", "Submental profile cues not clearly captured"], "score_explanation": "Mandibular deflection, pre-jowl sulcus depth, jowl bulge prominence, and submental fullness are not consistently measurable across white/positive/negative modes; JSI cannot be computed.", "affected_area_image": "1"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "insufficient_data", "possible_causes": ["Lip region not clearly delineated across modes", "Potential cosmetic overlay cannot be excluded"], "score_explanation": "Intrinsic melanin (UV/Woods), surface darkness (white/negative), and vascular congestion cannot be separated confidently; lipstick masking and depth profiling are indeterminate.", "affected_area_image": "6"}, "textural_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textural Radiance Index", "score_or_label": "insufficient_data", "possible_causes": ["Surface clarity/shine patterns not measurable", "Keratin congestion fluorescence not evident"], "score_explanation": "Micro-clarity (white/positive), smooth scatter (negative), and Woods keratin-shadow signatures are not sufficiently visible to compute TRI or regional radiance mapping.", "affected_area_image": "2"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "insufficient_data", "possible_causes": ["Under-eye region not captured with adequate contrast", "Shadow and vascular cues indistinct across modes"], "score_explanation": "Infraorbital pigmentation (white/CP/Woods), vascular hue (UV/blue), tear trough shadowing (white/PPL), puffiness (white/CP), and peri-orbital fine lines (PPL) are not clearly visible; weighted severity cannot be assigned.", "affected_area_image": "3"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "insufficient_data", "possible_causes": ["Insufficient vessel-line contrast in positive polarization", "Diffuse/background redness not separable from baseline tone"], "score_explanation": "Clinical erythema (white), PPL vascular lines, XPL diffuse erythema, and UV/Woods hotspots are not clearly delineated; therefore a hierarchical redness severity cannot be assigned.", "affected_area_image": "2"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "insufficient_data", "possible_causes": ["Inadequate microtexture contrast for flaking detection", "Redness and hotspot signals are not clearly visible"], "score_explanation": "Required features such as surface micro-cracks/flaking (negative/positive), Woods-mode keratin fluorescence, and erythema/reactive hotspots (white/UV) are not clearly extractable; therefore BSI and regional barrier/reactivity maps cannot be computed.", "affected_area_image": "3"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pres Score", "score_or_label": "insufficient_data", "possible_causes": ["Insufficient pore boundary definition", "Micro-topography/fluorescence signals not evident"], "score_explanation": "Pore-edge contrast (positive), pore visibility (white), negative-mode roughness, and blue-mode clogging fluorescence are not measurable; TPB and spatial pore maps cannot be computed.", "affected_area_image": "2"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "insufficient_data", "possible_causes": ["Fine-line segmentation not reliable", "Insufficient contrast for wrinkle depth mapping"], "score_explanation": "Wrinkle line count, depth index from positive mode, microline density from negative mode, and UV chronicity signals are not extractable; WBI cannot be calculated.", "affected_area_image": "3"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "insufficient_data", "possible_causes": ["No discernible micro-laxity or recoil signatures", "Collagen-linked reflectance not clearly patterned"], "score_explanation": "Negative-mode micro-laxity patterns, white/Woods collagen reflectance uniformity, and positive-mode elastic recoil cues are not quantifiable; continuous firmness index is indeterminate.", "affected_area_image": "1"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "insufficient_data", "possible_causes": ["No clear macule/freckle clusters under Woods", "UV enhancement vs white not measurable for depth"], "score_explanation": "Pigmented area coverage, mean intensity, mottling, Woods cluster density, and UV:Woods depth indicators are not segmentable; PPL_continuous and regional burden maps cannot be produced.", "affected_area_image": "6"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session."}}',
