            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Combination", "possible_causes": ["Genetic T‑zone sebaceous distribution", "Climate/indoor AC producing cheek dryness"], "score_explanation": "White and positive modes show a mildly shiny T‑zone (nose/central forehead) while cheeks remain relatively matte. Blue/UV modes show porphyrin/comedonal dots concentrated on the nose rather than cheeks, and Woods does not show widespread dryness fluorescence. Overall pattern indicates oil-dominant T‑zone with drier cheeks → combination skin without strong sensitivity spikes.", "affected_area_image": "2"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "3", "possible_causes": ["Genetic sebaceous activity in the T‑zone", "Daytime accumulation of oil and sweat"], "score_explanation": "Blue mode shows limited fluorescence overall with concentration on the nose; positive mode reveals mild specular highlights on the nose/forehead rather than whole-face glow; UV shows moderate porphyrin dots at the nose. This aligns with moderate sebum levels, T‑zone predominant.", "affected_area_image": "1"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "2", "possible_causes": ["Sebum accumulation and follicular congestion in the T‑zone", "Pore occlusion from shaving debris or comedogenic residue"], "score_explanation": "UV/Woods modes show numerous fine porphyrin/comedonal dots focused on the nose with scattered cheek dots; white light displays a small inflamed papule on the central forehead and no nodules or widespread clusters. Pattern indicates mild comedonal acne with occasional inflammatory lesions.", "affected_area_image": "2"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "3", "possible_causes": ["Low ambient humidity/air‑conditioning", "Insufficient use of humectants/occlusives after cleansing"], "score_explanation": "White light shows decent brightness but mild dullness on cheeks and perioral region; negative mode reveals fine micro‑lines around mouth/under‑eye; Woods demonstrates scattered, not dense, dry fluorescence. Findings match mild dehydration with room for improvement.", "affected_area_image": "2"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "3", "possible_causes": ["Mild dehydration decreasing surface smoothness", "Mottled superficial pigmentation reducing uniform brightness"], "score_explanation": "Surface reflectance is generally even with some patchy loss of glow over the cheeks; positive mode shows controlled highlights without oily patchiness; Woods indicates mild dryness that slightly reduces radiance. Net result: healthy but not radiant glow.", "affected_area_image": "2"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "2", "possible_causes": ["Early soft‑tissue laxity", "Posture or gravity‑related tissue descent over time"], "score_explanation": "White mode shows a mostly defined mandibular contour with minimal submental fullness and no pronounced jowl bulge; negative mode does not reveal deep pre‑jowl sulcus. Consistent with mild early laxity only.", "affected_area_image": "2"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "2", "possible_causes": ["Sun exposure to the vermilion", "Post‑shave/irritation‑related perioral darkening"], "score_explanation": "White light shows a natural pink lip with slight central duskiness; Woods/UV show mild intrinsic melanin signal along the vermilion without deep or extensive involvement. Perioral shadowing is faint.", "affected_area_image": "6"}, "textural_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textural Radiance Index", "score_or_label": "2", "possible_causes": ["Light keratin build‑up reducing perfect clarity", "Mild hydration deficit on the cheeks"], "score_explanation": "Positive mode shows clear surface with controlled highlights; negative mode indicates good smooth-scatter with only mild micro‑roughness; Woods shows low keratin haze. Together this supports good radiance with minor clarity loss.", "affected_area_image": "5"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "2", "possible_causes": ["Thin peri‑orbital skin with visible vasculature", "Sleep variability or mild dehydration"], "score_explanation": "Minimal brown pigmentation is seen under white/woods; slight bluish/vascular tint under UV/blue with mild trough demarcation but no marked puffiness. Fine lines are subtle. Overall indicates mild peri‑orbital concerns.", "affected_area_image": "3"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "2", "possible_causes": ["Shaving or friction around the nasal/perioral region", "Transient reactivity from dryness or temperature changes"], "score_explanation": "White light shows faint central erythema at the nose and perioral area; negative mode shows only slight diffuse background redness; positive mode does not reveal dense branching telangiectasia; UV/Woods display small inflammatory hotspots limited to the central face. Overall indicates mild, reactive redness rather than structural vascular prominence.", "affected_area_image": "5"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "2", "possible_causes": ["Shaving/razor-induced irritation around the center face", "Intermittent dehydration from cleansing or low humidity"], "score_explanation": "Negative mode shows generally smooth microtexture with only faint irregularity; Woods reveals minimal scattered dry fluorescence without dense scaling; white light shows mild central erythema around the nose/perioral area but not diffuse. These findings are consistent with a mildly compromised but mostly intact barrier.", "affected_area_image": "3"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "3", "possible_causes": ["T‑zone sebum activity enlarging pore appearance", "Debris/oxidized comedones within nasal pores"], "score_explanation": "Positive mode highlights visible pores on the nose and medial cheeks; negative mode shows otherwise fairly smooth texture; blue/UV indicate some clogged pores on the nose. This represents moderate pore visibility with localized congestion.", "affected_area_image": "5"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "2", "possible_causes": ["Early photoaging with mild collagen softening", "Transient dehydration lines"], "score_explanation": "Negative and positive modes show a few fine lines around the peri‑oral/forehead regions without deep etched furrows; UV does not reveal strong chronicity tracks. This aligns with mild superficial wrinkles.", "affected_area_image": "3"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "2", "possible_causes": ["Early collagen/elastic fiber softening", "Cumulative sun exposure"], "score_explanation": "Negative mode shows minimal micro‑laxity/crepe patterns; white/woods display fairly uniform reflectance; positive mode edges are reasonably crisp, suggesting only a mild drop in elastic recoil.", "affected_area_image": "2"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "3", "possible_causes": ["Chronic sun exposure leading to lentiginous speckling", "Post‑inflammatory marks from prior breakouts or irritation"], "score_explanation": "White light shows scattered brown macules on cheeks and forehead; Woods mode accentuates the same clusters and reveals additional speckled epidermal spots; borders are moderately defined and distribution is patchy rather than diffuse. This corresponds to a moderate superficial pigment load.", "affected_area_image": "6"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Scoring", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Woods mode reveals multiple epidermal speckled clusters on cheeks/forehead; superficial pattern is typically responsive to brightening peels, SPF adherence, and targeted topicals.", "target_single_session_score": "2"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Positive and UV modes show localized nasal/medial‑cheek pore visibility and congestion; extractions/BHA or hydrafacial‑type treatments often reduce visibility quickly.", "target_single_session_score": "2"}, {"parameter": "Skin Hydration Score", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Mild dehydration markers (fine micro‑lines and scattered Woods fluorescence) typically improve noticeably after humectant + occlusive hydration and barrier‑support treatments.", "target_single_session_score": "4"}, {"parameter": "Vascularity / Redness Scoring", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Central reactive erythema without prominent vessels often settles with calming, anti‑inflammatory care.", "target_single_session_score": "1"}, {"parameter": "Skin Sebum Index", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "T‑zone shine/porphyrin dots indicate manageable oil and congestion that respond to cleansing optimization and keratolytics.", "target_single_session_score": "2"}, {"parameter": "Visual Acne Grading", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Mild comedonal pattern limited to the nose is amenable to short‑term improvement with extractions and antibacterial steps.", "target_single_session_score": "1"}, {"parameter": "Peri-Orbital Health Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Only mild vascular tint/fine lines; hydration and cooling can enhance appearance but baseline is already good.", "target_single_session_score": "2"}, {"parameter": "Superficial Wrinkles Score", "current_score": "2", "is_primary_concern": "false", "reason_for_selection": "Early fine lines without deep etching; small visible change expected after one session mainly via hydration/smoothing.", "target_single_session_score": "2"}, {"parameter": "Skin Luminosity / Glow Index", "current_score": "3", "is_primary_concern": "false", "reason_for_selection": "Glow is limited by mild dehydration and mottled pigmentation; radiance typically improves quickly with exfoliation + hydration.", "target_single_session_score": "4"}]}}',
