            'parameters_with_abnormal_scores' => '{"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Superficial Pigmentation Scoring", "current_score": "3", "is_primary_concern": true, "reason_for_selection": "Woods mode reveals multiple epidermal speckled clusters on cheeks/forehead; superficial pattern is typically responsive to brightening peels, SPF adherence, and targeted topicals.", "target_single_session_score": "2"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": true, "reason_for_selection": "Positive and UV modes show localized nasal/medial‑cheek pore visibility and congestion; extractions/BHA or hydrafacial‑type treatments often reduce visibility quickly.", "target_single_session_score": "2"}, {"parameter": "Skin Hydration Score", "current_score": "3", "is_primary_concern": true, "reason_for_selection": "Mild dehydration markers (fine micro‑lines and scattered Woods fluorescence) typically improve noticeably after humectant + occlusive hydration and barrier‑support treatments.", "target_single_session_score": "4"}, {"parameter": "Vascularity / Redness Scoring", "current_score": "2", "is_primary_concern": false, "reason_for_selection": "Central reactive erythema without prominent vessels often settles with calming, anti‑inflammatory care.", "target_single_session_score": "1"}, {"parameter": "Skin Sebum Index", "current_score": "3", "is_primary_concern": false, "reason_for_selection": "T‑zone shine/porphyrin dots indicate manageable oil and congestion that respond to cleansing optimization and keratolytics.", "target_single_session_score": "2"}, {"parameter": "Visual Acne Grading", "current_score": "2", "is_primary_concern": false, "reason_for_selection": "Mild comedonal pattern limited to the nose is amenable to short‑term improvement with extractions and antibacterial steps.", "target_single