            'diagnosis' => '{"diagnosis_report": {"skin_type": {"description": "Classifies your skin into oily, dry, combination, or normal based on sebum distribution, shine patterns, pore visibility, and hydration cues across the 6 imaging modes.", "parameter_name": "Skin Type Classification", "score_or_label": "Combination", "possible_causes": ["Physiologic T‑zone sebaceous predominance", "Intermittent congestion from makeup/sunscreen residues or inadequate cleansing"], "score_explanation": "White light (image 5) shows a mostly matte surface on the cheeks with visible pores limited mainly to the nose. Blue/UV/Wood’s (images 2,3,4) reveal clustered porphyrin fluorescence along the T‑zone and medial cheeks indicating active sebum in those regions while lateral cheeks look comparatively drier. Redness signals are low and barrier cues are stable. Overall pattern aligns with combination skin (oilier T‑zone with relatively drier cheeks).", "affected_area_image": "5"}, "skin_sebum_index": {"description": "Quantifies visible shine, blue-mode fluorescence, porphyrin load, and subclinical congestion to assess overall sebum production and distribution.", "parameter_name": "Skin Sebum Index (v6.0)", "score_or_label": "3", "possible_causes": ["T‑zone sebaceous predominance", "Pore blockage maintaining porphyrin load"], "score_explanation": "White/positive (images 5,6) show low‑to‑moderate surface shine overall, but UV/Wood’s (images 3,4) reveal moderate porphyrin load on the nose and central cheeks. Blue mode (image 2) shows uniform blue illumination without heavy glossy flares. Net pattern indicates moderate sebum with focal T‑zone hotspots.", "affected_area_image": "2"}, "visual_acne_grading": {"description": "Assesses acne severity by counting, classifying, and mapping lesions (comedones, papules, pustules, nodules) across the face using white, UV, Woods, blue, and contrast modes.", "parameter_name": "Visual Acne Grading (v5.1 Spatial)", "score_or_label": "3", "possible_causes": ["Follicular congestion with C. acnes activity (porphyrin fluorescence)", "Occlusive products or inconsistent pore‑clearing routines"], "score_explanation": "UV/Wood’s (images 3,4) show numerous orange‑red porphyrin spots concentrated over the nose and medial cheeks, consistent with comedonal activity and a few inflamed lesions. White/positive (images 5,6) reveal scattered comedones and a few small papules; no nodules or widespread pustules observed. Distribution favors T‑zone clusters → moderate acne burden.", "affected_area_image": "5"}, "skin_hydration_score": {"description": "Assesses hydration level by analyzing surface reflectance, smoothness, scattering patterns, and dryness cues in white and negative lighting.", "parameter_name": "Skin Hydration Score", "score_or_label": "3", "possible_causes": ["Insufficient humectants/occlusives", "Environmental dehydration (air‑conditioning, low water intake)"], "score_explanation": "White light (image 5) shows moderate, even reflectance without marked shine; cheeks appear slightly dull compared with the T‑zone. Wood’s (image 4) does not show dense dry‑patch fluorescence. These patterns suggest mild dehydration rather than severe dryness.", "affected_area_image": "5"}, "skin_luminosity_glow": {"description": "Measures radiance, evenness of reflectance, and overall surface optical quality under white and positive-mode lighting.", "parameter_name": "Skin Luminosity / Glow Index", "score_or_label": "3", "possible_causes": ["Mild dehydration reducing surface smooth reflectance", "Superficial pigmentation and congestion muting uniform glow"], "score_explanation": "White and positive (images 5,6) show acceptable brightness but with mild patchy glow reduction from scattered PIH/uneven tone and T‑zone congestion. Shadow transitions are reasonably soft, yielding a healthy but not radiant glow.", "affected_area_image": "5"}, "jawline_sagging_score": {"description": "Assesses jawline definition, tissue descent, and contour smoothness using white & negative-mode structural cues.", "parameter_name": "Jawline Sagging Score", "score_or_label": "2", "possible_causes": ["Early collagen/elasticity softening", "Posture/fluid status variations"], "score_explanation": "White (image 5) displays a largely continuous mandibular contour with minimal submental fullness and no pronounced jowl bulge. Any laxity is early/mild.", "affected_area_image": "5"}, "lip_pigmentation_score": {"description": "Evaluates natural lip pigmentation using Woods, UV, and white modes even when lipstick partially obscures color.", "parameter_name": "Lip Pigmentation Score", "score_or_label": "2", "possible_causes": ["Physiologic melanin at the vermilion", "Sun exposure without lip SPF"], "score_explanation": "White (image 5) shows near‑natural pink tone with mild darkness at the vermilion border. UV/Wood’s (images 3,4) indicate a shallow melanin signal without pronounced vascular pooling. Findings are consistent with mild intrinsic pigmentation.", "affected_area_image": "4"}, "textural_radiance_index": {"description": "Measures optical smoothness, microtexture brightness, and light-scatter harmony across the face.", "parameter_name": "Textural Radiance Index", "score_or_label": "3", "possible_causes": ["Porphyrin/keratin micro‑congestion reducing clarity", "Mild dehydration and superficial pigment mottling"], "score_explanation": "Positive (image 6) shows slight patchy gloss due to T‑zone congestion; white (image 5) shows moderate brightness but reduced uniformity from PIH speckling. Wood’s (image 4) indicates mild keratin/porphyrin scatter contributing to a modest radiance drop. Overall: healthy glow with moderate textural dullness.", "affected_area_image": "6"}, "peri_orbital_health_score": {"description": "Combined assessment of under-eye pigmentation, vascularity, hollowness, and puffiness using multi-light analysis including negative and white mode.", "parameter_name": "Peri-Orbital Health Score", "score_or_label": "3", "possible_causes": ["Epidermal melanin and PIH in the infraorbital zone", "Lifestyle factors (sleep, rubbing) contributing to pigment retention"], "score_explanation": "White (image 5) shows visible brown‑gray dark circles extending to the upper cheek junction with soft shadowing; no marked puffiness. UV/Wood’s (images 3,4) reinforce pigment prominence over vascular glow. Structural hollowness appears mild. Pigmentation is the dominant factor → moderate concern.", "affected_area_image": "1"}, "vascularity_redness_score": {"description": "Evaluates visible erythema, vascular prominence, diffuse redness, and inflammatory hotspots using white, PPL-positive, XPL-negative, UV, and Woods imaging.", "parameter_name": "Vascularity / Redness Scoring (v6)", "score_or_label": "2", "possible_causes": ["Transient reactivity (heat, skincare actives)", "Post‑inflammatory background from prior blemishes"], "score_explanation": "Clinical erythema in white light (image 5) is faint and localized. Positive mode (image 6) does not reveal prominent telangiectasia. UV/Wood’s (images 3,4) lack strong inflammatory clusters. Overall redness is mild/reactive rather than structural.", "affected_area_image": "6"}, "barrier_health_sensitivity": {"description": "Evaluates redness, flaking, micro-irritation, hydration integrity, and overall resilience of the skin barrier using white, Woods, negative-mode, and PPL cues.", "parameter_name": "Barrier Health + Sensitivity (Combined Score)", "score_or_label": "2", "possible_causes": ["Occasional under‑hydration", "Environmental exposure (air‑conditioning, sun)"], "score_explanation": "White (image 5) shows minimal erythema and no obvious scaling. Wood’s/UV (images 4,3) do not show strong inflammatory hotspots; fluorescence is mainly porphyrins rather than barrier‑related dryness. Texture appears mostly uniform on positive mode (image 6). Overall reads as mildly compromised at most, with early dehydration rather than inflammatory sensitivity.", "affected_area_image": "1"}, "texture_open_pores_scoring": {"description": "Assesses pore size, distribution, and surface irregularity using positive-mode and white-light contrast.", "parameter_name": "Texture & Open Pores Score", "score_or_label": "3", "possible_causes": ["Sebum‑driven enlargement and clogging in the T‑zone", "Residual PIH and comedones adding micro‑roughness"], "score_explanation": "Positive mode (image 6) and white (image 5) reveal visible pores over the nose and medial cheeks with scattered comedonal roughness; lateral cheeks remain smoother. No coarse scarring seen. This corresponds to moderate pores/texture.", "affected_area_image": "6"}, "superficial_wrinkles_scoring": {"description": "Measures fine lines, etched lines, and early wrinkle patterns using negative-mode shadow mapping and white-light visibility.", "parameter_name": "Superficial Wrinkles Score", "score_or_label": "2", "possible_causes": ["Early dehydration lines", "Normal expression lines at rest"], "score_explanation": "White/positive (images 5,6) show faint forehead and peri‑orbital fine lines without deep etching. UV (image 3) does not suggest long‑standing chronic etched furrows. Overall mild wrinkle burden mainly from dehydration lines.", "affected_area_image": "1"}, "skin_firmness_elasticity_index": {"description": "Evaluates collagen integrity, recoil patterns, and micro-tension in the skin using positive- and white-mode mapping.", "parameter_name": "Skin Firmness & Elasticity Index", "score_or_label": "2", "possible_causes": ["Early collagen decline", "Subclinical dehydration reducing snap‑back appearance"], "score_explanation": "White and positive (images 5,6) show good contour and edge definition with only subtle softening in the lower face; woods/UV do not indicate significant collagen‑poor zones. Net impression: mild elasticity drop only.", "affected_area_image": "5"}, "superficial_pigmentation_scoring": {"description": "Identifies freckles, tanning, PIH, and pigmentation clusters using Woods and UV imaging plus white-light clinical cues.", "parameter_name": "Superficial Pigmentation Scoring", "score_or_label": "3", "possible_causes": ["Cumulative sun exposure without consistent high‑SPF use", "Post‑inflammatory hyperpigmentation from prior acne"], "score_explanation": "White (image 5) shows numerous small macules and PIH speckles on cheeks, nose and perioral zone. Wood’s (image 4) highlights these as discrete superficial clusters with moderate coverage; UV (image 3) suggests a mostly epidermal component with no deep, confluent patches. Overall perceived load is moderate.", "affected_area_image": "4"}}, "treatable_concerns_summary": {"description": "Parameters showing measurable deviations and their expected improvement after a single treatment session.", "parameters_with_abnormal_scores": [{"parameter": "Visual Acne Grading (v5.1 Spatial)", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Porphyrin clusters on UV/Wood’s indicate active congestion in T‑zone; comedones responsive to pore decongestion, BHA, and antibacterial care.", "target_single_session_score": "2"}, {"parameter": "Skin Sebum Index (v6.0)", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Moderate porphyrin load and T‑zone oil hotspots can reduce quickly with proper cleansing, keratolytics, and blue‑light/antibacterial steps.", "target_single_session_score": "2"}, {"parameter": "Superficial Pigmentation Scoring", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Multiple superficial epidermal macules on Wood’s are amenable to brightening peels/laser‑toning and strict photoprotection.", "target_single_session_score": "2"}, {"parameter": "Texture & Open Pores Score", "current_score": "3", "is_primary_concern": "true", "reason_for_selection": "Medial cheek/nose pore visibility and micro‑roughness improve with exfoliation, pore extraction, and hydration.", "target_single_session_score": "2"